NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Ezekiel'

CHAPTERS = {
    1: {
        1: 'Und es geschah im dreißigsten Jahr im vierten, am fünften des Monats, da ich inmitten der Weggeführten am Flusse Chebar war, daß die Himmel sich öffneten, und ich sah Gesichte Gottes.',
        2: 'Am fünften des Monats - es war das fünfte Jahr der Wegführung des Königs Jojachin, -',
        3: 'Geschah das Wort Jehovahs an Jecheskel, den Sohn Busis, den Priester, im Lande der Chaldäer am Flusse Chebar, und es war allda die Hand Jehovahs auf ihm.',
        4: 'Und ich sah, und siehe, der Wind eines Wetters kam von Mitternacht, eine große Wolke, und ein wirbelndes Feuer, und ein Glanz dabei ringsumher, und aus seiner Mitte wie der Anblick der Glühkohle aus des Feuers Mitte.',
        5: 'Und inmitten ihrer war die Ähnlichkeit von vier Tieren, und ihr Aussehen war: Sie hatten die Ähnlichkeit eines Menschen.',
        6: 'Und vier Gesichter hatte eines, und vier Flügel ein jedes von ihnen.',
        7: 'Und ihre Füße waren ein gerader Fuß, und ihrer Füße Sohle wie die Fußsohle eines Kalbes und schimmernd wie der Anblick von geglättetem Erz.',
        8: 'Und Menschenhände waren unter ihren Flügeln, bei ihren vier Richtungen, und ihrer Angesichter und ihrer Flügel waren je vier.',
        9: 'Aneinander zusammengefügt waren ihre Flügel, und sie wandten sich nicht um bei ihrem Gehen; sie gingen, jeder Mann stracks vor seinem Angesicht.',
        10: 'Und die Ähnlichkeit ihrer Angesichter war eines Menschen Angesicht, und eines Löwen Angesicht zur Rechten der vier und das Angesicht eines Ochsen zur Linken der vier, und das Angesicht eines Adlers für die vier.',
        11: 'Und ihre Angesichter und ihre Flügel waren oben getrennt, jeder Mann hatte zwei zusammengefügte, jeder Mann zwei, die ihre Leiber bedeckten.',
        12: 'Und sie gingen, jeder Mann stracks vor seinem Angesicht; wohin der Geist war zu gehen, gingen sie, sie wandten sich nicht um bei ihrem Gehen.',
        13: 'Und die Ähnlichkeit der Tiere war wie brennende Kohlen des Feuers anzusehen, wie Fackeln anzusehen ging es zwischen den Tieren dahin, und einen Glanz hatte das Feuer, und aus dem Feuer ging Blitz hervor.',
        14: 'Und die Tiere liefen und kehrten zurück, wie der Blitz anzusehen.',
        15: 'Und ich sah die Tiere, und siehe, ein Rad war auf der Erde neben den Tieren, bei ihren vier Gesichtern.',
        16: 'Die Räder und ihr Werk waren anzusehen wie der Anblick des Tharschischsteins, und eine Ähnlichkeit hatten alle vier. Und ihr Aussehen und ihr Werk waren, als ob ein Rad inmitten des Rades wäre.',
        17: 'Nach ihren vier Richtungen gingen sie bei ihrem Gehen; sie wandten sich nicht um bei ihrem Gehen.',
        18: 'Und sie hatten ihre Felgen und ihre Höhe und waren furchtbar; und ihre Felgen voller Augen rings um die vier.',
        19: 'Und beim Gehen der Tiere, gingen die Räder neben ihnen; und wenn die Tiere sich erhoben von der Erde, erhoben sich die Räder.',
        20: 'Wohin der Geist war zu gehen, gingen sie, dahin war der Geist zu gehen. Und die Räder hoben sich samt ihnen; denn der Geist des Tieres war in den Rädern.',
        21: 'Wenn sie gingen, gingen sie; und wenn sie standen, standen sie; und wenn sie sich erhoben von der Erde, erhoben sich samt ihnen die Räder, denn der Geist des Tieres war in den Rädern.',
        22: 'Und über den Häuptern des Tieres die Ähnlichkeit einer Ausbreitung, wie der Anblick von Kristall, furchtbar, ausgespannt oben über ihren Häuptern.',
        23: 'Und unter der Ausbreitung waren ihre Flügel gerade gegeneinander. Jeder Mann hatte zwei, die hier bedeckten, und jeder Mann zwei, die dort bedeckten ihre Leiber.',
        24: 'Und ich hörte die Stimme ihrer Flügel, wie die Stimme vieler Wasser, wie die Stimme des Schaddai. Bei ihrem Gehen war die Stimme des Brausens wie die Stimme des Heerlagers. Bei ihrem Stehen ließen sie ihre Flügel sinken.',
        25: 'Und eine Stimme geschah über der Ausbreitung, die über ihrem Haupte war. Bei ihrem Stehen ließen sie ihre Flügel sinken.',
        26: 'Und oben über der Ausbreitung, die war über ihrem Haupte, wie das Aussehen eines Saphirsteines, die Ähnlichkeit eines Thrones, und auf der Ähnlichkeit des Thrones war eine Ähnlichkeit anzusehen wie ein Mensch oben darauf.',
        27: 'Und ich sah wie den Anblick der Glühkohle, wie das Aussehen eines Feuers innerhalb desselben ringsum; vom Aussehen seiner Lenden und aufwärts, und vom Aussehen seiner Lenden unterwärts sah ich wie das Aussehen von Feuer, und hatte Glanz ringsumher.',
        28: 'Wie das Aussehen des Bogens, der in der Wolke ist am Tag des Platzregens, so war anzusehen der Glanz ringsumher. Es war das Aussehen der Ähnlichkeit der Herrlichkeit Jehovahs. Und ich sah und fiel auf mein Angesicht und hörte die Stimme Eines, Der redete.',
    },
    2: {
        1: 'Und Er sprach zu mir: Menschensohn, stehe auf deine Füße, und Ich will mit dir reden:',
        2: 'Und es kam ein Geist in mich, wie Er zu mir redete, und ließ mich auf meine Füße stehen, und ich hörte Den, Der zu mir redete.',
        3: 'Und Er sprach zu mir: Menschensohn, Ich sende dich zu den Söhnen Israels, zu einer empörerischen Völkerschaft, die sich wider Mich empörte; sie und ihre Väter sind von Mir abgefallen bis auf diesen selbigen Tag.',
        4: 'Und die Söhne sind harten Angesichts und bestärkten Herzens; zu ihnen sende Ich dich, und zu denselben sollst du sprechen: Also spricht der Herr Jehovah.',
        5: 'Und sie, ob sie darauf hören oder es unterlassen, denn sie sind ein widerspenstig Haus, aber sie sollen wissen, daß ein Prophet in ihrer Mitte ist.',
        6: 'Du aber, Menschensohn, sollst dich nicht fürchten vor ihnen, und vor ihren Worten sollst du dich nicht fürchten; zwar sind sie Aufwiegler und Dornen bei dir, und bei Skorpionen wohnst du. Vor ihren Worten sollst du dich nicht fürchten, und vor ihrem Angesicht nicht entsetzen, obwohl sie sind ein widerspenstig Haus.',
        7: 'Und Meine Worte sollst du zu ihnen reden, ob sie darauf hören oder es unterlassen; denn widerspenstig sind sie.',
        8: 'Du aber, Menschensohn, höre, was Ich zu dir rede. Sei du nicht widerspenstig, wie das widerspenstige Haus, sperre deinen Mund auf und iß, was Ich dir gebe.',
        9: 'Und ich sah, und siehe, eine Hand war gegen mich ausgestreckt, und siehe, die Rolle eines Buches war darin.',
        10: 'Und Er breitete sie vor mir aus, und sie war inwendig und auf der Rückseite geschrieben, und geschrieben waren darauf Klagelieder, Seufzer und Weh.',
    },
    3: {
        1: 'Und Er sprach zu mir: Menschensohn, iß, was du findest, iß diese Rolle und gehe, rede zu dem Hause Israels.',
        2: 'Und ich öffnete meinen Mund, und Er ließ mich essen diese Rolle,',
        3: 'Und Er sprach zu mir: Menschensohn, laß essen deinen Bauch und fülle deine Eingeweide mit dieser Rolle, die Ich dir gebe. Und ich aß, und sie war in meinem Mund wie Honig an Süße.',
        4: 'Und Er sprach zu mir: Menschensohn, gehe hin, komme zu dem Hause Israels und rede zu ihm mit Meinen Worten.',
        5: 'Denn nicht zu einem Volk von tiefer Lippe und von schwerer Zunge bist du gesandt; zum Hause Israels,',
        6: 'Nicht zu vielen Völkern von tiefer Lippe und von schwerer Zunge, deren Worte du nicht hörst. Würden sie nicht, wenn Ich zu ihnen dich sendete, auf dich hören?',
        7: 'Aber das Haus Israels ist nicht willens, auf dich zu hören, denn sie sind nicht willens auf Mich zu hören, weil das ganze Haus Israels von bestärkter Stirne und von hartem Herzen ist.',
        8: 'Siehe, Ich mache dein Angesicht stark ihrem Angesicht entgegen, und deine Stirne stark entgegen ihrer Stirne.',
        9: 'Wie den Diamant, stärker denn der Fels, mache Ich deine Stirne. Fürchte dich nicht und entsetze dich nicht vor ihnen, daß sie ein widerspenstig Haus sind.',
        10: 'Und Er sprach zu mir: Menschensohn, alle Meine Worte, die Ich zu dir rede, nimm zu deinem Herzen und höre sie mit deinen Ohren.',
        11: 'Und gehe hin, komme zu den Weggeführten, zu den Söhnen deines Volkes und rede zu ihnen und sprich zu ihnen: Also spricht der Herr Jehovah; ob sie es hören, oder ob sie es unterlassen.',
        12: 'Und der Geist erhob mich, und ich hörte hinter mir die Stimme eines großen Erdbebens: Gesegnet sei die Herrlichkeit Jehovahs von Seinem Orte aus;',
        13: 'Und die Stimme der Flügel, der Tiere, die einander küß-ten, und die Stimme der Räder samt ihnen und eines großen Erdbebens Stimme.',
        14: 'Und der Geist erhob mich und nahm mich, und bitter im Grimm meines Geistes ging ich; und die Hand Jehovahs war stark über mir.',
        15: 'Und ich kam zu den Weggeführten gen Tel Abib, zu denen, die sitzen am Flusse Chebar, und betrachtete sie allda sitzen, und saß da sieben Tage erstaunt in ihrer Mitte.',
        16: 'Und es geschah am Ende der sieben Tage, daß Jehovahs Wort an mich geschah, und Er sprach:',
        17: 'Menschensohn, zum Wächter habe Ich dich gegeben für das Haus Israel, und hören sollst du aus Meinem Mund ein Wort, und sie von Mir warnen.',
        18: 'Wenn Ich zu den Ungerechten spreche: Du sollst des Todes sterben, und du warnst ihn nicht und redest nicht, den Ungerechten zu warnen vor seinem ungerechten Weg, um ihn am Leben zu erhalten, so stirbt er, der Ungerechte, in seiner Missetat, aber Ich fordere sein Blut von deiner Hand.',
        19: 'Und so du den Ungerechten gewarnt hast, und er nicht zurückkehrt von seiner Ungerechtigkeit und von seinem ungerechten Wege, so wird er sterben in seiner Missetat, und du hast deine Seele errettet.',
        20: 'Und wenn sich ein Gerechter zurückwendet von seiner Gerechtigkeit und Verkehrtes tut, und Ich einen Anstoß vor ihn tue, daß er stirbt; so du ihn nicht verwarnt hast ob seiner Sünde, so stirbt er, und nicht gedacht wird seiner Gerechtigkeit, die er getan, aber Ich fordere sein Blut von deiner Hand.',
        21: 'Und so du den Gerechten hast gewarnt, daß der Gerechte nicht sündige, und er nicht sündigt, soll er leben, weil er sich hat warnen lassen; und du hast deine Seele errettet.',
        22: 'Und allda war die Hand Jehovahs über mir, und Er sprach zu mir: Stehe auf und gehe in den Talgrund hinaus, und dort werde Ich zu dir reden.',
        23: 'Und ich stand auf und ging hinaus in den Talgrund, und siehe, allda stand die Herrlichkeit Jehovahs, wie die Herrlichkeit, die ich am Flusse Chebar sah, und ich fiel auf mein Angesicht.',
        24: 'Und in mich kam der Geist und ließ mich auf meine Füße stehen, und Er redete mit mir und sprach zu mir: Gehe hinein und schließe dich ein in deines Hauses Mitte.',
        25: 'Und du, Menschensohn, siehe, man legt dir Stricke an und bindet dich damit, daß du nicht mitten unter sie ausgehst.',
        26: 'Und deine Zunge will Ich an deinem Gaumen kleben lassen, daß du verstummen sollst und nicht mehr für sie ein Mann der Rüge sein mögest; denn ein widerspenstig Haus sind sie.',
        27: 'Und wenn Ich mit dir rede, will Ich deinen Mund öffnen, daß du zu ihnen sprechest: Also spricht der Herr Jehovah: Der, so es höret, höre es, und der es unterläßt, unterlasse es, weil sie sind ein widerspenstig Haus.',
    },
    4: {
        1: 'Und du, Menschensohn, nimm dir einen Ziegelstein und lege ihn vor dich hin und zeichne die Stadt Jerusalem darauf.',
        2: 'Und gib wider sie eine Belagerung, und baue ein Bollwerk wider sie, und schütte einen Wall auf wider sie und gib wider sie Heerlager, und setze rings um sie Sturmböcke.',
        3: 'Du aber nimm dir eine eiserne Pfanne und gib sie als eiserne Wand zwischen dich und die Stadt und richte dein Gesicht wider sie, und sie sei in Belagerung, und du sollst sie belagern. Ein Zeichen sei es dem Hause Israels.',
        4: 'Und du sollst auf deine linke Seite liegen, und lege darauf die Missetat des Hauses Israel. Die Zahl der Tage, die du darauf liegst, sollst ihre Missetat du tragen.',
        5: 'Ich aber gebe dir die Jahre ihrer Missetat zur Zahl der Tage: dreihundertneunzig Tage, daß du die Missetat des Hauses Israel sollst tragen.',
        6: 'Und hast du solches vollendet, sollst du ein zweites Mal auf deiner rechten Seite liegen und die Missetat des Hauses Jehudah tragen vierzig Tage, einen Tag auf das Jahr, einen Tag auf das Jahr gebe Ich dir.',
        7: 'Und auf Jerusalems Belagerung richte dein Angesicht und deinen entblößten Arm und weissage wider sie.',
        8: 'Und siehe, Ich lege dir Stricke an, daß du dich nicht von deiner einen Seite auf deine andere Seite kehren kannst, bis du die Tage deiner Belagerung hast vollendet.',
        9: 'Und du, nimm du dir Weizen und Gerste und Bohnen und Linsen und Hirse und Spelt, und tue sie in ein Gefäß und mache dir davon Brot nach der Zahl der Tage, die du auf deiner Seite liegst, dreihundertneunzig Tage sollst du es essen.',
        10: 'Und deine Speise, die du essen sollst nach dem Gewicht, sei zwanzig Schekel auf den Tag, von Zeit zu Zeit sollst du sie essen.',
        11: 'Und Wasser sollst du trinken nach dem Maß, ein sechstel Hin. Von Zeit zu Zeit sollst du es trinken.',
        12: 'Und sollst als Gerstenkuchen es essen; mit Kot, dem Auswurf von Menschen sollst du Kuchen machen vor ihren Augen.',
        13: 'Und Jehovah sprach: Also werden die Söhne Israels ihr unrein Brot essen unter den Völkerschaften, wohin Ich sie verstoßen werde.',
        14: 'Und ich sprach: Ach, Herr Jehovah, siehe, meine Seele ist nicht verunreinigt, und Aas und Zerfleischtes habe ich nicht gegessen von meiner Jugend bis jetzt, und ist kein abscheuliches Fleisch in meinen Mund gekommen.',
        15: 'Und Er sprach zu mir: Siehe, Ich gebe dir Rinderdung statt Menschenkot, damit du dein Brot damit machst.',
        16: 'Und Er sprach zu mir: Menschensohn, siehe, Ich breche den Stab des Brotes in Jerusalem, und sie sollen Brot essen nach dem Gewichte und mit Sorgen, und Wasser trinken nach dem Maß und mit Erstaunen.',
        17: 'Weil sie des Brotes und des Wassers mangeln, und sich erstaunen werden, der Mann und sein Bruder und abzehren ob ihrer Missetat.',
    },
    5: {
        1: 'Und du, Menschensohn, nimm dir ein scharfes Schwert; ein Schermesser der Bartscherer sollst du dir nehmen und lasse es über dein Haupt und über deinen Bart hinfahren, und nimm dir Waagen des Gewichts und teile sie.',
        2: 'Ein Drittel sollst du im Feuer verbrennen inmitten der Stadt, wenn die Tage der Belagerung erfüllt sind, und nehmen sollst du ein Drittel und mit dem Schwerte schlagen ringsumher und ein Drittel zersprengen in den Wind, und hinter ihnen her will Ich das Schwert ausziehen;',
        3: 'Und nimm von da ein wenig an der Zahl und binde sie zusammen an deine Fittiche.',
        4: 'Und nimm noch von ihnen und wirf sie in des Feuers Mitte und verbrenne sie im Feuer; von ihnen wird ein Feuer ausgehen über das ganze Haus Israel.',
        5: 'So spricht der Herr Jehovah: Dieses Jerusalem, inmitten der Völkerschaften setzte Ich es, und Lande rings um sie her.',
        6: 'Sie aber wandelten Meine Rechte in Ungerechtigkeit mehr als die Völkerschaften, und Meine Satzungen mehr als die Lande, die rings um sie her sind; denn sie verschmähten Meine Rechte und Meine Satzungen, sie wandelten nicht darin.',
        7: 'Darum, so spricht der Herr Jehovah, weil ihr mehr tobet denn die Völkerschaften, die um euch her sind, in Meinen Satzungen nicht wandeltet und Meine Rechte nicht tatet, und nicht nach den Rechten der Völkerschaften, die um euch her sind, tatet;',
        8: 'Darum spricht also der Herr Jehovah: Siehe, so bin auch Ich wider dich, und tue Gerichte in deiner Mitte vor den Augen der Völkerschaften.',
        9: 'Und tue in dir, was Ich nicht getan, und desgleichen Ich nicht mehr tun werde ob aller deiner Greuel.',
        10: 'Darum sollen Väter die Söhne essen inmitten deiner, und Söhne ihre Väter essen, und Gerichte werde Ich tun in dir und nach allen Winden zersprengen all deinen Überrest.',
        11: 'Darum, bei Meinem Leben, ist der Spruch des Herrn Jehovahs, weil du Mein Heiligtum verunreinigtest mit allen deinen Scheusalen und allen deinen Greueln, so werde auch Ich dich verringern und Mein Auge wird nicht schonen, und auch Ich werde nicht Mitleid haben.',
        12: 'Ein Drittel von dir wird sterben an der Pest und vor Hunger in deiner Mitte alle werden, und ein Drittel fallen durch das Schwert rings um dich her, und ein Drittel werde Ich zersprengen nach allen Winden, und das Schwert ausziehen hinter ihnen her.',
        13: 'Aber Mein Zorn soll vollendet werden, und Mein Grimm wider sie zur Ruhe kommen, daß es Mich gereut, und wissen sollen sie, daß Ich, Jehovah, in Meinem Eifer geredet hatte, da Mein Grimm wider sie vollendet ward;',
        14: 'Und Ich werde dich dahingeben zur Öde und zur Schmach unter den Völkerschaften rings um dich her, und vor den Augen eines jeden, der vorübergeht.',
        15: 'Und du wirst zur Schmach und Verhöhnung, zur Züchtigung und zum Erstaunen werden den Völkerschaften rings um dich her, da Ich an dir Gerichte tue in Zorn und in Grimm und in Strafen des Grimms; Ich, Jehovah, habe es geredet.',
        16: 'Wenn Ich des Hungers böse Pfeile unter sie sende, die sein sollen zum Verderben, die Ich senden werde, euch zu verderben; und den Hunger werde Ich dazutun wider euch, und euch den Stab des Brotes brechen.',
        17: 'Und den Hunger und das böse wilde Tier sende Ich wider euch, daß sie dich machen kinderlos. Und Pest und Blut soll in dir durchziehen. Und das Schwert bringe Ich über dich. Ich, Jehovah, habe es geredet.',
    },
    6: {
        1: 'Und Jehovahs Wort geschah an mich, sprechend:',
        2: 'Menschensohn, richte dein Angesicht gegen die Berge Israels und weissage wider sie.',
        3: 'Und sprich: Ihr, Berge Israels, höret das Wort des Herrn Jehovahs. So spricht der Herr Jehovah zu den Bergen und zu den Hügeln, zu den Flußbetten und zu den Schluchten: Siehe, Ich bringe über euch das Schwert und zerstöre eure Opferhöhen.',
        4: 'Und verwüstet werden eure Altäre und zerbrochen eure Sonnensäulen, und eure Erschlagenen lasse Ich fallen vor eure Götzen.',
        5: 'Und die Leichen der Söhne Israels gebe Ich hin vor eure Götzen und zersprenge euer Gebein rings um eure Altäre.',
        6: 'In allen euren Wohnsitzen sollen die Städte verödet und die Opferhöhen verwüstet sein, auf daß verödet und verwüstet seien eure Altäre, und zerbrochen seien und feiern eure Götzen, und niedergehauen eure Sonnensäulen, und euer Machwerk ausgewischt.',
        7: 'Und fallen soll der Erschlagene in eurer Mitte, und ihr sollt wissen, daß Ich Jehovah bin.',
        8: 'Und Ich will übriglassen, so daß seien für euch Entkommene in den Völkerschaften, wenn ihr zersprengt seid in den Ländern.',
        9: 'Und eure Entkommenen werden Mein gedenken unter den Völkerschaften, wohin sie gefangen geführt werden, wenn Ich gebrochen ihr buhlerisches Herz, das von Mir gewichen, und ihre Augen, die ihren Götzen nachgebuhlt, und sie ob ihnen verdrossen werden, wegen der Bosheiten, die sie getan ob aller ihrer Greuel.',
        10: 'Und sollen wissen, daß Ich, Jehovah, nicht umsonst geredet habe, daß Ich all dieses Böse an ihnen tun werde.',
        11: 'So spricht der Herr Jehovah: Schlage in deine Hände und stampfe mit deinem Fuß und sprich: Ach! über all die bösen Greuel des Hauses Israels, darum sie durch das Schwert, durch Hunger und durch Pest fallen.',
        12: 'Wer ferne ist, stirbt an der Pest, und der Nahe fällt durch das Schwert, wer aber verbleibt und bewahrt wird, der wird Hungers sterben. Und Ich vollende Meinen Grimm an ihnen.',
        13: 'Daß ihr wisset, daß Ich Jehovah bin, wenn ihre Erschlagenen liegen in ihrer Götzen Mitte rings um ihre Altäre her, auf jedem erhabenen Hügel, auf allen Häuptern der Berge, und unter jedem belaubten Baum und unter jeder dichtverzweigten Eiche, am Orte, wo sie den Geruch der Ruhe allen ihren Götzen gaben.',
        14: 'Und Ich strecke Meine Hand aus wider sie, und mache das Land zur Verwüstung und Wüstenei, von der Wüste bis nach Diblath an allen ihren Wohnsitzen, und sie sollen wissen, daß Ich Jehovah bin.',
    },
    7: {
        1: 'Und es geschah das Wort Jehovahs an mich, sprechend:',
        2: 'Und du, Menschensohn, also spricht der Herr Jehovah: Dem Boden Israels ist das Ende da! Das Ende ist gekommen über die vier Ecken des Landes.',
        3: 'Nun ist das Ende über dich, und Meinen Zorn entsende Ich wider dich, daß Ich nach deinen Wegen dich richte und alle deine Greuel auf dich lege.',
        4: 'Und Mein Auge soll deiner nicht schonen, und Ich werde dich nicht bemitleiden. Denn deine Wege bringe Ich über dich, und deine Greuel sollen in deiner Mitte sein, daß ihr wisset, daß Ich Jehovah bin.',
        5: 'So spricht der Herr Jehovah: Ein Übel, ein Übel, - siehe - es kommt.',
        6: 'Ein Ende kommt, es kommt das Ende, es erwacht über dich, siehe, es kommt.',
        7: 'Es kommt der Morgen über dich, der du im Lande wohnst. Es kommt die Zeit, nahe ist der Tag des Getümmels, und ist kein Kelterlied auf den Bergen.',
        8: 'Jetzt aus der Nähe schütte Ich Meinen Grimm aus über dich und vollende Meinen Zorn an dir, daß Ich dich nach deinen Wegen richte, und über dich all deine Greuel gebe.',
        9: 'Und Mein Auge wird dich nicht schonen, auch werde Ich dich nicht bemitleiden. Nach deinen Wegen gebe Ich es über dich, und deine Greuel sollen in deiner Mitte sein, daß ihr wisset, daß Ich Jehovah es bin, Der schlägt.',
        10: 'Siehe, der Tag! Siehe, er kommt! Hervor geht der Morgen. Es blüht der Stab, es sproßt die Vermessenheit.',
        11: 'Die Gewalt macht sich auf für der Ungerechtigkeit Stab. Nichts ist von ihnen und von ihrer Menge und von ihrem Brausen da, und kein Trauerlied über sie.',
        12: 'Es kommt die Zeit, der Tag reicht heran. Der Käufer soll nicht fröhlich sein, noch trauern der Verkäufer; denn Entbrennung ist über all ihrer Menge.',
        13: 'Denn der Verkäufer kehrt nicht zum Verkauften zurück, obschon sein Leben unter den Lebendigen ist; denn das Gesicht über all seine Menge geht nicht zurück, und eines jeden Mannes Leben ist in seiner Missetat; sie stärken sich nicht.',
        14: 'Sie stoßen in das Lärmhorn, und alles macht bereit; aber keiner geht in den Streit; denn Mein Entbrennen ist wider all seine Menge.',
        15: 'Das Schwert ist draußen, und Pest und Hunger innen. Wer auf dem Felde ist, der stirbt durch das Schwert, und den, so in der Stadt ist, frißt der Hunger und die Pest.',
        16: 'Und ihre Entkommenen entkommen und sind auf den Bergen wie die Tauben der Talschluchten; sie alle girren, jeder Mann über seine Missetat.',
        17: 'Schlaff werden alle Hände und aller Knie gehen zu Wasser.',
        18: 'Und mit Säcken gürten sie sich, und sie bedecket Grausen, und Scham ist auf aller Angesicht, und auf all ihren Häuptern Kahlheit.',
        19: 'Ihr Silber werfen sie auf die Gassen, und zur Befleckung wird ihr Gold. Ihr Silber und ihr Gold vermögen nicht, sie zu erretten am Tag des Wütens Jehovahs. Sie sättigen nicht ihre Seele und füllen nicht ihre Eingeweide; denn zum Straucheln ward ihre Missetat.',
        20: 'Und die Zierde ihres Geschmeides setzten sie zum Stolz, und machten daraus die Bilder ihrer Greuel, ihrer Scheusale; darum habe Ich es ihnen zur Befleckung gemacht.',
        21: 'Und in die Hand der Fremden gebe Ich es zum Raub, und zur Beute den Ungerechten der Erde, daß sie es entweihen.',
        22: 'Und Ich habe Mein Angesicht von ihnen herumgewandt, und Mein Verborgenes entweihen sie, und Räuber kommen hinein und entweihen es.',
        23: 'Mache eine Kette; denn das Land ist voll vom Gericht des Blutes, und die Stadt ist voll von Gewalttat.',
        24: 'Und Ich lasse die Bösen der Völkerschaften kommen, daß sie derselben Häuser in Besitz nehmen, und lasse zu Ende kommen den Stolz der Starken, und ihre Heiligtümer sollen entweiht werden.',
        25: 'Es kommt der Untergang; und sie suchen Frieden, und es wird keiner sein.',
        26: 'Unheil kommt auf Unheil; Gerücht auf Gerücht ist da. Und sie suchen Gesichte von den Propheten; aber das Gesetz ging dem Priester und Rat von den Ältesten verloren.',
        27: 'In Trauer ist der König, und der Fürst zieht an Erstaunen; und bestürzt sind die Hände des Volkes des Landes. Nach ihrem Wege tue Ich ihnen, und nach ihren Gerichten richte Ich sie, daß sie wissen, daß Ich Jehovah bin.',
    },
    8: {
        1: 'Und es geschah im sechsten Jahr, im sechsten, am fünften des Monats, saß ich in meinem Hause und die Ältesten Jehudahs saßen vor mir, und allda fiel auf mich die Hand des Herrn Jehovah.',
        2: 'Und ich sah, und siehe, eine Ähnlichkeit wie Feuer anzusehen. Von dem Aussehen seiner Lenden und abwärts, Feuer; und von seinen Lenden und aufwärts das Aussehen von Lichtglanz, wie der Anblick der Glühkohle.',
        3: 'Und es reckte wie das Gebilde einer Hand aus und nahm mich bei den Locken meines Hauptes, und der Geist erhob mich zwischen Erde und Himmel und brachte mich gen Jerusalem in Gesichten Gottes zum Eingang des inneren Tores, das gen Mitternacht gewendet ist, wo der Sitz des Standbildes der Eifersucht war, das zum Eifern reizte.',
        4: 'Und siehe, allda war die Herrlichkeit des Gottes Israels wie das Aussehen dessen, den ich in dem Talgrund sah.',
        5: 'Und Er sprach zu mir: Menschensohn, hebe deine Augen auf gegen den Weg der Mitternacht; und ich hob meine Augen auf gegen den Weg der Mitternacht, und siehe, nördlich vom Tore des Altars war dieses Standbild der Eifersucht beim Hineingehen.',
        6: 'Und Er sprach zu mir: Menschensohn, siehst du, was diese tun? Große Greuel tut hier das Haus Israels. Mich zu entfernen von Meinem Heiligtum. Und kehre dich noch um, du wirst noch größere Greuel sehen.',
        7: 'Und Er brachte mich hinein zum Eingang des Vorhofs, und ich sah, und siehe, ein Loch war in der Wand.',
        8: 'Und Er sprach zu mir: Menschensohn, durchbohre doch die Wand; und ich durchbohrte die Wand, und siehe, da war ein Eingang.',
        9: 'Und Er sprach zu mir: Gehe hinein und siehe die bösen Greuel, die sie allda tun.',
        10: 'Und ich ging hinein und sah, und siehe, allerlei Gebilde von Kriechtier und Vieh, Scheusale und allerlei Götzen des Hauses Israel waren auf der Wand ringsum, ringsum gemalt.',
        11: 'Und siebzig Männer von den Ältesten des Hauses Israels, und Jaasanjahu, der Sohn Schaphans, stand in ihrer Mitte; sie standen vor denselben und jeder Mann hatte sein Rauchfaß in seiner Hand, und der Wohlgeruch einer Wolke von Räuchwerk stieg auf.',
        12: 'Und Er sprach zu mir: Siehst du, Menschensohn, was die Ältesten des Hauses Israels tun im Finstern, jeder Mann in den Kammern seines Gebildes? Denn sie sagen: Jehovah sieht uns nicht. Jehovah hat das Land verlassen.',
        13: 'Und Er sprach zu mir: Kehre dich noch zurück, siehe die großen Greuel, die sie tun.',
        14: 'Und Er brachte mich zum Eingang des Tores zu Jehovahs Haus gen Mitternacht hinein, und siehe, da saßen die Weiber, die um den Thammus weinten.',
        15: 'Und Er sprach zu mir: hast du gesehen, Menschensohn? Du wirst noch zurückkehren und größere Greuel denn diese sehen.',
        16: 'Und Er brachte mich hinein zum inneren Vorhof von Jehovahs Haus, und siehe, am Eingang zu Jehovahs Tempel zwischen der Halle und dem Altar war es, als wären fünfundzwanzig Männer mit ihrem Rücken gegen Jehovahs Tempel und mit ihrem Angesichte gegen Osten und beteten dem Osten zu die Sonne an.',
        17: 'Und Er sprach zu mir: Siehst du es, Menschensohn? ist es ein Leichtes vom Hause Jehudah, daß sie die Greuel tun, die sie hier getan, daß sie das Land mit Gewalttat erfüllen, und zurückkehren, Mich zu reizen? Und siehe, sie recken das Rebmesser an ihre Nase aus.',
        18: 'Und auch Ich, Ich werde es im Grimme tun. Nicht schont Mein Auge, noch bemitleide Ich. Und rufen werden sie in Meine Ohren mit großer Stimme, aber Ich höre sie nicht.',
    },
    9: {
        1: 'Und Er rief in meine Ohren mit großer Stimme, sprechend: Sie nahen die Heimsucher der Stadt, und jeder Mann hat ein Werkzeug des Verderbens in seiner Hand.',
        2: 'Und siehe, sechs Männer kamen des Weges vom oberen Tor, das gegen Mitternacht gewendet ist, und jeder Mann hatte sein Werkzeug des Zerstreuens in seiner Hand, und ein Mann in ihrer Mitte war mit Lein angetan und hatte eines Schreibers Tintenfaß an seinen Lenden, und sie kamen herein und standen neben dem Altar von Erz.',
        3: 'Und die Herrlichkeit des Gottes Israels stieg auf von dem Cherub, auf dem sie war, nach der Schwelle des Hauses hin und rief dem Mann, der mit Lein angetan war und des Schreibers Tintenfaß an seinen Lenden hatte.',
        4: 'Und Jehovah sprach zu ihm: Ziehe hindurch inmitten der Stadt, inmitten Jerusalems, und zeichne ein Zeichen auf die Stirne der Männer, die seufzen und jammern über all die Greuel, die in ihrer Mitte getan werden.',
        5: 'Und zu jenen sprach Er vor meinen Ohren: Zieht hindurch in die Stadt ihm nach und schlaget. Nicht schone euer Auge und habet kein Mitleid.',
        6: 'Den Alten, den Jüngling und die Jungfrau, und das Kindlein und die Weiber sollt ihr erwürgen, sie zu verderben; aber an keinen Mann sollt ihr hinzutreten, an dem das Zeichen ist; und ihr sollt an Meinem Heiligtum anfangen. Und sie fingen bei den alten Männern an, die vor dem Hause waren.',
        7: 'Und Er sprach zu ihnen: Verunreinigt das Haus und füllet mit Erschlagenen die Vorhöfe; ziehet aus. Und sie zogen aus und schlugen in der Stadt.',
        8: 'Und es geschah, da sie geschlagen hatten, daß ich verblieb. Und ich fiel auf mein Angesicht und schrie und sprach: Ach, Herr Jehovah, willst Du allen Überrest Israels verderben, daß Deinen Grimm Du ausgießest über Jerusalem?',
        9: 'Und Er sprach zu mir: Die Missetat des Hauses Israels und Jehudahs ist gar sehr groß und das Land ist gefüllt mit Blut, und voller Rechtsverdrehung ist die Stadt; denn sie sagen: Jehovah hat das Land verlassen, und Jehovah sieht nicht.',
        10: 'Und auch Ich - Mein Auge wird nicht schonen, und Ich will nicht bemitleiden. Ihren Weg gebe Ich auf ihr Haupt.',
        11: 'Und siehe, der Mann, der mit der Lein war angetan und das Tintenfaß an seinen Lenden hatte, brachte Wort zurück und sprach: Ich habe getan, wie Du mir geboten hast.',
    },
    10: {
        1: 'Und ich sah, und siehe, auf der Ausbreitung über dem Haupte der Cherube war es wie der Stein Saphir, wie das Aussehen der Ähnlichkeit von einem Thron, über ihnen zu sehen.',
        2: 'Und Er sprach zu dem Manne, der mit Lein war angetan, und Er sprach: Gehe hinein zwischen das Räderwerk unter den Cherub, und fülle deine Hände mit Feuerkohlen, zwischen den Cheruben heraus und sprenge sie über die Stadt. Und er ging hinein vor meinen Augen.',
        3: 'Und die Cherube standen rechts vom Hause, da der Mann hineinging, und die Wolke füllte den inneren Vorhof.',
        4: 'Und es hob sich die Herrlichkeit Jehovahs empor über dem Cherub über des Hauses Schwelle, und von der Wolke ward das Haus erfüllt, und der Vorhof ward erfüllt vom Glanz der Herrlichkeit Jehovahs.',
        5: 'Und die Stimme der Flügel der Cherube ward gehört bis zu dem äußeren Vorhof, wie die Stimme des Gottes Schaddai, wenn Er redet.',
        6: 'Und es geschah, als Er dem Manne mit Lein angetan geboten und gesagt hatte: Nimm Feuer zwischen dem Räderwerk heraus, zwischen den Cheruben, und der hineinging und neben dem Rad stand;',
        7: 'Da reckte der Cherub seine Hand aus zwischen den Cheruben her zum Feuer, das zwischen den Cheruben war, und hob auf und gab es dem, der mit Lein angetan war, in die Hände; und er nahm es und ging hinaus.',
        8: 'Und man sah an den Cheruben unter ihren Flügeln das Gebilde der Hand eines Menschen.',
        9: 'Und ich sah, und siehe, vier Räder neben den Cheruben, ein Rad neben dem einen Cherub und ein Rad neben dem anderen Cherub, und das Aussehen der Räder war wie der Anblick des Steins von Tharschisch.',
        10: 'Und ihr Aussehen hatte eine Ähnlichkeit für die vier, als ob ein Rad wäre inmitten eines Rades.',
        11: 'Bei ihrem Gehen gingen sie ihren vier Richtungen zu; sie wandten sich nicht um bei ihrem Gehen, denn nach dem Ort, dahin das Haupt sich wandte, danach gingen sie; sie wandten sich nicht um bei ihrem Gehen.',
        12: 'Und all ihr Fleisch und ihr Rücken und ihre Hände und ihre Flügel und die Räder waren voller Augen ringsum, für ihre vier Räder.',
        13: 'Die Räder - sie wurden Räderwerk genannt vor meinen Ohren.',
        14: 'Und vier Angesichte hatte einer: Das eine Angesicht das Angesicht des Cherubs und das zweite Angesicht war eines Menschen Angesicht und das dritte eines Löwen Angesicht und das vierte eines Adlers Angesicht.',
        15: 'Und es hoben sich empor die Cherube; das war das Tier, das ich am Flusse Chebar sah.',
        16: 'Und wenn die Cherube gingen, gingen die Räder neben ihnen, und wenn die Cherube die Flügel erhoben, sich über die Erde emporzuheben, so wandten auch die Räder sich nicht um von ihrer Seite.',
        17: 'Und wenn dieselben standen, standen sie, und wenn sie sich emporhoben, hoben sie mit ihnen sich empor; denn der Geist des Tieres war in ihnen.',
        18: 'Und von des Hauses Schwelle ging die Herrlichkeit Jehovahs aus und stand über den Cheruben.',
        19: 'Und die Cherube erhoben ihre Flügel und hoben sich von der Erde empor vor meinen Augen. Da sie hinausgingen, waren die Räder ihnen beigesellt. Und es stand am Eingang des östlichen Tores am Hause Jehovahs, und die Herrlichkeit des Gottes Israels war oben über ihnen.',
        20: 'Das ist das Tier, das ich unter dem Gotte Israels am Flusse Chebar sah; und ich wußte, daß es Cherube waren.',
        21: 'Je vier Gesichter hatte einer und vier Flügel einer, und die Ähnlichkeit der Hände von Menschen unter ihren Flügeln.',
        22: 'Und die Ähnlichkeit ihrer Angesichter waren die Angesichter, die ich am Flusse Chebar sah, ihr Aussehen und sie selbst. Sie gingen, jeder Mann stracks vor seinem Angesicht.',
    },
    11: {
        1: 'Und es erhob mich der Geist und brachte mich herein an das vordere Tor von dem Hause Jehovahs, das nach Osten gewandt ist; und siehe, an des Tores Eingang waren fünfundzwanzig Männer, und ich sah in ihrer Mitte Jaasanjah, den Sohn Assurs, und Pelatjahu, Benajahus Sohn, Oberste des Volkes.',
        2: 'Und Er sprach zu mir: Menschensohn, dies die Männer, die Unrecht denken und raten bösen Rat in dieser Stadt.',
        3: 'Sie, die da sprechen: Es ist nicht nahe, daß man Häuser baue! Sie ist der Topf, und wir sind das Fleisch.',
        4: 'Darum weissage wider sie, weissage, Menschensohn!',
        5: 'Und es fiel der Geist Jehovahs auf mich und sprach zu mir: Sprich: Also spricht Jehovah: So sprechet ihr, Haus Israel, und was in eurem Geiste aufsteigt, weiß Ich.',
        6: 'Eurer Erschlagenen in dieser Stadt habt ihr viel gemacht, und ihre Gassen mit Erschlagenen gefüllt.',
        7: 'Darum so spricht der Herr Jehovah: Eure Erschlagenen, die ihr in ihrer Mitte hingestreckt, sie sind das Fleisch, und sie ist der Topf. Euch aber bringt man heraus aus ihrer Mitte.',
        8: 'Das Schwert habt ihr gefürchtet, und das Schwert bringe Ich herein über euch: spricht der Herr Jehovah.',
        9: 'Und aus ihrer Mitte lasse Ich euch hinausbringen, und gebe euch in der Fremden Hand und tue Gerichte über euch.',
        10: 'Ihr sollt fallen durch das Schwert, Ich richte euch an der Grenze Israels, auf daß ihr wisset, daß Ich bin Jehovah.',
        11: 'Sie soll euch der Topf nicht sein, noch sollt ihr das Fleisch darinnen sein, an Israels Grenze werde Ich euch richten.',
        12: 'Und ihr sollt wissen, daß Ich Jehovah bin, in dessen Satzungen ihr nicht gewandelt seid, und Meine Rechte habt ihr nicht getan, sondern habt getan nach den Rechten der Völkerschaften um euch her.',
        13: 'Und es geschah, wie ich weissagte, da starb Pelatjahu, der Sohn Benajahus, und ich fiel auf mein Angesicht und schrie mit großer Stimme und sprach: Ach, Herr Jehovah, willst Du Vollendung machen dem Überrest von Israel?',
        14: 'Und es geschah an mich Jehovahs Wort, sprechend:',
        15: 'Menschensohn, deine Brüder, deine Brüder, deiner Verwandtschaft Männer und das ganze Haus Israels allzumal, sie sind es, zu denen die, so in Jerusalem wohnen, sprechen: Bleibt ferne von Jehovah, uns ist es, das Land, zum Erbbesitz gegeben.',
        16: 'Sprich darum: So spricht der Herr Jehovah: Zwar werde Ich euch unter die Völkerschaften entfernen, und euch zerstreuen in die Länder; doch werde Ich ihnen ein kleines Heiligtum in den Ländern sein, dahin sie kommen.',
        17: 'Darum sprich: Also spricht der Herr Jehovah: Und Ich werde euch zusammenbringen von den Völkern und euch versammeln aus den Ländern, dahin ihr seid zerstreut, und euch geben den Boden Israels.',
        18: 'Und sie werden dorthin kommen und wegtun alle seine Scheusale und alle seine Greuel aus demselben.',
        19: 'Und geben will Ich ihnen ein Herz, und einen neuen Geist will Ich geben in eure Mitte, und wegnehmen das Herz von Stein aus ihrem Fleisch und ihnen geben ein Herz von Fleisch;',
        20: 'Damit sie in Meinen Satzungen wandeln und Meine Rechte halten, und sie tun. Und sie werden Mir zum Volk, und Ich will ihnen Gott sein.',
        21: 'Aber dem Herzen ihrer Scheusale und ihren Greueln geht ihr Herz nach; ihren Weg will Ich auf ihr Haupt geben, spricht der Herr Jehovah.',
        22: 'Und die Cherube erhoben ihre Flügel, und die Räder samt ihnen, und die Herrlichkeit des Gottes Israels war oben über ihnen.',
        23: 'Und die Herrlichkeit Jehovahs stieg hinauf aus der Mitte der Stadt und stand über dem Berg, der im Osten der Stadt ist.',
        24: 'Und es erhob mich der Geist und brachte mich hinein gen Chaldäa zu den Weggeführten in dem Gesicht, im Geiste Gottes; und das Gesichte das ich gesehen, stieg auf von mir.',
        25: 'Ich aber redete zu den Weggeführten alle Worte Jehovahs, die Er mich sehen ließ.',
    },
    12: {
        1: 'Und es geschah an mich Jehovahs Wort, und Er sprach:',
        2: 'Menschensohn, du sitzest inmitten eines widerspenstigen Hauses; die haben Augen zum Sehen und sehen nicht; Ohren haben sie zum Hören und hören nicht, weil sie ein widerspenstig Haus sind.',
        3: 'Und du, Menschensohn, mache dir Geräte zur Wegführung und wandere aus am Tag vor ihren Augen, und wandere aus vor ihren Augen von deinem Ort an einen anderen Ort. Vielleicht daß sie sehen, daß sie sind ein widerspenstig Haus.',
        4: 'Und bringe heraus deine Geräte, wie Geräte zur Wegführung am Tage vor ihren Augen, und du, ziehe aus am Abend vor ihren Augen, wie die Weggeführten ausziehen;',
        5: 'Vor ihren Augen bohre dir durch die Wand, und bringe sie da hinaus.',
        6: 'Vor ihren Augen erhebe sie auf die Schultern und in der Düsternis bringe sie hinaus, bedecke dein Gesicht, daß du das Land nicht sehest; denn Ich gebe dich zum Wahrzeichen dem Hause Israels.',
        7: 'Und ich tat so, wie mir geboten ward, meine Geräte brachte ich bei Tag als Geräte der Wegführung heraus, und am Abend bohrte ich mir mit der Hand durch die Wand; in der Düsternis brachte ich sie hinaus, erhob sie auf die Schulter vor ihren Augen.',
        8: 'Und am Morgen geschah an mich das Wort Jehovahs sprechend:',
        9: 'Menschensohn, sprechen nicht zu dir die von dem Hause Israel, dem widerspenstigen Hause: Was tust du?',
        10: 'Sprich zu ihnen: Also spricht der Herr Jehovah: Für den Fürsten ist diese Weissagung in Jerusalem und das ganze Haus Israel, das in seiner Mitte ist.',
        11: 'Sprich: Ich bin euch ein Wahrzeichen; wie ich getan habe, so wird euch getan, ihr werdet in Verbannung, in Gefangenschaft gehen.',
        12: 'Und den Fürsten, der in ihrer Mitte ist, ihn wird man auf die Schulter erheben in der Düsternis, daß er hinauskomme durch die Wand, die sie durchbohren, um ihn da hinauszubringen. Er wird sein Angesicht bedecken, daß er nicht selbst mit dem Auge das Land sehe.',
        13: 'Und Ich will gegen ihn Mein Netz ausbreiten, daß er in Meinem Garn erfaßt werde, und will ihn nach Babel hineinbringen in der Chaldäer Land, und er wird es nicht sehen, und allda soll er sterben.',
        14: 'Und alles um ihn her, was ihm beistand, und alle seine Scharen will Ich in allen Winden hin zersprengen, und das Schwert ausziehen hinter ihnen her.',
        15: 'Auf daß sie wissen, daß Ich Jehovah bin, indem Ich unter die Völkerschaften sie zerstreue und sie versprenge in die Länder.',
        16: 'Und ihrer will Ich nur wenige Männer vom Schwert, vom Hunger und von der Pest übrigbleiben lassen, daß sie unter den Völkerschaften, dahin sie kommen, alle ihre Greuel erzählen und wissen, daß Ich Jehovah bin.',
        17: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        18: 'Menschensohn, du sollst dein Brot mit Beben essen und dein Wasser mit Zittern und Sorgen trinken.',
        19: 'Und zu dem Volk des Landes sollst du sagen: So spricht der Herr Jehovah zu Jerusalems Bewohnern, zum Boden Israels: Ihr Brot sollen sie in Sorge essen und mit Erstaunen ihr Wasser trinken, weil ihr Land verwüstet ist, seiner Fülle bar ob der Gewalttat aller, die in ihm wohnten.',
        20: 'Und die bewohnten Städte werden verödet, und das Land verwüstet werden, auf daß sie wissen, daß Ich Jehovah bin.',
        21: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        22: 'Menschensohn, was habt ihr für ein Sprichwort auf dem Boden Israels, und ihr sprechet: Die Tage verlängern sich und alles Gesichte ist verloren.',
        23: 'Darum sprich zu ihnen: Also spricht der Herr Jehovah: Ich lasse zu Ende kommen dieses Sprichwort. Und sie sollen nicht mehr das Sprichwort führen in Israel. Sondern rede zu ihnen: Die Tage nahen und jeglichen Gesichtes Wort.',
        24: 'Denn nicht soll fürder irgendein eitel Gesichte, noch schmeichlerische Wahrsagung inmitten des Hauses Israels sein.',
        25: 'Denn Ich bin Jehovah. Was Ich rede, das rede Ich, das Wort wird getan und verzieht sich nicht mehr; denn in euren Tagen, du widerspenstig Haus, rede Ich ein Wort und tue es, spricht der Herr Jehovah.',
        26: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        27: 'Menschensohn, siehe, das Haus Israels spricht: Das Gesichte, das er erschaut, ist auf viele Tage, und für ferne Zeiten weissagt er.',
        28: 'Darum sprich zu ihnen: Also spricht der Herr Jehovah: Keines Meiner Worte soll fürder mehr verziehen; was Ich geredet, das Wort, wird getan, spricht der Herr Jehovah.',
    },
    13: {
        1: 'Und es geschah das Wort Jehovahs an mich, sprechend:',
        2: 'Menschensohn, weissage über die Propheten Israels, die da weissagen, und sprich zu denen, die aus ihrem Herzen weissagen: Hört das Wort Jehovahs.',
        3: 'So spricht der Herr Jehovah: Wehe über die törichten Propheten, die nach ihrem Geiste gehen und dem, was sie nicht sahen.',
        4: 'Wie Füchse in den Öden sind, Israel, deine Propheten geworden.',
        5: 'Ihr stieget nicht hinauf in die Durchbrüche, noch zäuntet ihr einen Zaun für das Haus Israel, zu stehen im Streit am Tag Jehovahs.',
        6: 'Sie schauen Eitles und wahrsagen Falsches, sie sprechen: Jehovahs Spruch! und Jehovah hat sie nicht gesandt, und lassen darauf warten, daß Er das Wort bestätige.',
        7: 'Habt ihr nicht ein eitel Gesicht geschaut, falsche Wahrsagungen gesprochen? und ihr sprechet: Jehovahs Spruch! und Ich habe nicht geredet.',
        8: 'Darum spricht so der Herr Jehovah: Weil ihr Eitles redet und Falsches schaut, darum sehet, bin Ich wider euch, spricht der Herr Jehovah.',
        9: 'Und Meine Hand soll sein wider die Propheten, die Eitles schauen und Falsches wahrsagen. Im Kreise Meines Volkes sollen sie nicht sein und nicht eingeschrieben in die Schrift des Hauses Israels und nicht kommen auf den Boden Israels, auf daß ihr wisset, daß Ich der Herr Jehovah bin.',
        10: 'Weil und alldieweil sie Mein Volk verleiten und sprechen: Friede! und ist kein Friede. Und baut es eine Scheidemauer - sie übertünchen sie mit Untauglichem.',
        11: 'Sprich zu den Tünchern mit dem Untauglichen: Sie falle! Ein überflutender Platzregen ist da, und ihr, Steine des Hagels, sollet fallen, und ein Wind des Wettersturmes soll sie durchbrechen.',
        12: 'Und siehe, die Wand fällt. Wird man nicht zu euch sagen: Wo ist die Tünche, mit der ihr habt getüncht?',
        13: 'Darum, so spricht der Herr Jehovah, lasse Ich den Wind des Wettersturmes durchbrechen in Meinem Grimm, und ein überflutender Platzregen kommt in Meinem Zorn, und Steine des Hagels im Grimm zur Vollendung.',
        14: 'Und reiße nieder die Wand, die ihr mit Untauglichem getüncht, und bringe sie zur Erde danieder, daß ihre Grundfeste aufgedeckt wird, und sie fällt, daß ihr alle werdet in ihrer Mitte; auf daß ihr wisset, daß Ich Jehovah bin.',
        15: 'Und Ich vollende Meinen Grimm an der Wand, und an denen, die mit dem Untauglichem sie getüncht haben, und spreche zu euch: Nicht mehr ist die Mauer, und nicht mehr die, die so übertünchten.',
        16: 'Die Propheten Israels, die über Jerusalem weissagten, und die Schauer, die für sie Frieden schauten, und ist kein Frieden, spricht der Herr Jehovah.',
        17: 'Du aber, Menschensohn, richte dein Angesicht auf deines Volkes Töchter, die da aus ihrem Herzen weissagen, und weissage über sie!',
        18: 'Und sprich: So spricht der Herr Jehovah: Wehe euch, die ihr Kissen nähet an alle Gelenke der Hände, und Kopftücher für Köpfe jeglichen Wuchses machet, um Seelen zu erjagen. - Die Seelen erjaget ihr Meinem Volk, und erhaltet euch Seelen am Leben.',
        19: 'Und ihr entweiht Mich bei Meinem Volke für eine Handvoll Gerste und für Bissen Brotes, damit, daß ihr Seelen zum Tode bringt, die nicht sterben sollten, und am Leben erhaltet Seelen, die nicht leben sollten, damit, daß ihr täuschet Mein Volk, die, so auf Falsches hören.',
        20: 'Darum, so spricht der Herr Jehovah, siehe, Ich will an eure Kissen, womit ihr die Seelen jaget, daß sie entfliegen. Aber Ich reiße sie ab von euren Armen und entsende die Seelen, die ihr jagtet, - die Seelen, daß sie entfliegen.',
        21: 'Und Ich zerreiße eure Kopftücher und errette Mein Volk aus eurer Hand, daß sie nicht mehr in eurer Hand als Erjagtes sind, und ihr wisset, daß Ich Jehovah bin.',
        22: 'Weil ihr durch Lüge des Gerechten Herz verzagen lasset, dem Ich nicht wehe tun will, und ihr stärket die Hände des Ungerechten, daß er von seinem bösen Weg nicht umkehre und am Leben bleibe.',
        23: 'Darum sollt ihr nicht Eitles schauen, und Wahrsagung nicht weiter wahrsagen. Und Ich errette Mein Volk aus eurer Hand, daß ihr wisset, daß Ich Jehovah bin.',
    },
    14: {
        1: 'Und es kamen Männer von den Ältesten Israels zu mir und saßen vor meinem Angesicht.',
        2: 'Und es geschah an mich das Wort Jehovahs, sprechend:',
        3: 'Menschensohn, diese Männer ließen ihre Götzen in ihr Herz aufsteigen und gaben den Anstoß ihrer Missetat vor ihr Angesicht. Soll Ich von ihnen Mich befragen lassen?',
        4: 'Darum rede mit ihnen und sprich zu ihnen: So spricht der Herr Jehovah: Jeder Mann aus dem Hause Israels, der seine Götzen ließ in sein Herz aufsteigen, und seiner Missetat Anstoß sich vor sein Angesicht setzte, und zum Propheten kommt, sollte Ich, Jehovah, ihm antworten, der mit seiner Götzen Menge kommt?',
        5: 'Auf daß Ich das ganze Haus Israel an ihrem Herzen erfasse, weil sie sich allesamt durch ihre Götzen von Mir entfremdet haben?',
        6: 'Darum sprich zu dem Hause Israels: So spricht der Herr Jehovah: Kehret zurück und wendet euch zurück von euren Götzen, und von allen euren Greueln wendet zurück euer Angesicht.',
        7: 'Denn jeder Mann vom Hause Israel und von den Fremdlingen, die in Israel sich aufhalten, der sich rückwärts von Mir entfremdet und seine Götzen in sein Herz aufsteigen läßt, und den Anstoß seiner Missetat setzt vor sein Angesicht und kommt zu dem Propheten, Mich für sich zu befragen, so will Ich, Jehovah, ihm von Mir aus antworten.',
        8: 'Ich will Mein Angesicht hingeben wider solchen Mann und ihn verwüsten, zu einem Zeichen und Sprichwort und ihn ausrotten aus der Mitte Meines Volkes, auf daß ihr wisset, daß Ich Jehovah bin.',
        9: 'Und wenn ein Prophet sich bereden läßt, daß er ein Wort redet, selbigen Propheten lasse auch Ich, Jehovah, bereden und recke Meine Hand aus wider ihn, daß Ich ihn aus der Mitte Meines Volkes Israel vernichte.',
        10: 'Und ihre Missetat sollen sie tragen. Die Missetat dessen, der da befragt, soll sein wie des Propheten Missetat.',
        11: 'Auf daß das Haus Israel nicht mehr von Mir abirre und sich nicht mehr verunreinige mit allen ihren Übertretungen, und daß sie Mir zum Volke werden und Ich ihr Gott sei, spricht der Herr Jehovah.',
        12: 'Und es geschah an mich Jehovahs Wort, sprechend:',
        13: 'Menschensohn, so ein Land sündigt wider Mich, daß es untreu Mir untreu wird, da recke Ich Meine Hand aus wider dasselbe und zerbreche ihm den Stab des Brotes und sende dahin den Hunger und rotte aus davon Mensch und Vieh.',
        14: 'Und wenn in ihrer Mitte diese drei Männer wären: Noach, Daniel und Hiob, würden sie durch ihre Gerechtigkeit ihre Seelen erretten, spricht der Herr Jehovah.',
        15: 'Wenn Ich böses wildes Tier lasse durch das Land hingehen, daß es dasselbe kinderlos macht, und es verwüstet, daß vor dem wilden Tier nichts da hindurchgeht;',
        16: 'Wenn diese drei Männer wären in ihrer Mitte, bei Meinem Leben, spricht der Herr Jehovah, sie würden ihre Söhne und Töchter nicht erretten, nur sie allein würden errettet, aber das Land wäre verwüstet.',
        17: 'Oder bringe Ich das Schwert herein über jenes Land und spreche: Das Schwert ziehe durch das Land, und Ich rotte daraus Mensch und Vieh aus.',
        18: 'Und diese drei Männer wären in seiner Mitte, bei Meinem Leben, spricht der Herr Jehovah, sie würden Söhne und Töchter nicht erretten; denn sie allein würden errettet.',
        19: 'Oder sendete Ich die Pest über dieses Land und gösse Meinen Grimm aus wider es mit Blut, um aus ihm Mensch und Vieh auszurotten;',
        20: 'Und Noach, Daniel und Hiob wären in ihrer Mitte, bei Meinem Leben, spricht der Herr Jehovah, sie würden weder Sohn noch Tochter erretten, sie würden durch die Gerechtigkeit ihrer Seele errettet.',
        21: 'Doch also spricht der Herr Jehovah: Wenn Ich auch sende Meine bösen vier Gerichte: Schwert und Hunger und das böse wilde Tier und Pest über Jerusalem, daß Ich daraus Mensch und Vieh ausrotte;',
        22: 'Und siehe, es verbleiben in ihr noch übrig Entkommene, die herausgebracht werden, Söhne und Töchter, siehe, sie kommen heraus zu euch und ihr werdet ihren Weg und ihre Handlungen sehen, und ihr werdet euch trösten über dem Bösen, das Ich über Jerusalem hereingebracht, über alles, das Ich über dasselbe hatte kommen lassen.',
        23: 'Und sie werden euch trösten, wenn ihr ihren Weg und ihre Handlungen sehet, und ihr werdet wissen, daß Ich nicht umsonst all das getan, was Ich in ihm getan habe, spricht der Herr Jehovah.',
    },
    15: {
        1: 'Und es geschah zu mir das Wort Jehovahs, sprechend:',
        2: 'Menschensohn, was ist das Holz des Weinstocks vor allem Holz? Die Rebe, die unter den Bäumen des Waldes ist?',
        3: 'Nimmt man davon Holz, um ein Werk zu machen? nimmt man davon einen Pflock, um irgendein Gerät daran aufzuhängen?',
        4: 'Siehe, man gibt es dem Feuer zur Speise. Seine zwei Enden hat das Feuer aufgefressen, und in der Mitte ist es entbrannt. Gerät es zu einem Werk?',
        5: 'Siehe, da es noch ganz war, machte man kein Werk daraus. Nun aber das Feuer es aufgefressen und es entbrannt ist, kann man noch ein Werk davon machen?',
        6: 'Darum spricht also der Herr Jehovah: Gleichwie das Holz des Weinstocks ist unter dem Holz des Waldes, das Ich zur Speise dem Feuer gebe, so gebe Ich Jerusalems Bewohner,',
        7: 'Und gebe wider sie Mein Angesicht, daß, wo sie auch dem Feuer sind entgangen, das Feuer sie doch fressen wird. Und ihr sollt wissen, daß Ich Jehovah bin, wenn Ich Mein Angesicht setze wider sie,',
        8: 'Und Ich das Land zur Wüste hingebe, weil sie sind untreu worden, spricht der Herr Jehovah.',
    },
    16: {
        1: 'Und es geschah an mich das Wort Jehovahs, sprechend:',
        2: 'Menschensohn, tue Jerusalem ihre Greuel zu wissen,',
        3: 'Und sprich: So spricht der Herr Jehovah zu Jerusalem: Dein Handel und deine Geburt ist aus dem Land des Kanaaniters; dein Vater ist der Amoriter und deine Mutter eine Chethiterin.',
        4: 'Und bei deiner Geburt, am Tag, da du geboren wardst, wurde dein Nabel nicht abgeschnitten, und du wurdest im Wasser nicht gebadet für Mein Anschauen, nicht mit Salz gesalzen und in Windeln nicht gewickelt.',
        5: 'Kein Auge schonte dein, dir eins von diesen zu tun, dich zu bemitleiden, und du wurdest auf des Feldes Fläche hingeworfen, aus Ekel vor deiner Seele am Tag, da du geboren wardst.',
        6: 'Und Ich ging an dir vorüber und sah dich zertreten in deinem Blut, und sprach zu dir in deinem Blut: Lebe! Und Ich sprach zu dir in deinem Blute: Lebe!',
        7: 'Zur Mehrung, wie den Sproß des Feldes gab Ich dich, und du wuchsest und wurdest groß, und kamst in dem Schmuck deines Schmuckes, die Brüste wurden fest, und dein Haar sproßte; du aber warst nackt und bloß.',
        8: 'Und Ich ging an dir vorüber und sah dich, und siehe, es war deine Zeit, die Zeit der Liebkosungen, und Ich breitete Meinen Fittich über dich und deckte deine Blöße und schwor dir und ging einen Bund ein mit dir, spricht der Herr Jehovah, und du wardst Mein.',
        9: 'Und Ich badete dich mit Wasser und spülte ab dein Blut von dir und salbte dich mit Öl.',
        10: 'Und Ich zog dir Gewirktes an, und beschuhte dich mit Tachaschfell, umwand dich mit Byssus und bedeckte dich mit Seide.',
        11: 'Und ich schmückte dich mit Geschmeide und gab Armbänder an deine Hände und ein Kettchen um deinen Nacken.',
        12: 'Und gab einen Reif an deine Nase und Ohrringe an deine Ohren und eine Krone der Zierde auf dein Haupt.',
        13: 'Und du warst geschmückt mit Gold und Silber, und dein Anzug war Byssus und Seide und Gewirktes. Semmelmehl und Honig und Öl aßest du, und wardst gar sehr schön, und gelangtest zum Königtum.',
        14: 'Und dein Name ging aus ob deiner Schönheit, denn sie war vollkommen durch Mein Geschmeide, das Ich dir angelegt hatte, spricht der Herr Jehovah.',
        15: 'Du aber vertrautest auf deine Schönheit und buhltest auf deinen Namen und gossest deine Buhlereien aus auf jeden, der vorüberging, sein war sie.',
        16: 'Und nahmst von deinen Kleidern und machtest dir bunte Opferhöhen und buhltest auf ihnen, was nicht gekommen ist noch geschehen wird.',
        17: 'Und du hast Geräte deines Schmuckes von Meinem Gold und Meinem Silber, das Ich dir gegeben hatte, genommen und männliche Bilder dir gemacht und mit ihnen gebuhlt.',
        18: 'Und hast deine gewirkten Kleider genommen und sie bedeckt und Mein Öl und Mein Räucherwerk gabst du vor sie;',
        19: 'Und Mein Brot, das Ich dir hatte gegeben, Semmelmehl und Öl und Honig, so Ich dich essen ließ, hast du vor sie gegeben zum Geruch der Ruhe, und es geschah, spricht der Herr Jehovah.',
        20: 'Und du nahmst deine Söhne und Töchter, die du Mir geboren, und opfertest sie ihnen zum Fraß. War es zu wenig für deine Buhlereien?',
        21: 'Und Meine Söhne hast du geschlachtet und sie gegeben, daß sie für sie durch das Feuer hindurchgingen.',
        22: 'Und bei all deinen Greueln und Buhlereien gedenkst du nicht der Tage deiner Jugend, wie du nackt und bloß warst, zertreten in deinem Blut.',
        23: 'Und es geschah nach all deiner Bosheit - wehe, wehe dir, spricht der Herr Jehovah-',
        24: 'Daß du dir bautest eine Hochwarte und dir eine Höhe machtest in jeder Straße.',
        25: 'Am Anfang jedes Weges bautest du deine Höhe, und machtest zum Greuel deine Schönheit, und spreiztest dein Füße jedem, der vorüberging, und mehrtest deine Buhlerei.',
        26: 'Und buhltest mit Ägyptens Söhnen, deinen Nachbarn groß an Fleisch, und mehrtest deine Buhlerei, Mich zu reizen.',
        27: 'Und siehe, Ich habe Meine Hand ausgestreckt über dich und verringerte dein Bestimmtes, und gebe dich in den Willen derer, die dich hassen der Töchter der Philister, die Schande fühlten ob deiner Unzucht Weg.',
        28: 'Und du buhltest mit Aschurs Söhnen, weil du nicht satt kannst werden. Und mit ihnen hast du gebuhlt und wurdest auch nicht satt.',
        29: 'Und du mehrtest deine Buhlerei bis in das Land des Handels Chaldäa, und auch da bist du nicht satt geworden.',
        30: 'Wie verschmachtet dein Herz, spricht der Herr Jehovah, weil du all dies tust, das Werk eines buhlerischen, herrischen Weibes.',
        31: 'Indem du deine Hochwarte bautest am Anfang jedes Weges und deine Höhe machtest in jeder Straße, warst du nicht wie die Buhlerin, die ihrer Buhlgabe sich brüstet?',
        32: 'Das ehebrecherische Weib nimmt anstatt ihres Mannes Fremde an.',
        33: 'Man gibt jeglicher Buhlerin ein Buhlgeschenk, aber du gibst allen deinen Liebhabern deine Buhlgeschenke, und beschenkst sie, daß sie von ringsumher zu deiner Buhlschaft zu dir kommen.',
        34: 'Und ist bei dir das Umgekehrte gegen die Weiber bei deinen Buhlereien, daß dir nicht nachgebuhlt wird, und damit, daß du die Buhlgabe gibst und dir keine Buhlgabe gegeben wird. Und du warst zum Umgekehrten.',
        35: 'Darum, Buhlerin, höre das Wort Jehovahs!',
        36: 'So spricht der Herr Jehovah: Weil dein Erz ausgeschüttet ist und deine Blöße aufgedeckt in deinen Buhlereien mit deinen Liebhabern und mit allen Götzen deiner Greuel und ob dem Blute deiner Söhne, die du ihnen hast gegeben;',
        37: 'Darum, siehe, will Ich zusammenbringen alle deine Liebhaber, denen du angenehm gewesen und alle, die du geliebt hast, mit allen, die du gehaßt hast, und Ich will sie zusammenbringen wider dich von ringsumher, und will deine Blöße vor ihnen aufdecken, daß sie alle deine Blöße sehen,',
        38: 'Und Ich will richten über dich Gerichte der Ehebrecherinnen und derer, die Blut vergießen, und gebe dich zum Blut des Grimmes und des Eifers.',
        39: 'Und Ich gebe dich in ihre Hand, daß sie deine Hochwarten umreißen, und abbrechen deine Höhen und dir deine Kleider ausziehen, und sie nehmen die Geräte deines Schmuckes, und dich nackt und bloß lassen;',
        40: 'Und sie bringen eine Versammlung wider dich herauf, die mit dem Stein dich sollen steinigen und mit ihren Schwertern zerstücken.',
        41: 'Und deine Häuser verbrennen sie mit Feuer und tun an dir Gerichte vor vieler Weiber Augen. Und ich mache deiner Buhlerei ein Ende und du sollst keine Buhlgabe mehr geben.',
        42: 'Und Ich lasse ruhen Meinen Grimm wider dich, und Mein Eifer weicht von dir, und Ich raste und bin nicht mehr gereizt.',
        43: 'Weil du der Tage deiner Jugend nicht gedacht und Mich mit alledem hast aufgebracht, siehe, so gebe auch Ich deinen Weg dir auf dein Haupt, spricht der Herr Jehovah, auf daß du nicht tust zu allen deinen Greueln noch Unzucht.',
        44: 'Siehe, jeder, der Sprichworte redet, wird über dich das Sprichwort reden und sagen: Wie die Mutter, so ihre Tochter.',
        45: 'Die Tochter deiner Mutter bist du, die ihres Mannes und ihrer Söhne überdrüssig ward; und die Schwester deiner Schwestern bist du, die ihrer Männer und ihrer Söhne überdrüssig wurden; eure Mutter ist eine Chethiterin und euer Vater ein Amoriter.',
        46: 'Und deine große Schwester ist Schomron, sie und ihre Töchter, die dir zu Linken wohnt; und deine kleine Schwester, die zu deiner Rechten wohnt, ist Sodom und ihre Töchter.',
        47: 'Nicht bist du in ihren Wegen gewandelt und hast nach ihren Greueln getan. Um ein wenig verdroß es dich, und du hast in allen deinen Wegen Verderblicheres denn sie getan.',
        48: 'Bei Meinem Leben, spricht der Herr Jehovah, deine Schwester Sodom, sie und ihre Töchter haben nicht getan, wie du und deine Töchter getan habt.',
        49: 'Siehe, das war deiner Schwester Sodom Missetat: Stolz, Sättigung an Brot und sorgloses Rasten bei ihr und ihren Töchtern, und die Hand des Elenden und Dürftigen hat sie nicht gestärkt.',
        50: 'Sie wurden aber hoffärtig und taten Greuel vor Mir, und Ich tat sie hinweg, wie Ich es sah.',
        51: 'Schomron hatte nicht die Hälfte deiner Sünden gesündigt, und du mehrtest deine Greuel mehr denn sie und hast deine Schwester gerechtfertigt durch alle deine Greuel, die du getan.',
        52: 'So trage auch du denn deine Schande, wozu du deine Schwester verurteiltest; durch deine Sünden, durch die du dich greulicher denn sie gemacht, machst du sie gerechter denn du, und auch du schäme dich und trage deine Schande, daß deine Schwestern du gerechtfertigt hast.',
        53: 'Ich aber bringe zurück ihre Gefangenschaft, Sodoms und seiner Töchter Gefangenschaft und Schomrons und seiner Töchter Gefangenschaft und die Gefangenen deiner Gefangenschaft in ihrer Mitte.',
        54: 'Auf daß du tragest deine Schande und bist zuschanden worden ob allem, das du tatest, indem du ihnen zum Troste wirst.',
        55: 'Und deine Schwestern Sodom und ihre Töchter sollen zurückkehren in ihren früheren Stand und Schomron und seine Töchter werden zurückkehren in ihren früheren Stand, und du und deine Töchter sollet zurückkehren in euren früheren Stand.',
        56: 'Und war nicht deine Schwester Sodom am Tage deines Stolzes zum Gerücht in deinem Mund,',
        57: 'Ehe deine Bosheit aufgedeckt war, wie zur Zeit der Schmähung von Arams Töchtern und allen seinen Umgebungen, den Töchtern der Philister, die ringsumher dich verhöhnen.',
        58: 'Deine Unzucht und deine Greuel hast du getragen, spricht Jehovah.',
        59: 'Denn also spricht der Herr Jehovah: Und Ich tue dir, wie du hast getan, weil du den Eid hast verachtet und den Bund zunichte gemacht.',
        60: 'Ich will aber Meines Bundes mit dir in den Tagen deiner Jugend gedenken und einen Bund mit dir aufrichten der Ewigkeit.',
        61: 'Du aber sollst gedenken deiner Wege, und Schande fühlen, wenn du deine Schwestern nimmst, die größer sind denn du, zusamt den kleineren als du, und Ich sie dir zu Töchtern gebe, aber nicht wegen deines Bundes.',
        62: 'Aber Ich will Meinen Bund mit dir aufrichten, auf daß du wissest, daß Ich Jehovah bin.',
        63: 'Auf daß du dessen gedenkst und dich schämst und deinen Mund nicht auftun dürfest vor Schanden, wenn Ich Mich versöhne mit dir, ob allem, das du getan, spricht der Herr Jehovah.',
    },
    17: {
        1: 'Und es geschah an mich das Wort Jehovahs, sprechend:',
        2: 'Menschensohn, rätsle ein Rätsel und sprich ein Sprichwort von dem Hause Israel.',
        3: 'Und sprich: Also spricht der Herr Jehovah: Der große Adler, groß an Flügeln, mit langen Fittichen, voll Gefieder, bunt an Farben, kam auf den Libanon und nahm den Wipfel einer Zeder;',
        4: 'Das Haupt von seinen Reisern pflückte er ab und brachte es hinein in ein Land des Handels und setzte es in eine Stadt der Kaufleute.',
        5: 'Und er nahm von des Landes Samen und tat ihn in ein Feld der Saat, er nahm ihn an viel Wasser, vorsichtig setzte er ihn.',
        6: 'Und er sproßte und wurde zu einem üppigen Weinstock niedrigen Wuchses, so daß seine Ranken sich zu ihm selber wandten, und seine Wurzeln unter ihm waren; und er ward zu einem Weinstock und machte Zweige und entsandte Schosse.',
        7: 'Und da war ein großer Adler, groß an Flügeln und mit viel Gefieder, und siehe, dieser Weinstock bog seine Wurzeln zu ihm hin und entsandte seine Ranken nach ihm, daß er ihn tränkete von den Beeten seiner Pflanzung.',
        8: 'In einem guten Felde, an vielen Wassern war er eingepflanzt, daß er solle Zweige machen und Frucht tragen, so daß er ein stattlicher Weinstock wäre.',
        9: 'Sprich: Also spricht der Herr Jehovah: Wird er gedeihen? Wird man nicht seine Wurzeln ausreißen, und seine Frucht abstreifen, daß er verdorrt, daß all sein abgepflücktes Gesproß verdorrt? Aber ohne einen großen Arm und viel Volk wird man ihn von seinen Wurzeln erheben.',
        10: 'Und siehe, er ist eingepflanzt, wird der gedeihen? Wenn ihn berührt der Wind von Osten, wird er nicht ganz verdorren? Wird er nicht in den Beeten, da er sproßt, verdorren?',
        11: 'Und es geschah das Wort Jehovahs zu mir, sprechend:',
        12: 'Sprich doch zu dem widerspenstigen Haus: Wißt ihr nicht, was dies ist? Sprich: Siehe, der König Babels kommt nach Jerusalem und nimmt dessen König und seine Obersten und bringt sie zu sich hinein nach Babel.',
        13: 'Und er nahm einen vom Samen des Königtums und schloß einen Bund mit ihm, und ging einen Eid ein mit ihm, und die Widder des Landes nahm er.',
        14: 'Auf daß das Königreich niedrig sei und sich nicht erhebe, den Bund halte und dastehe.',
        15: 'Und er empörte sich wider ihn und sandte seine Boten nach Ägypten, daß man ihm Rosse und viel Volkes gebe. Wird es ihm gelingen? Wird der entrinnen, der solches tut? Und er hat den Bund zunichte gemacht und sollte entrinnen?',
        16: 'Bei Meinem Leben, spricht der Herr Jehovah: Er wird am Ort des Königs, der ihn zum König machte, dessen Eid er verachtet und dessen Bund er zunichte gemacht hat, bei ihm inmitten Babels sterben.',
        17: 'Und nicht mit großer Streitmacht und vieler Versammlung wird Pharao mit ihm tun im Streite, wenn einen Wall man aufschüttet und ein Bollwerk baut, um viele Seelen auszurotten.',
        18: 'Und er hat den Eid verachtet, daß er den Bund zunichte machte, und siehe, er hatte seine Hand gegeben und alles dies getan; er wird nicht entrinnen.',
        19: 'Darum, so spricht der Herr Jehovah, werde Ich, bei Meinem Leben, Meinen Eid, den er verachtet, und Meinen Bund, den er zunichte gemacht hat, auf sein Haupt geben.',
        20: 'Und Mein Netz über ihn ausbreiten, daß er erfaßt wird in Meinem Garn, und werde ihn nach Babel hineinbringen und rechten allda mit ihm ob der Untreue, die er an Mir begangen.',
        21: 'Und all seine Auserwählten, in allen seinen Scharen sollen durch das Schwert fallen, und die, so verblieben, ausgebreitet werden in allen Wind, und ihr sollt wissen, daß Ich, Jehovah, geredet habe.',
        22: 'So spricht der Herr Jehovah: Und Ich nehme vom Wipfel der emporragenden Zeder und gebe es, Ich pflücke vom Haupte ihrer Reiser ein zartes ab, und Ich pflanze es ein auf einen hohen und ragenden Berg.',
        23: 'Ich will es einpflanzen auf den emporragenden Berg Israels, daß es den Zweig erhebe und Frucht trage und zur stattlichen Zeder werde, und unter ihm jeder Vogel jeglichen Gefieders wohne; im Schatten seiner Zweige sollen sie wohnen.',
        24: 'Und alle Bäume des Feldes sollen wissen, daß Ich, Jehovah, erniedrige den hohen Baum, daß Ich hoch mache den niedrigen Baum, verdorren lasse den grünen Baum, und aufsprossen den dürren Baum. Ich, Jehovah, habe geredet, und Ich tue es.',
    },
    18: {
        1: 'Und es geschah an mich das Wort Jehovahs, sprechend:',
        2: 'Was führt ihr auf Israels Boden dies Sprichwort, daß ihr sagt: Die Väter essen Herlinge und den Söhnen werden die Zähne stumpf davon?',
        3: 'Bei Meinem Leben, spricht der Herr Jehovah, ihr sollt dies Sprichwort nimmer führen in Israel.',
        4: 'Seht, Mein sind sie, alle Seelen, wie des Vaters Seele, so des Sohnes Seele, sie sind Mein. Die Seele, die da sündigt, sie soll sterben.',
        5: 'Und der Mann, so da gerecht ist, und Recht tut und Gerechtigkeit,',
        6: 'Der auf den Bergen nicht ißt, und seine Augen nicht erhebt zu den Götzen des Hauses Israels und nicht verunreinigt seines Nächsten Weib, und dem Weibe in ihrer Unreinheit nicht naht;',
        7: 'Und der Mann, der nicht bedrückt, sein Pfand für die Schuld zurückgibt, keinen ausplündert, dem Hungernden sein Brot gibt und den Nackten bedeckt mit einem Kleide,',
        8: 'Nicht gibt auf Wucher, und keine Mehrung nimmt, vom Verkehrten seine Hand zurückwendet, ein wahrhaft Urteil tut zwischen Mann und Mann,',
        9: 'Wandelt in Meinen Satzungen und hält Meine Rechte, daß er Wahrheit tue: gerecht ist er, er soll leben, spricht der Herr Jehovah.',
        10: 'Und zeugt er einen Sohn, einen Räuber, der Blut vergießt, und tut auch nur deren eines;',
        11: 'Und er tut das alles nicht: denn er ißt auf den Bergen und verunreinigt das Weib seines Nächsten,',
        12: 'Der den Elenden und Dürftigen bedrükket, der ausplündert, das Pfand nicht zurückgibt und zu den Götzen erhebt seine Augen, Greuel tut,',
        13: 'Auf Wucher gibt und Mehrung nimmt. Und der soll leben? Nicht soll er leben! All diese Greuel tut er. Er soll des Todes sterben. Sein Blut soll auf ihm sein!',
        14: 'Und siehe, er zeugt einen Sohn, und der sieht alle Sünden seines Vaters, die er tut, und er fürchtet sich und tut nicht dergleichen;',
        15: 'Ißt nicht auf den Bergen und erhebt nicht seine Augen zu den Götzen des Hauses Israels und verunreinigt nicht seines Nächsten Weib;',
        16: 'Und bedrückt den Mann nicht, behält kein Pfand zurück und plündert nicht aus, gibt dem Hungrigen sein Brot, und bedeckt den Nackten mit einem Kleid,',
        17: 'Kehrt von dem Elenden die Hand nicht zurück, nimmt nicht Wucher, noch Mehrung, tut Meine Rechte, wandelt in Meinen Satzungen - er soll nicht sterben ob seines Vaters Missetat! Er soll leben!',
        18: 'Sein Vater, der mit Erpressung erpreßte, den Bruder ausplünderte, und der nicht das Gute tat inmitten seines Volkes, und siehe, der stirbt in seiner Missetat.',
        19: 'Und sprechet ihr: Warum soll denn der Sohn an des Vaters Missetat nicht tragen? Weil der Sohn Recht und Gerechtigkeit getan, all Meine Satzungen gehalten und sie getan, soll er leben.',
        20: 'Die Seele, die da sündigt, sie soll sterben. Der Sohn soll nicht tragen an der Missetat des Vaters, und der Vater soll nicht tragen an der Missetat des Sohnes, des Gerechten Gerechtigkeit soll sein auf ihm, und die Unge- rechtigkeit des Ungerechten soll auf ihm sein.',
        21: 'Wo aber der Ungerechte zurückkehrt von allen seinen Sünden, die er getan, und hält alle Meine Satzungen, und tut Recht und Gerechtigkeit, der soll gewißlich leben; er soll nicht sterben.',
        22: 'All seiner Übertretungen, die er getan, soll ihm nicht mehr gedacht werden, er soll leben in seiner Gerechtigkeit, die er hat getan.',
        23: 'Habe Ich Lust am Tode des Ungerechten, spricht der Herr Jehovah, und nicht an seiner Rückkehr von seinen Wegen, daß er lebe?',
        24: 'Und wo der Gerechte kehrt zurück von seiner Gerechtigkeit und tut Verkehrtes nach all den Greueln, die der Ungerechte tut, sollte der es tun und leben? All seiner Gerechtigkeit, die er getan, wird man nicht mehr gedenken in der Untreue, die er begangen und in den Sünden, die er gesündigt hat, in ihnen soll er sterben!',
        25: 'Und ihr sprecht: Nicht recht ist der Weg des Herrn. So höret doch, ihr Haus Israel: Ist denn Mein Weg nicht recht, und sind nicht eure Wege nicht recht?',
        26: 'Wenn der Gerechte sich zurückkehrt von seiner Gerechtigkeit und tut Verkehrtes, so stirbt er darob. Ob seiner Verkehrtheit, die er tat, stirbt er.',
        27: 'Und wenn der Ungerechte zurückkehrt von seiner Ungerechtigkeit, die er getan, und Recht tut und Gerechtigkeit, soll seine Seele er am Leben erhalten.',
        28: 'Denn er sah es und kehrte zurück von allen seinen Übertretungen, die er getan, er soll leben, soll nicht sterben.',
        29: 'Und die vom Hause Israel sprechen: Des Herrn Weg ist nicht recht. Sind Meine Wege nicht recht, du Haus Israel, sind nicht eure Wege nicht recht?',
        30: 'Darum werde Ich euch, jeden Mann nach seinen Wegen, richten, Haus Israel, spricht der Herr Jehovah. Kehrt zurück und wendet euch zurück von allen euren Übertretungen, daß die Missetat euch nicht zum Anstoß werde.',
        31: 'Werfet von euch all eure Übertretungen, wodurch ihr abgefallen waret, und machet euch ein neues Herz und einen neuen Geist! Denn warum wollt ihr sterben, ihr vom Hause Israel?',
        32: 'Denn Ich habe keine Lust am Tod des Sterbenden, spricht der Herr Jehovah; darum kehrt zurück und lebet.',
    },
    19: {
        1: 'Und du erhebe ein Trauerlied über die Fürsten Israels,',
        2: 'Und sprich: Was war deine Mutter? Eine alte Löwin, unter Löwen lagerte sie, inmitten junger Löwen erzog sie ihre Jungen.',
        3: 'Und es stieg herauf eines von ihren Jungen. Ein junger Löwe war es, und lernte zerfleischen, Menschen fressen.',
        4: 'Und von ihm hörten die Völkerschaften; er ward in ihrer Fallgrube erfaßt, und an Haken brachten sie ihn herein nach dem Land Ägypten.',
        5: 'Sie aber sah, daß sie gewartet, aber ihre Hoffnung verloren war, und nahm ihrer Jungen eines, setzte es zum jungen Löwen.',
        6: 'Und inmitten der Löwen ging er einher, ward zum jungen Löwen und lernte das Zerfleischen, fraß Menschen.',
        7: 'Und erkannte ihre Witwen und verödete ihre Städte, und verwüstete das Land und seine Fülle durch die Stimme seines Brüllens.',
        8: 'Und die Völkerschaften setzten sich wider ihn aus den Landschaften ringsumher, und breiteten ihr Netz aus wider ihn, und in ihrer Fallgrube ward er erfaßt.',
        9: 'Und sie taten ihn in den Käfig an Haken und brachten ihn herein zum König von Babel und brachten ihn in die Festen, damit seine Stimme nicht mehr auf Israels Bergen gehört würde.',
        10: 'Deine Mutter war wie ein Weinstock, dir ähnlich, am Wasser hingepflanzt; fruchtbar und rebenvoll ward er vom vielen Wasser.',
        11: 'Und hatte starke Stäbe zu Zeptern der Herrscher, und sein Wuchs ward hoch zwischen Dichtverflochtenem; so ward er sichtbar durch seine Höhe, durch die Menge seiner Zweige.',
        12: 'Aber er ist im Grimm ausgerissen, zur Erde geworfen, und der Wind vom Osten hat verdorrt seine Frucht. Abgerissen und verdorrt wurden die Stäbe seiner Stärke. Das Feuer fraß sie.',
        13: 'Und nun ist er eingepflanzt in die Wüste, in ein Land der Dürre und des Durstes;',
        14: 'Und nun ist von dem Stabe seiner Zweige Feuer ausgegangen, es frißt auf seine Frucht, und ist daran kein Stab der Stärke zum Zepter eines Herrschers. Ein Trauerlied ist es, und ward zum Trauerlied.',
    },
    20: {
        1: 'Und es geschah im siebenten Jahr am zehnten im fünften Monat, daß Männer von den Ältesten Israels kamen, Jehovah zu befragen, und sie saßen vor mir.',
        2: 'Und es geschah zu mir das Wort Jehovahs, sprechend:',
        3: 'Menschensohn, rede mit den Ältesten von Israel und sprich zu ihnen: Also spricht der Herr Jehovah: Seid ihr gekommen, Mich zu befragen? Bei Meinem Leben lasse Ich Mich von euch nicht befragen, spricht der Herr Jehovah.',
        4: 'Willst du sie richten, willst du sie richten, Menschensohn, so tue ihnen die Greuel ihrer Väter zu wissen.',
        5: 'Und sprich zu ihnen: Also spricht der Herr Jehovah: Am Tage, da Ich Israel erwählte, und erhob Meine Hand für den Samen des Hauses Jakob und tat Mich ihnen zu wissen im Land Ägypten, und erhob ihnen Meine Hand, sprechend: Ich bin Jehovah, euer Gott.',
        6: 'An selbem Tag erhob Ich Meine Hand für sie, sie herauszubringen aus dem Land Ägypten in ein Land, das für sie Ich ausgespäht hatte, das von Milch und Honig fließt, das die Zierde für alle Länder ist.',
        7: 'Und Ich sprach zu ihnen: Werft ein jeder Mann die Scheusale seiner Augen hin, und mit den Götzen Ägyptens verunreinigt euch nicht! Ich, Jehovah, bin euer Gott.',
        8: 'Und sie wurden widerspenstig wider Mich und wollten nicht auf Mich hören, und kein Mann warf die Scheusale seiner Augen weg, und sie verließen Ägyptens Götzen nicht, so daß Ich sprach, Ich wollte Meinen Grimm ausschütten über sie, allen Meinen Zorn an ihnen zu vollenden mitten im Lande Ägypten.',
        9: 'Aber Ich tat es um Meines Namens willen, daß er nicht entweiht würde vor den Augen der Völkerschaften, in deren Mitte sie waren, denen Ich vor deren Augen war bekannt geworden, daß Ich sie herausbrachte aus dem Lande Ägypten.',
        10: 'Und Ich brachte sie heraus aus dem Lande Ägypten und brachte sie herein in die Wüste,',
        11: 'Und gab ihnen Meine Satzungen und tat ihnen Meine Rechte zu wissen, die der Mensch tun soll, daß er durch sie lebe.',
        12: 'Und auch Meine Sabbathe habe Ich ihnen gegeben, daß sie zum Zeichen seien zwischen Mir und ihnen, auf daß sie wüßten, daß Ich, Jehovah, bin, Der sie heiligt.',
        13: 'Aber das Haus Israels war widerspenstig wider Mich in der Wüste; sie wandelten nicht in Meinen Satzungen und verschmähten Meine Rechte, die der Mensch tun soll, daß er durch sie lebe. Und sie entweihten Meine Sabbathe sehr. Und Ich sagte, daß Ich Meinen Grimm in der Wüste werde ausschütten über sie, um sie alle zu machen.',
        14: 'Aber Ich tat es um Meines Namens willen, daß er nicht entweiht würde vor den Augen der Völkerschaften, vor deren Augen Ich sie herausgebracht hatte.',
        15: 'Und auch in der Wüste erhob Ich Meine Hand wider sie, daß Ich sie nicht wollte in das Land hereinbringen, das Ich ihnen gab, welches von Milch und Honig fließt, das die Zierde für alle Länder ist;',
        16: 'Weil sie Meine Rechte verschmähten und in Meinen Satzungen nicht wandelten und Meine Sabbathe entweihten, indem ihr Herz wandelte ihren Götzen nach.',
        17: 'Aber Mein Auge schonte ihrer, daß Ich sie nicht verdarb, und Ich es mit ihnen nicht alle machte in der Wüste.',
        18: 'Und Ich sprach zu ihren Söhnen in der Wüste: Ihr sollt nach eurer Väter Satzungen nicht wandeln und nicht halten ihre Rechte, noch mit ihren Götzen euch verunreinigen.',
        19: 'Ich, Jehovah, bin euer Gott. Nach Meinen Satzungen sollt ihr wandeln und Meine Rechte halten und sie tun.',
        20: 'Und Meine Sabbathe sollt ihr heiligen, daß sie ein Zeichen seien zwischen Mir und euch, auf daß ihr wisset, daß Ich, Jehovah, euer Gott bin.',
        21: 'Aber die Söhne waren gegen Mich widerspenstig, sie wandelten nicht in Meinen Satzungen und hielten Meine Rechte nicht, daß sie solche getan hätten, die der Mensch tut und durch sie lebt. Meine Sabbathe entweihten sie; und Ich sagte, Ich wolle Meinen Grimm ausschütten über sie, daß Mein Zorn sie alle mache in der Wüste.',
        22: 'Ich kehrte aber Meine Hand zurück und tat es um Meines Namens willen, auf daß er vor den Augen der Völkerschaften nicht entweiht würde, vor deren Augen Ich sie herausgebracht hatte.',
        23: 'Auch hob Ich in der Wüste Meine Hand auf wider sie, sie zu zerstreuen unter die Völkerschaften und sie zu zersprengen in die Länder,',
        24: 'Weil sie Meine Rechte nicht taten und Meine Satzungen verschmähten und Meine Sabbathe entweihten und nach den Götzen ihrer Väter waren ihre Augen.',
        25: 'Und darum gab Ich ihnen auch Satzungen, die nicht gut waren, und Rechte, darinnen sie kein Leben haben konnten.',
        26: 'Und ließ sie sich verunreinigen an ihren Gaben, daß sie durch das Feuer durchführten alles, was die Mutter bricht, sie zu verwüsten, auf daß sie wüßten, daß Ich Jehovah bin.',
        27: 'Darum, Menschensohn, sollst du reden zu dem Haus Israel und zu ihnen sprechen: So spricht der Herr Jehovah: Noch darin verhöhnten Mich eure Väter, daß Untreue sie wider Mich begingen.',
        28: 'Und Ich brachte sie herein zu dem Land, das Ich Meine Hand aufgehoben, ihnen zu geben; und wenn sie sahen irgendeinen emporragenden Hügel, oder irgendeinen dichtbelaubten Baum, so opferten sie da ihre Opfer, und gaben da den Unmut ihrer Opfergaben, und legten hin den Geruch der Ruhe, und gossen ihre Trankopfer aus.',
        29: 'Und Ich sprach zu ihnen: Was ist die Opferhöhe, wohin ihr kommt? Und ihr Name wurde genannt bis auf diesen Tag Bamah.',
        30: 'Darum sprich zum Hause Israels: So spricht der Herr Jehovah: Wollt ihr euch auf dem Wege eurer Väter verunreinigen und ihren Scheusalen nachbuhlen?',
        31: 'Und wenn ihr eure Gaben erhebt, wenn ihr eure Söhne in das Feuer hindurchführt, ihr euch mit allen euren Götzen verunreinigt bis auf diesen Tag, sollte Ich Mich von euch, o Haus Israels, befragen lassen? Bei Meinem Leben, spricht der Herr Jehovah, Ich lasse Mich nicht von euch befragen.',
        32: 'Und das, was in eurem Geist aufsteigt, soll nicht geschehen - wie ihr sprecht: Laßt uns sein wie die Völkerschaften, wie die Familien der Länder, daß wir dem Holze und dem Steine Dienst tun.',
        33: 'Bei Meinem Leben, spricht der Herr, Jehovah, mit starker Hand und mit ausgestrecktem Arm und ausgeschüttetem Grimm will Ich über euch regieren,',
        34: 'Und aus den Völkern euch herausbringen und euch zusammenbringen aus den Ländern, wohin ihr zerstreut seid, mit starker Hand und mit ausgestrecktem Arm und mit ausgeschüttetem Grimm,',
        35: 'Und werde euch hereinbringen zu der Wüste der Völker und mit euch allda rechten von Angesicht zu Angesicht.',
        36: 'Wie Ich mit euren Vätern habe gerechtet in der Wüste beim Lande Ägypten, so will Ich mit euch rechten, spricht der Herr Jehovah,',
        37: 'Und lasse euch dann vorüberziehen, unter der Rute und bringe euch herein in das Band des Bundes,',
        38: 'Und scheide von euch aus die Empörer und die von Mir abfielen. Herausbringen werde Ich sie vom Lande ihrer Wanderungen, aber auf den Boden Israels soll keiner kommen, auf daß ihr wisset, daß Ich Jehovah bin.',
        39: 'Und ihr vom Hause Israels - so spricht der Herr Jehovah - geht, dienet, ein jeder Mann seinen Götzen, danach aber, wenn ihr nicht auf Mich hört, so entweiht nicht mehr Meinen Namen mit euren Gaben und mit euren Götzen.',
        40: 'Denn auf dem Berge Meiner Heiligkeit, auf dem Berg der Höhe Israels, spricht der Herr Jehovah, allda wird dienen Mir das ganze Haus Israels, sie alle im Lande. Dort werde Ich Wohlgefallen haben an ihnen, und allda will Ich fordern eure Hebeopfer und eure Opfergaben, Erstlinge von allem, was ihr Mir heiligt.',
        41: 'Durch den Geruch der Ruhe werde Ich an euch Wohlgefallen haben, wenn Ich euch von den Völkern herausgebracht und euch zusammengebracht habe aus den Ländern, dahin ihr seid zerstreut worden, und werde in euch geheiligt werden in den Augen der Völkerschaften.',
        42: 'Und ihr sollt wissen, daß Ich Jehovah bin, wenn Ich euch auf Israels Boden hereingebracht, in das Land, das Meine Hand Ich erhob, zu geben euren Vätern.',
        43: 'Und allda werdet ihr gedenken eurer Wege und aller eurer Handlungen, durch die ihr euch verunreinigt habt, und euch selbst zum Verdruß geworden seid durch all eure Bosheiten, die ihr getan.',
        44: 'Und ihr sollt wissen, daß Ich Jehovah bin, wenn Ich mit euch tue um Meines Namens willen, nicht nach euren bösen Wegen und euren verderblichen Handlungen, du Haus Israel, spricht der Herr Jehovah.',
    },
    21: {
        1: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        2: 'Menschensohn, richte dein Angesicht gen Süden und träufle dem Südwinde zu und weissage über den Wald des Feldes im Mittage,',
        3: 'Und sprich zum Wald im Mittag: Höre das Wort Jehovahs: So spricht der Herr Jehovah: Siehe, Ich entzünde in dir ein Feuer, und es soll in dir allen grünen Baum und allen dürren Baum auffressen, und soll die lohe Flamme nicht erlöschen, und sollen von ihr alle Flächen von Mittag nach Mitternacht verbrannt werden.',
        4: 'Und alles Fleisch soll sehen, daß Ich, Jehovah, es brennen lasse. Nicht soll es erlöschen.',
        5: 'Und ich sprach: Ach, Herr Jehovah, sie sagen von mir: Führt er nicht Sprichwörter?',
        6: 'Und es geschah Jehovahs Wort zu mir, sprechend:',
        7: 'Menschensohn, richte dein Angesicht gen Jerusalem und laß träufeln gegen die Heiligtümer und weissage wider den Boden Israels.',
        8: 'Und sprich zum Boden Israels: So spricht Jehovah: Siehe, Ich bin wider dich und ziehe Mein Schwert heraus aus seiner Scheide und rotte aus von dir den Gerechten und den Ungerechten.',
        9: 'Weil Ich von dir ausrotte den Gerechten und den Ungerechten, darum geht heraus Mein Schwert aus seiner Scheide über alles Fleisch von Mittag bis gen Mitternacht.',
        10: 'Und alles Fleisch soll wissen, daß Ich, Jehovah, Mein Schwert aus seiner Scheide zog, es kehrt nimmer zurück.',
        11: 'Und du, Menschensohn, seufze, daß die Lenden dir brechen, und seufze bitterlich vor ihren Augen.',
        12: 'Und es wird geschehen, daß sie zu dir sprechen: Warum seufzest du? Und du sollst sprechen: Ob dem Gerücht, das da kommt. Ein jeglich Herz wird zerschmelzen und alle Hände erschlaffen, aller Geist wird getrübt, und alle Knie gehen im Wasser. Siehe, es kommt und es geschieht, spricht der Herr Jehovah.',
        13: 'Und es geschah zu mir das Wort Jehovahs, sprechend:',
        14: 'Menschensohn, weissage und sprich: So spricht Jehovah: Sprich: Das Schwert, das Schwert! Geschärft und auch blank gemacht ist es.',
        15: 'Zu schlachten eine Schlachtung, ist es geschärft; auf daß es werde zum Blitz, ist es blank gemacht. Oder sollen wir uns freuen? Die Rute meines Sohnes verschmäht jeglich Holz.',
        16: 'Und er gab es zum Blankmachen, um es mit der Hand zu fassen. Es ist geschärft, das Schwert, und ist blank gemacht, um es zu geben in die Hand des Würgers.',
        17: 'Schreie und heule, Menschensohn; denn es ist wider Mein Volk, es ist wider all die Fürsten Israels. Dem Schwert verfallen sind sie samt Meinem Volk, darum schlage an deine Hüfte.',
        18: 'Denn es ist eine Prüfung. Und wozu? wenn auch die verschmähte Rute nicht mehr ist! spricht der Herr Jehovah.',
        19: 'Du aber, Menschensohn, weissage und schlage Hand auf Hand. Zum drittenmal wiederhole sich das Schwert, das Schwert der Erschlagenen, es ist das Schwert der großen Erschlagung für sie in den Kammern.',
        20: 'Auf daß das Herz zerfließe, und das Straucheln sich mehre, und Ich richte die Spitze des Schwertes wider alle ihre Tore, nur gemacht zum Blitze, zum Schlachten gewetzt.',
        21: 'Einige dich, wende dich rechts, richte dich, wende dich links, wohin du dein Angesicht kehren magst.',
        22: 'Und auch Ich werde Hand auf Hand schlagen und zur Ruhe bringen Meinen Grimm. Ich, Jehovah, habe geredet.',
        23: 'Und es geschah Jehovahs Wort zu mir. Er sprach:',
        24: 'Und du, Menschensohn, setze dir zwei Wege, auf denen das Schwert des Königs von Babel kommen soll. Aus einem Land sollen beide ausgehen; und schaffe einen Wegweiser. Am Anfang des Weges nach der Stadt sollst du ihn schaffen.',
        25: 'Den Weg sollst du setzen, daß das Schwert komme gen Rabbath der Söhne Ammons, und gen Jehudah in das befestigte Jerusalem.',
        26: 'Denn Babels König steht an der Wegscheide still, am Anfang der zwei Wege, um sich wahrsagen zu lassen, er schüttelt die Pfeile, er fragt die Theraphim, besieht die Leber.',
        27: 'Zu seiner Rechten ist die Wahrsagung Jerusalem, die Sturmböcke zu setzen, ein Loch zu öffnen, durch Zerstoßung die Stimme zu erhöhen im Feldgeschrei, die Sturmböcke zu setzen wider die Tore, aufzuschütten einen Wall, Bollwerk zu bauen.',
        28: 'Doch wie eitel Wahrsagerei ist es in ihren Augen, mit Schwüren ihnen beschworen. Und er läßt sie gedenken der Missetat, sie zu erfassen.',
        29: 'Darum spricht also der Herr Jehovah: Weil er euch gedenken ließ an eure Missetat durch Aufdeckung eurer Übertretungen, euch eure Sünden sehen ließ in allen euren Handlungen, darum, daß er euch derselben gedenken ließ, sollt ihr mit der Hand erfaßt werden.',
        30: 'Und du, Erschlagener, ungerechter Fürst Israels, dessen Tag kommt, zur Zeit der Missetat des Endes.',
        31: 'So spricht der Herr Jehovah: Nimm weg die Tiare, erhöhet die Krone! Das sei nicht so! Das Niedrige soll erhöht und das Hohe erniedrigt werden.',
        32: 'Verdreht, verdreht, verdreht setze Ich sie; auch das soll nicht so sein, bis der kommt, der das Gericht hat, und dem Ich es gebe. Du aber, Menschensohn, weissage und sprich: So spricht der Herr Jehovah über die Söhne Ammons und über ihre Schmähung, und sprich: Schwert, Schwert, gezückt zum Schlachten, blank gemacht zum Verzehren, daß es zum Blitz sei. Als du dir Eitles schauen und dir Falsches wahrsagen ließest, um dich zu legen über die Hälse der Erschlagenen, der Ungerechten, deren Tag kommt zur Zeit der Missetat des Endes; Laß zurück es kehren in seine Scheide; am Ort, da du erschaffen wardst, im Lande deines Handels richte Ich dich, Und schütte Meinen Unwillen aus über dich, mit dem Feuer Meines Wütens hauche Ich dich an und gebe dich in die Hand brennender Männer, der Werkleute des Verderbens. Dem Feuer sollst du zur Speise werden. Dein Blut soll sein in des Landes Mitte. Nicht soll man deiner mehr gedenken; denn Ich, Jehovah, habe es geredet.',
    },
    22: {
        1: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        2: 'Du aber, Menschensohn, willst du richten, willst du richten die Stadt des Blutes, und sie wissen lassen all ihre Greuel?',
        3: 'Und sprich: So spricht der Herr Jehovah: Stadt, die in ihrer Mitte Blut vergossen, daß ihre Zeit komme, und Götzen für sich gemacht hat zu ihrer Verunreinigung,',
        4: 'Durch dein Blut, das du vergossen, bist du schuldig und hast durch die Götzen, die du machtest, dich verunreinigt, und hast nahen lassen deine Tage und bist zu deinen Jahren gekommen. Darum gebe Ich dich den Völkerschaften, zur Schmähung und zum Schimpf allen Landen.',
        5: 'Die Nahen und die ferne von dir sind, beschimpfen dich, die du unrein von Namen, mit vielem Getümmel bist,',
        6: 'Siehe, die Fürsten Israels sind jeder Mann nach seinem Arm in dir, Blut zu vergießen.',
        7: 'Vater und Mutter achten sie gering in dir. Am Fremdling tun sie Erpressung in deiner Mitte. Waise und Witwe bedrücken sie in dir.',
        8: 'Meine Heiligtümer hast du verachtet und Meine Sabbathe entweiht.',
        9: 'Zwischenträgerische Männer sind in dir, Blut zu vergießen; und auf den Bergen aßen sie in dir und taten Schandtat in deiner Mitte.',
        10: 'Man deckt die Blöße des Vaters auf, und sie schwächten die Unreine in ihrer Befleckung.',
        11: 'Und ein Mann tut Greuel mit des Genossen Weib. Und mit der Schnur verunreinigt sich der Mann durch Schandtat; der Mann schwächt seine Schwester, seines Vaters Tochter, in dir.',
        12: 'Geschenk nehmen sie in dir, Blut zu vergießen. Wucher und Mehrung nimmst du und übervorteilst durch Erpressung deinen Nächsten, und vergessen Meiner, spricht der Herr Jehovah.',
        13: 'Und siehe, Ich schlage Meine Hände zusammen über dem Geiz, den du übst und dem Blute, das in deiner Mitte ist.',
        14: 'Wird dein Herz bestehen, werden deine Hände stark sein in den Tagen, da Ich mit dir zu tun habe? Ich, Jehovah, habe es geredet und tue es.',
        15: 'Und werde dich zerstreuen unter die Völkerschaften und dich zersprengen in die Länder und mache zunichte deine Unreinheit.',
        16: 'Und du sollst durch dich entweiht werden in den Augen der Völkerschaften, und sollst wissen, daß Ich Jehovah bin.',
        17: 'Und es geschah an mich Jehovahs Wort, sprechend:',
        18: 'Menschensohn, die vom Haus Israels sind Mir zu Schlacken geworden. Sie alle sind Erz und Zinn und Eisen und Blei mitten im Schmelzofen, Schlacken des Silbers sind sie.',
        19: 'Darum spricht also der Herr Jehovah: Weil ihr alle seid zu Schlacken geworden, darum, siehe, will Ich euch zusammenbringen inmitten Jerusalems,',
        20: 'Ein Zusammenbringen von Silber und Erz und Eisen und Blei und Zinn inmitten des Schmelzofens, daß man ein Feuer dafür anbläst zum Schmelzen, also will auch Ich in Meinem Zorn und Meinem Grimm euch zusammenbringen und hineinlegen und schmelzen,',
        21: 'Und euch zusammenfassen und mit dem Feuer Meines Wütens hinblasen über euch, daß ihr in seiner Mitte geschmolzen werdet.',
        22: 'Gleichwie das Silber schmilzt in des Schmelzofens Mitte, so sollt ihr in seiner Mitte geschmolzen werden, und wissen, daß Ich, Jehovah, Meinen Grimm über euch ausgeschüttet habe.',
        23: 'Und es geschah zu mir Jehovahs Wort, sprechend:',
        24: 'Menschensohn, sprich zu ihr: Du bist ein Land, das nicht gereinigt ist, nicht beregnet am Tage des Unwillens.',
        25: 'Eine Verschwörung ihrer Propheten ist in ihrer Mitte, wie der brüllende Löwe, der das Zerfleischte zerfleischt, fressen sie die Seele, Gut und Kostbarkeit nehmen sie und machen in ihr viel der Witwen.',
        26: 'Meinem Gesetze tun ihre Priester Gewalt an, und entweihen Meine Heiligtümer, zwischen Heiligem und Entweihtem scheiden sie nicht und tun nicht zu wissen, was rein und unrein ist, und vor Meinen Sabbathen verbergen sie die Augen, und Ich werde entweiht in ihrer Mitte.',
        27: 'Ihre Obersten sind in ihrer Mitte wie Wölfe, die das Zerfleischte zerfleischen, Blut zu vergießen, Seelen zu zerstören, daß sie Gewinn gewinnen.',
        28: 'Und ihre Propheten übertünchen ihnen Untaugliches, indem sie Eitles schauen und ihnen Falsches wahrsagen, sprechend: So spricht der Herr Jehovah, und Jehovah hat nicht geredet.',
        29: 'Das Volk des Landes übt Erpressung und plündert aus, bedrückt den Elenden und Dürftigen und übt Erpressung an dem Fremdling wider Recht.',
        30: 'Und Ich suchte unter ihnen nach einem Mann, der den Zaun zäunete, der vor dem Durchbruch stünde vor Mir für das Land, daß Ich es nicht verderbete, und Ich fand keinen.',
        31: 'Darum schütte Meinen Unwillen Ich über sie aus, im Feuer Meines Wütens mache Ich sie alle, Ich gebe ihren Weg auf ihr Haupt, spricht der Herr Jehovah.',
    },
    23: {
        1: 'Und es geschah das Wort Jehovahs zu mir, sprechend:',
        2: 'Menschensohn, es waren zwei Weiber, Töchter einer Mutter,',
        3: 'Und sie buhlten in Ägypten, in ihrer Jugend buhlten sie, ließen dort drücken ihre Brüste, und sie betasteten die Zitzen ihrer Jungfrauschaft.',
        4: 'Und dies sind ihre Namen: Oholah, die große, und ihre Schwester Oholibah; und sie wurden Mein, und gebaren Söhne und Töchter; und ihre Namen: Samaria ist Oholah, und Jerusalem Oholibah.',
        5: 'Und Oholah buhlte neben Mir, und es lüstete sie nach ihren Liebhabern, nach denen von Aschur, die nahe waren,',
        6: 'Die sich in blauen Purpur kleideten, Statthalter und Landvögte, Jünglinge, allesamt begehrenswert, Reiter, die auf Rossen reiten.',
        7: 'Und sie gab ihre Buhlereien über sie, die Auswahl der Söhne Aschurs allesamt, und verunreinigte sich mit allen, nach denen sie es lüstete, mit allen ihren Götzen.',
        8: 'Und ihre Buhlerei von Ägypten her verließ sie nicht, denn in ihrer Jugend lagen sie bei ihr, die Zitzen ihrer Jungfrauschaft betasteten sie, und ergossen ihre Buhlereien über sie.',
        9: 'Darum gab Ich sie in ihrer Liebhaber Hand, in die Hand der Söhne Aschurs, nach denen sie es lüstete.',
        10: 'Sie deckten ihre Blöße auf, sie nahmen ihre Söhne und ihre Töchter, sie aber erwürgten sie mit dem Schwerte, und ihr Name unter den Weibern, daß sie Gericht gehalten über sie.',
        11: 'Und ihre Schwester Oholibah, sah es, und ihre Wollust war verderblicher denn die ihrige, und ihre Buhlereien denn die Buhlereien ihrer Schwester.',
        12: 'Sie lüstete nach Aschurs Söhnen, Statthaltern und Landvögten, die nahe waren, prächtig angetan, Reiter, die auf Rossen ritten, begehrenswerte Jünglinge allesamt.',
        13: 'Und Ich sah, daß sie sich verunreinigte, einen Weg für sie beide.',
        14: 'Und sie tat hinzu zu ihren Buhlereien und sah Männer an die Wand gemalt, die Bilder der Chaldäer mit Mennigrot gemalt,',
        15: 'Umgürtet mit dem Gurt um ihre Lenden, mit überhängenden Turbanen auf ihren Häuptern, sie alle anzusehen wie Kriegshäuptlinge, nach der Ähnlichkeit der Söhne Babels, der Chaldäer, im Land ihrer Geburt;',
        16: 'Und sie lüstete nach ihnen nach den Ansehen ihrer Augen und sandte Boten zu ihnen nach Chaldäa.',
        17: 'Und zu ihr kamen Babels Söhne zum Liebeslager, und sie verunreinigten sie mit ihrer Buhlerei, und sie verunreinigte sich mit ihnen, bis ihre Seele sich von ihnen abneigte.',
        18: 'Und sie hatte ihre Buhlereien aufgedeckt und aufgedeckt ihre Blöße, und Meine Seele ward ihr abgeneigt, wie Meine Seele sich von ihrer Schwester abgeneigt hatte.',
        19: 'Und sie mehrte ihre Buhlereien, daß an die Tage ihrer Jugend sie gedachte, da sie im Land Ägypten gebuhlt hatte,',
        20: 'Und sie lüstete nach ihren Kebsmännern, deren Fleisch das Fleisch der Esel und deren Erguß der Hengste Erguß ist.',
        21: 'Und du sahst dich nach deiner Jugend Unzucht um, da man in Ägypten deine Zitzen betastete, um deiner Jugend Brüste willen.',
        22: 'Darum, Oholibah, so spricht der Herr Jehovah, siehe, Ich errege deine Liebhaber wider dich, von denen deine Seele sich abgeneigt hatte, und bringe sie ringsum wider dich herbei.',
        23: 'Die Söhne Babels und alle Chaldäer, Pekod und Schoa und Koa, alle Söhne Aschurs mit ihnen, begehrenswerte Jünglinge, Statthalter und Landvögte allesamt, Kriegshäuptlinge und Aufgerufene, reitend auf Rossen allzumal,',
        24: 'Und sie kommen wider dich mit Rasseln der Streitwagen und Räder, und mit einer Versammlung von Völkern, sie richten Schild und Tartsche und Helm ringsumher wider dich, und vor sie gebe Ich das Gericht, daß sie dich nach ihren Rechten richten,',
        25: 'Und setze Meinen Eifer wider dich, daß sie mit dir tun im Grimm, dir Nase und Ohren abschneiden, und was noch von dir nachkommt, falle durch das Schwert. Sie sollen deine Söhne und Töchter nehmen, und was nachkommt von dir, [soll] vom Feuer gefressen werden.',
        26: 'Sie sollen deine Kleider dir ausziehen und nehmen deines Schmuckes Geräte.',
        27: 'Und Ich lasse zu Ende kommen von dir deine Unzucht und deine Buhlerei vom Land Ägypten her, daß nimmer zu ihnen deine Augen du erhebst und Ägyptens nicht mehr gedenkst.',
        28: 'Denn also spricht der Herr Jehovah: Siehe, Ich gebe dich in die Hand dessen, den du haßtest, in dessen Hand, von dem sich deine Seele abgeneigt hatte.',
        29: 'Daß sie im Haß mit dir handeln, und dir all dein Erarbeitetes nehmen, und nackt und bloß dich lassen, daß die Blöße deiner Buhlereien und deine Unzucht und deine Buhlereien aufgedeckt werden.',
        30: 'Solches geschieht dir, weil du den Völkerschaften nachgebuhlt, daß mit ihren Götzen du dich verunreinigt hast.',
        31: 'Auf deiner Schwester Weg bist du gegangen, und ihren Becher gebe Ich in deine Hand.',
        32: 'So spricht der Herr Jehovah: Deiner Schwester Becher sollst du trinken, den tiefen und weiten, sollst zum Gelächter und Hohne werden - er fasset viel.',
        33: 'Voll Trunkenheit und Grames sollst du werden: denn ein Becher der Verwüstung und Wüstenei ist der Becher deiner Schwester Schomron.',
        34: 'Und sollst ihn trinken und ausdrücken und seine Scherben zermalmen und dein Brüste damit zerreißen; denn Ich habe es geredet, spricht der Herr Jehovah.',
        35: 'Darum spricht also der Herr Jehovah: Weil du Mein vergessen und hinter deinen Rücken Mich geworfen hast, so trage denn auch deine Unzucht und deine Buhlereien.',
        36: 'Und Jehovah sprach zu mir: Menschensohn, willst du Oholah und Oholibah richten und ihnen ihre Greuel ansagen?',
        37: 'Wie Ehebruch sie trieben und Blut an ihren Händen haben, und durch ihre Götzen sie die Ehe brachen, und auch ihre Söhne, die sie Mir geboren, ihnen zur Speise hindurchführten.',
        38: 'Noch taten sie Mir dies: Mein Heiligtum verunreinigten sie an jenem Tage und entweihten Meine Sabbathe,',
        39: 'Und damit, daß sie ihre Söhne ihren Götzen schlachteten, und an selbem Tage kamen in Mein Heiligtum, es zu entweihen. Und siehe, so taten sie inmitten Meines Hauses.',
        40: 'Und sie sandten auch an Männer, die aus der Ferne kommen sollten, an die ein Bote ward gesandt, und siehe, sie kamen, du hast dich für sie gebadet, deine Augen geschminkt und mit deinem Geschmeide geschmückt,',
        41: 'Und saßest auf einem herrlichen Bette, und ein Tisch ward vor dir zugerichtet, und Mein Räuchwerk und Mein Öl setztest du darauf.',
        42: 'Und die Stimme einer achtlosen Menge war in ihr, und zu den Männern der Menge der Menschen wurden Sabäer aus der Wüste hereingebracht, und sie gaben Armbänder an ihre Hände und eine Krone des Schmuckes auf ihre Häupter.',
        43: 'Und Ich sprach von der, so alt ist in Ehebrüchen: Nun buhlet sie ihre Buhlereien, auch sie.',
        44: 'Und sie gingen zu ihr ein, wie man zu einem Weibe, einer Buhlerin eingeht. So gingen sie ein zu Oholah und Oholibah, den Weibern der Unzucht.',
        45: 'Und gerechte Männer, die werden sie richten nach dem Recht der Ehebrecherinnen, und nach dem Recht derer, so Blut vergießen; denn Ehebrecherinnen sind sie, und Blut ist an ihren Händen.',
        46: 'Denn also spricht der Herr Jehovah: Ich bringe eine Versammlung wider sie herauf und gebe sie dem Grausen und dem Raube hin.',
        47: 'Und die Versammlung - sie werden sie mit dem Steine steinigen, und mit ihren Schwertern sie niederhauen, ihre Söhne und ihre Töchter erwürgen, und mit Feuer ihre Häuser verbrennen.',
        48: 'Und so will Ich der Unzucht im Lande ein Ende machen, daß alle Weiber Zucht annehmen und nicht nach ihrer Unzucht tun.',
        49: 'Und eure Unzucht soll man auf euch legen und die Sünden ob euren Götzen sollt ihr tragen, und wissen, daß Ich der Herr Jehovah bin.',
    },
    24: {
        1: 'Und es geschah Jehovahs Wort zu mir im neunten Jahr, im zehnten Monat, am zehnten des Monats, und sprach:',
        2: 'Menschensohn, schreibe dir den Namen dieses Tages, diesen selben Tag an. An diesem selben Tag legt sich der König Babels an Jerusalem hin.',
        3: 'Und sprich dem Haus der Widerspenstigkeit ein Sprichwort und sprich zu ihnen: Also spricht der Herr Jehovah: Setze den Topf zu, setze zu und gieße auch Wasser darein.',
        4: 'Sammle die Stücke darein, jeglich gut Stück, Hüfte und Schulter, mit der Auswahl der Knochen fülle ihn.',
        5: 'Die Auswahl vom Kleinvieh nimm und auch Feuerung von Knochen darunter. Siede seinen Sud. Laß auch seine Knochen in dessen Mitte kochen.',
        6: 'Darum spricht also der Herr Jehovah: Wehe der Stadt des Blutes. Ein Topf ist sie, in der dessen Schaum ist, und sein Schaum geht nicht davon heraus. Nimm Stück für Stück heraus. Laß nicht das Los darüber fallen!',
        7: 'Denn ihr Blut ist in ihrer Mitte. Auf die dürre Felsenklippe hat sie es gelegt, nicht auf die Erde es geschüttet, um mit Staub es zuzudecken.',
        8: 'Um Grimm aufsteigen zu lassen, Rache zu rächen, ließ Ich ihr Blut auf die dürre Felsenklippe tun, daß es nicht werde zugedeckt.',
        9: 'Darum spricht also der Herr Jehovah: Wehe der Stadt des Blutes, Ich will auch die Feuerstätte groß machen.',
        10: 'Mache viel der Holzstücke, schüre das Feuer an, mache gar das Fleisch und würze die Würze, und laß die Knochen erglühen!',
        11: 'Und laß ihn leer auf seinen Kohlen stehen, auf daß er heiß werde und sein Erz erglühe, und in seiner Mitte seine Unreinheit schmelze, und sein Schaum ganz aus sei.',
        12: 'Sie ermüdet mit Beschwerden, und sein vieler Schaum will nicht hinausgehen. In das Feuer mit seinem Schaum!',
        13: 'In deiner Unreinheit ist Unzucht. Weil Ich dich wollte reinigen, und du nicht wolltest rein werden von deiner Unreinheit, sollst du nicht mehr rein werden, bis Mein Grimm wider dich ausruht.',
        14: 'Ich, Jehovah, habe es geredet. Es kommt, und Ich tue es, und lasse nicht los, und schone nicht und lasse Mich es nicht gereuen. Nach deinen Wegen und nach deinen Handlungen richten sie dich; spricht der Herr Jehovah.',
        15: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        16: 'Menschensohn, siehe, Ich nehme von dir deiner Augen Begehr durch eine Seuche, und du sollst nicht klagen und nicht weinen, und soll dir keine Träne kommen.',
        17: 'Jammere stille, über die Toten mache keine Trauer, binde deinen Kopfbund um auf dir, und lege deine Schuhe an deine Füße, und umhülle nicht den Bart und iß kein Brot der Männer!',
        18: 'Und ich redete am Morgen zu dem Volk, und am Abend starb mein Weib, und am Morgen tat ich, wie mir geboten ward.',
        19: 'Und das Volk sprach zu mir: Willst du uns nicht ansagen, was uns das ist, was du tust?',
        20: 'Und ich sprach zu ihnen: Jehovahs Wort geschah zu mir und sprach:',
        21: 'Sprich zu dem Hause Israel: So spricht der Herr Jehovah: Siehe, Ich lasse Mein Heiligtum entweihen, eurer Stärke Stolz und eurer Augen Begehr, und was eure Seele bemitleidet; und eure Söhne und eure Töchter, die ihr hinterlassen, sollen durch das Schwert fallen.',
        22: 'Und ihr sollt tun, wie ich getan, sollt nicht umhüllen euren Bart, und sollt das Brot der Männer nicht essen;',
        23: 'Und euer Kopfbund sei auf euren Häuptern, und eure Schuhe an euren Füßen, ihr sollt nicht klagen und nicht weinen und sollt dahinschwinden ob euren Missetaten, und sollt grollen jeder Mann seinem Bruder;',
        24: 'Und soll Jecheskel euch zum Wahrzeichen sein; nach allem, was er tat, sollt ihr tun, wenn es kommt, daß ihr erkennt, daß Ich der Herr Jehovah bin.',
        25: 'Und du, Menschensohn, wird nicht am Tage, da Ich von ihnen nehme ihre Stärke, die Freude ihrer Zierde, ihrer Augen Begehr und das, wonach sie die Seele erheben, ihre Söhne und ihre Töchter,',
        26: 'An jenem Tage wird ein Entkommener zu dir kommen, um es deine Ohren hören zu lassen.',
        27: 'An jenem Tage wird dein Mund sich öffnen mit dem Entkommenen, und du wirst reden und nicht mehr stumm sein, und wirst ihnen zum Wahrzeichen sein, daß sie wissen, daß Ich Jehovah bin.',
    },
    25: {
        1: 'Und es geschah Jehovahs Wort zu mir, sprechend:',
        2: 'Menschensohn, richte dein Angesicht wider die Söhne Ammons und weissage wider sie,',
        3: 'Und sprich zu den Söhnen Ammons: Höret das Wort des Herrn Jehovah! So spricht der Herr Jehovah: Weil du Ha! gesagt über Mein Heiligtum, als es entweiht wurde, und über den Boden Israels, als er verwüstet ward, und über das Haus Jehudah, als es in die Verbannung ging;',
        4: 'Darum, siehe, gebe Ich dich den Söhnen des Ostens zum Erbbesitz, daß ihre Gehöfte sie bei dir bewohnen, und ihre Wohnungen bei dir machen. Sie werden essen deine Frucht und sie werden trinken deine Milch.',
        5: 'Und Rabbah gebe Ich zum Wohnort für die Kamele, und die Söhne Ammons zum Lagerplatz des Kleinviehs, und wissen sollt ihr, daß Ich Jehovah bin.',
        6: 'Denn also spricht der Herr Jehovah: Weil du in die Hand geklatscht und mit dem Fuße gestampft und mit aller Verhöhnung in der Seele über den Boden Israels fröhlich warst;',
        7: 'Darum, siehe, recke Ich Meine Hand aus über dich, und gebe dich zum Raub den Völkerschaften und rotte dich von den Völkern aus und zerstöre dich aus den Ländern und vernichte dich, daß du wissest, daß Ich Jehovah bin.',
        8: 'So spricht der Herr Jehovah: Weil Moab und Seir sprachen: Siehe, wie alle Völkerschaften ist das Haus Jehudah!',
        9: 'Darum, siehe, öffne Ich die Seite Moabs von den Städten her, von seinen Städten her von seinem Ende, die Zierde des Landes, Beth Jeschimoth, Baal Meon und Kirjathajim zu,',
        10: 'Den Söhnen des Ostens, bei den Söhnen Ammons, und gebe sie zum Erbbesitz, damit man der Söhne Ammons nicht mehr gedenken soll unter den Völkerschafen.',
        11: 'Und über Moab übe Ich Gerichte, daß sie wissen, daß Ich Jehovah bin.',
        12: 'So spricht der Herr Jehovah: Weil Edom es tat und mit Rache sich rächte am Hause Jehudah, und mit Schuld sich verschuldete und sich an ihnen rächte;',
        13: 'Darum, spricht also der Herr Jehovah, will Meine Hand Ich ausstrecken über Edom und von ihm ausrotten Mensch und Vieh, und es zur Öde machen, von Theman an, und bis nach Dedan; sie sollen fallen durch das Schwert;',
        14: 'Und Meine Rache will Ich üben an Edom durch die Hand Meines Volkes Israel, so daß sie tun an Edom nach Meinem Zorn und nach Meinem Grimm. Und sie sollen erkennen Meine Rache, spricht der Herr Jehovah.',
        15: 'So spricht der Herr Jehovah: Dafür, daß die Philister mit Rache handelten und sich mit Rache rächten mit Verhöhnung in der Seele, sie zu verderben aus ewiger Feindschaft,',
        16: 'Darum, so spricht der Herr Jehovah: Siehe, Ich strecke Meine Hand aus über die Philister und rotte aus die Kerether und zerstöre den Überrest am Gestade des Meeres.',
        17: 'Und Ich will große Rache üben wider sie im Grimme, daß sie wissen, daß Ich Jehovah bin, wenn Meine Rache Ich an ihnen übe.',
    },
    26: {
        1: 'Und es geschah im elften Jahr am ersten des Monats, da geschah Jehovahs Wort an mich, und sprach:',
        2: 'Menschensohn! Weil Zor sprach über Jerusalem: Ha! zerbrochen ist die Tür der Völker. Nun wendet man sich herum zu mir. Ich werde voll, sie ist verödet.',
        3: 'Darum, so spricht der Herr Jehovah, siehe, Ich bin wider dich, Zor, und bringe viele Völkerschaften wider dich herauf, wie das Meer heraufbringt seine Wogen,',
        4: 'Daß sie verderben Zors Mauern und seine Türme niederreißen, und seinen Staub fege Ich von ihm weg, daß Ich es zur dürren Felsenklippe mache.',
        5: 'Ein Platz zum Ausspreiten des Garnes soll es inmitten des Meeres sein; denn Ich habe es geredet, spricht der Herr Jehovah; und zum Raub soll es den Völkerschaften werden;',
        6: 'Und seine Töchter auf dem Felde werden durch das Schwert erwürgt, und sie sollen wissen, daß Ich Jehovah bin.',
        7: 'Denn also spricht der Herr Jehovah: Siehe, Ich bringe wider Zor Nebuchadrezzar, den König Babels, von Norden her, den König der Könige mit Roß und mit Streitwagen und mit Reitern und einer Versammlung und viel Volkes.',
        8: 'Deine Töchter wird er auf dem Felde mit dem Schwerte erwürgen, und mit Bollwerken dich umgeben, und einen Wall aufschütten wider dich, und Schilddächer aufrichten gegen dich,',
        9: 'Und seines Brechers Stoß auf deine Mauern richten und deine Türme mit seinen Schwertern niederreißen.',
        10: 'Die Unzahl seiner Rosse wird dich mit ihrem Staub bedecken. Von der Stimme der Reiter und Räder und Streitwagen werden deine Mauern beben, sein Einzug in deinen Toren wird sein gleich den Einzügen in eine erstürmte Stadt.',
        11: 'Mit seiner Rosse Hufen zerstampft er alle deine Gassen, erwürgt dein Volk mit dem Schwerte und deiner Stärke Denksäulen wird er zur Erde stürzen.',
        12: 'Sie werden dein Vermögen erbeuten, und deine Waren rauben, und umreißen deine Mauern und niederreißen deine Häuser der Begehr, und deine Steine und dein Holz und deinen Staub mitten in das Wasser werfen.',
        13: 'Und deiner Lieder Tosen lasse Ich zu Ende kommen, und deiner Harfen Stimme wird nicht mehr gehört.',
        14: 'Und Ich mache dich zur dürren Felsenklippe; zur Ausspreitung von Garben sollst du werden, sollst nicht mehr aufgebaut werden; denn Ich, Jehovah, habe geredet, spricht der Herr Jehovah.',
        15: 'So spricht der Herr Jehovah zu Zor: Beben nicht die Inseln vor dem Getöse deines Falles, vom Jammern der Durchstochenen, vom Würgen der in dir Erwürgten?',
        16: 'Und alle Fürsten des Meeres steigen herab von ihren Thronen, und tun ihre Oberkleider weg, und ziehen ihre gewirkten Kleider aus, ziehen an das Erzittern, sitzen auf der Erde, und erzittern jeden Augenblick und erstaunen über dir.',
        17: 'Und erheben ein Klagelied über dich und sprechen zu dir: Wie bist du zerstört, die du in den Meeren wohntest; die gelobte Stadt, die stark war im Meere, sie und ihre Bewohner, die bei allen, so daran wohnten, Schrecken verbreitete.',
        18: 'Nun erzittern die Inseln am Tage deines Falls, und bestürzt sind die Eilande im Meer ob deinem Ausgange.',
        19: 'Denn also spricht der Herr Jehovah: Wenn Ich dich habe gemacht zu einer verödeten Stadt, wie die Städte, die nicht bewohnt werden, wenn Ich den Abgrund über dich heraufgebracht, und dich die vielen Wasser bedeckt haben;',
        20: 'Und Ich hinab dich fahren lasse mit denen, die in die Grube hinabfahren zu der Urzeit Volk, und dich im Land der Unteren habe wohnen lassen, in den ewigen Öden mit denen, die in die Grube hinabfahren, so daß du nicht bewohnt wirst. Und Ich gebe eine Zierde im Lande der Lebendigen;',
        21: 'Aber zur Schrecknis will Ich dich machen, daß du nicht mehr seiest. Daß man dich sucht und du nicht mehr gefunden werdest ewiglich, spricht der Herr Jehovah.',
    },
    27: {
        1: 'Und es geschah zu mir Jehovahs Wort, sprechend:',
        2: 'Du aber, Menschensohn, erhebe ein Klagelied über Zor.',
        3: 'Und sprich zu Zor: Du, die du wohnst an den Zugängen des Meeres, Händlerin der Völker nach den vielen Inseln, also spricht der Herr Jehovah: Zor, du sprichst: Ich bin die Vollendung der Schönheit.',
        4: 'Im Herzen der Meere sind deine Grenzen; deine Bauleute haben vollendet deine Schönheit.',
        5: 'Aus Senirs Tannen bauten sie dir all dein Tafelwerk. Die Zeder nahmen sie vom Libanon, Masten auf dir zu machen.',
        6: 'Aus Eichen von Baschan machten sie deine Ruder; aus Elfenbein machten sie die Ruderbank, die Tochter des Schreitens aus den Inseln Chittims.',
        7: 'Byssus, buntgewirkt aus Ägypten, war dein Segel, dir ein Panier zu sein, blau und roter Purpur aus Elischahs Inseln war deine Zeltdecke.',
        8: 'Die, so in Zidon und in Arvad wohnen, sie waren deine Ruderer; deine Weisen, o Tyrus, waren in dir, sie waren deine Steuerleute.',
        9: 'Gebals Älteste und seine Weisen waren in dir, zu bessern deinen Leck. Alle Schiffe des Meeres und ihre Seeleute waren in dir, daß sie verkehrten in deinem Verkehr.',
        10: 'Paras und Lud und Put waren in deiner Streitmacht, Männer deines Streites, sie hingen auf in dir Tartsche und Helm, sie gaben dir deine Ehre.',
        11: 'Die Söhne Arvads und deine eigene Streitmacht waren auf deinen Mauern ringsumher, und die Gamader waren in deinen Türmen. Sie hängten ihre Schilde ringsum an deinen Mauern auf, sie vollendeten deine Schönheit.',
        12: 'Tharschisch handelte mit dir mit aller Güter Menge, und gaben in deinen Markt Silber, Eisen, Zinn und Blei.',
        13: 'Javan, Thubal und Meschech waren deine Kaufleute und gaben Menschenseelen und eherne Gefäße in deinen Verkehr.',
        14: 'Von Beththogarmah gaben sie Rosse und Reiter und Maultiere in deinen Markt.',
        15: 'Die Söhne Dedans waren deine Kaufleute; in viele Inseln ging der Handel deiner Hand: Hörner, Elfenbein und Ebenholz gaben sie dir zurück als deine Gegengabe.',
        16: 'Aram handelte mit dir um die Menge deiner Werke; Chrysopras, Purpur und buntgewirkten Zeug und Byssus und Korallen und Karfunkeln gaben sie in deine Märkte.',
        17: 'Jehudah und das Land Israel waren deine Kaufleute, Weizen von Minnith, und Pannag und Honig und Öl und Balsam geben sie in deinen Verkehr.',
        18: 'Damaskus handelte mit dir in der Menge deiner Werke um eine Menge aller Güter, um Wein von Chelbon und um Wolle von Zachar.',
        19: 'Und Dan und Javan von Usal gaben auf deinen Markt verarbeitet Eisen, Kassia und Kalmus war in deinem Verkehr.',
        20: 'Dedan war dein Kaufmann mit Decken zum Ausbreiten für den Wagen.',
        21: 'Arabien und alle Fürsten Kedars waren Händler dir zur Hand in Lämmern und Widdern und Böcken; in diesen waren sie deine Händler.',
        22: 'Die von Scheba und Raamah, sie waren deine Kaufleute mit den Erstlingen alles Gewürzes, und mit allen kostbaren Steinen, und Gold gaben sie dir für deinen Markt.',
        23: 'Charan und Channeh und Eden, die Kaufleute Schebas; Aschur und Chilmad waren deine Kaufleute.',
        24: 'Sie waren deine Kaufleute in dem Vollkommensten in Ballen von purpurblauen und gestickten Zeugen und in Schätzen von Prachtgewändern, mit Stricken umbunden; und Zedernholz war in deinem Handel.',
        25: 'Die Tharschischschiffe waren deine Karawanen für deinen Verkehr, und du wurdest angefüllt und sehr verherrlicht im Herzen der Meere.',
        26: 'In viele Wasser brachten deine Ruderer dich: der Wind vom Osten hat dich im Herzen der Meere zerbrochen;',
        27: 'Dein Gut und dein Markt, dein Verkehr, deine Seeleute und deine Steuerleute, die, so deine Lecke bessern, die so in deinem Verkehr verkehren, und alle Männer deines Streites, die in dir sind, und in all deiner Versammlung, die in deiner Mitte ist, sie werden fallen in der Meere Herz am Tage deines Falles.',
        28: 'Ob der Stimme des Geschreis deiner Steuerleute beben die Vorstädte.',
        29: 'Und alle, die das Ruder fassen, steigen herab aus ihren Schiffen, die Seeleute, alle die Steuerleute des Meeres stehen auf dem Land;',
        30: 'Und lassen ihre Stimme hören über dich und schreien bitterlich, und bringen Staub herauf auf ihre Häupter; sie wälzen sich umher in der Asche.',
        31: 'Und scheren sich kahl über dir und gürten sich mit Säcken, und weinen über dich in Bitterkeit der Seele bittere Klage;',
        32: 'Und werden über dich ihr Trauerlied erheben, ein Klagelied, und über dich ein Klagelied anstimmen: Wer war wie Zor, verstört inmitten des Meeres!',
        33: 'Als dein Handel hervorging aus den Meeren, sättigtest du viele Völker; mit der Menge deiner Güter und deines Verkehrs bereichertest du die Könige der Erde.',
        34: 'Nun du zerbrochen bist von den Meeren in der Wasser Tiefen, fällt dahin dein Verkehr und all deine Versammlung in deiner Mitte.',
        35: 'Alle, so auf den Inseln wohnen erstaunen über dir, und ihre Könige schaudern mit Schauder, ihre Gesichter sind verstört.',
        36: 'Die Händler unter den Völkern zischen über dich, daß du bist zur Bestürzung geworden, und bist nichts in Ewigkeit.',
    },
    28: {
        1: 'Und es geschah Jehovahs Wort zu mir, sprechend:',
        2: 'Menschensohn, sprich zum Führer Zors: So spricht der Herr Jehovah: Weil dein Herz hoffärtig ist geworden, und du sprichst: Ein Gott bin ich, auf dem Sitze Gottes sitze ich, im Herzen der Meere. Und du bist ein Mensch und kein Gott, und hast dein Herz wie Gottes Herz gemacht.',
        3: 'Siehe, weise bist du, mehr denn Daniel, und kein Geheimnis ist vor dir verdeckt.',
        4: 'Durch deine Weisheit und deine Einsicht hast du Vermögen dir gemacht, und hast Gold und Silber in deine Schatzkammern geschafft.',
        5: 'Durch deine viele Weisheit hast du in deinem Handel dein Vermögen gemehrt, und durch dein Vermögen ist hoch dein Herz geworden.',
        6: 'Darum spricht so der Herr Jehovah: Weil du dein Herz wie Gottes Herz gemacht;',
        7: 'Darum, siehe, bringe Ich Fremde über dich, die Trotzigen der Völkerschaften. Die sollen ihre Schwerter ziehen wider die Schöne deiner Weisheit und deinen Strahlenglanz entweihen.',
        8: 'Zur Grube bringen sie dich hinab, so daß du stirbst den Tod der Erschlagenen im Herzen der Meere.',
        9: 'Wirst du Angesichts deiner Würger sprechen: Ich bin Gott, da du doch Mensch bist und kein Gott in der Hand derer, die dich erschlagen?',
        10: 'Den Tod der Unbeschnittenen wirst du sterben von der Hand der Fremden; denn Ich habe es geredet, spricht der Herr Jehovah.',
        11: 'Und es geschah Jehovahs Wort zu mir, sprechend:',
        12: 'Du, Menschensohn, erhebe ein Klagelied über den König Zors und sprich zu ihm: So spricht der Herr Jehovah: Besiegelnd das Ebenmaß, voller Weisheit warst du und vollkommen von Schönheit,',
        13: 'In Eden, dem Garten Gottes, warst du, jeglicher kostbare Stein war deine Bedeckung, Rubin, Topas, Diamant, Tharschisch, Schoham und Jaspis, Saphir, Chrysopras und Smaragd und Gold, das Werk deiner Pauken und deiner Pfeifen war in dir; am Tage, da du geschaffen wardst, wurden sie bereitet.',
        14: 'Du warst ein Cherub, die Ausdehnung des Deckenden, und Ich setzte dich, du warst auf dem Berg der Heiligkeit Gottes, inmitten der Steine des Feuers bist du gewandelt.',
        15: 'Untadelig warst du in deinen Wegen vom Tage an, da du geschaffen wardst, bis Verkehrtheit in dir gefunden ward.',
        16: 'Durch deinen vielen Handel ist deine Mitte voll von Gewalttat geworden, und du sündigtest, und Ich entweihe dich, weg vom Berge Gottes, und zerstöre dich, deckender Cherub, aus der Mitte der Steine des Feuers.',
        17: 'Ob deiner Schönheit ward dein Herz hoffärtig, hast verdorben deine Weisheit ob deinem Strahlenglanz. Zur Erde werfe Ich dich herab, gebe dich hin vor den Königen, daß sie auf dich sehen.',
        18: 'Ob deiner vielen Missetaten, ob der Verkehrtheit deines Handels hast du entweiht deine Heiligtümer. Und Ich lasse Feuer aus deiner Mitte ausgehen, daß es dich auffresse, und mache dich zur Asche auf der Erde vor den Augen aller, die dich sehen.',
        19: 'Alle, die dich kennen unter den Völkern, erstaunen ob dir; zu Schrecknissen bist du geworden und bist nicht mehr in Ewigkeit.',
        20: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        21: 'Menschensohn, richte dein Angesicht wider Zidon und weissage wider dasselbe,',
        22: 'Und sprich: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Zidon, und will Mich in deiner Mitte verherrlichen, auf daß sie wissen, daß Ich Jehovah bin, wenn Ich Gerichte in ihm tue, und in ihm geheiligt werde.',
        23: 'Und Ich sende Pest darein, und Blut in seine Gassen, daß in seiner Mitte falle der Erschlagene durch das Schwert, das wider dasselbe ist von ringsumher, damit sie wissen, daß Ich Jehovah bin.',
        24: 'Und soll nicht mehr für das Haus Israel ein stechender Stachel sein und ein schmerzender Dorn von allen ihren Umgebungen, die sie verhöhnen, und sie sollen wissen, daß Ich der Herr Jehovah bin.',
        25: 'So spricht der Herr Jehovah: Wenn Ich das Haus Israel zusammenbringe aus den Völkern, unter die sie zerstreut worden, und Mich heilige in ihnen vor den Augen der Völkerschaften, dann sollen sie auf ihrem Boden wohnen, den Ich Meinem Knecht, dem Jakob, gegeben hatte.',
        26: 'Und sie sollen sicher darauf wohnen und Häuser bauen und Weinberge pflanzen, und sicher sollen sie wohnen, wenn Ich Gerichte halte über alle die, so sie verhöhnen ringsumher, und sie sollen wissen, daß Ich, Jehovah, bin ihr Gott.',
    },
    29: {
        1: 'Im zehnten Jahr, im zehnten, am zwölften des Monats, geschah an mich das Wort Jehovahs, sprechend:',
        2: 'Menschensohn, richte dein Angesicht wider Pharao, Ägyptens König, und weissage wider ihn und wider ganz Ägypten.',
        3: 'Rede und sprich: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Pharao, Ägyptens König, du großes Ungetüm, das inmitten seiner Ströme sich lagert, das spricht: Mein Strom ist es, und ich habe mich gemacht,',
        4: 'Und Ich lege Haken in deine Kinnbacken und lasse die Fische deiner Ströme an deinen Schuppen haften und ziehe dich herauf aus deiner Ströme Mitte, und alle Fische deiner Ströme, die an deinen Schuppen haften,',
        5: 'Und gebe dich dahin in die Wüste, dich und alle Fische deiner Ströme; auf des Feldes Oberfläche sollst du fallen, nicht gesammelt noch zusammengebracht werden, dem wilden Tiere des Landes und dem Gevögel der Himmel gebe Ich dich zur Speise.',
        6: 'Und alle, die in Ägypten wohnen, sollen wissen, daß Ich Jehovah bin, weil sie eine Stütze von Rohr waren dem Hause Israel.',
        7: 'Wenn sie dich faßten mit der Hand, ward er zerquetscht und durchstachst ihnen die ganze Schulter; und wenn sie sich auf dich stützten, brachst du und machtest alle die Lenden stehen.',
        8: 'Darum spricht der Herr Jehovah also: Siehe, Ich bringe über dich das Schwert, und Ich rotte aus von dir Mensch und Vieh.',
        9: 'Und das Land Ägypten wird zur Verwüstung und Öde werden, auf daß sie wissen, daß Ich Jehovah bin, weil es sprach: Mein ist der Strom, und Ich habe ihn gemacht.',
        10: 'Darum, siehe, bin Ich wider dich und wider deine Ströme, und will das Land Ägypten zur Öde der Verwüstung machen von dem Turme von Seveneh und bis zur Grenze Kusch.',
        11: 'Nicht durch dasselbe soll hingehen eines Menschen Fuß und nicht dadurch hingehen des Viehes Fuß, und nicht soll man darin wohnen vierzig Jahre.',
        12: 'Und Ich mache das Land Ägypten zur Verwüstung mitten unter verwüsteten Ländern, und seine Städte sollen vierzig Jahre eine Verwüstung mitten unter verödeten Städten sein, und Ich will die Ägypter unter die Völkerschaften zerstreuen und sie versprengen in die Länder.',
        13: 'Denn also spricht der Herr Jehovah: Vom Ende von vierzig Jahren will Ich Ägypten zusammenbringen aus den Völkern, dahin sie zerstreut worden;',
        14: 'Und Ich will die Gefangenschaft Ägyptens zurückbringen und sie zurückbringen in das Land Pathros, in das Land ihres Handels, und sie sollen ein niedriges Königreich sein.',
        15: 'Es soll niedriger sein denn die Königreiche und sich nicht mehr erheben über die Völkerschaften; und Ich werde ihrer wenig machen, daß sie nicht mehr beherrschen die Völkerschaften;',
        16: 'Und es soll dem Hause Israel nicht mehr zum Vertrauen sein, erinnernd an die Missetat, daß sie sich nach ihnen wandten. Und wissen sollen sie, daß Ich der Herr Jehovah bin.',
        17: 'Und es geschah im siebenundzwanzigsten Jahr, im ersten am ersten des Monats, daß Jehovahs Wort an mich geschah, sprechend:',
        18: 'Menschensohn, Nebuchadrezzar, Babels König, läßt seine Streitmacht wider Zor einen großen Dienst dienen, ein jeglich Haupt ward kahl gemacht, und jegliche Schulter abgerieben, und ihm und seiner Streitmacht wird kein Lohn von Zor für den Dienst, den wider dasselbe er gedient hatte.',
        19: 'Darum spricht so der Herr Jehovah: Siehe, Ich gebe Nebuchadrezzar, Babels König, das Land Ägypten, daß seine Volks- menge er wegnehme und erbeute dessen Beute und raube dessen Raub, und es der Lohn sei seiner Heeresmacht,',
        20: 'Für seine Arbeit, mit der er gedient, gebe Ich ihm das Land Ägypten, weil sie es für Mich getan, spricht der Herr Jehovah.',
        21: 'An jenem Tage lasse Ich sprossen ein Horn dem Hause Israel, und gebe dir das Öffnen des Mundes inmitten ihrer, und sie sollen wissen, daß Ich Jehovah bin.',
    },
    30: {
        1: 'Und es geschah Jehovahs Wort zu mir, sprechend:',
        2: 'Menschensohn, weissage und sprich: So spricht der Herr Jehovah: Heulet, wehe dem Tag!',
        3: 'Denn nahe ist der Tag, und nahe ist der Tag Jehovahs, ein Tag der Wolke, eine Zeit der Völkerschaften wird es sein.',
        4: 'Und kommen wird das Schwert nach Ägypten, und in Kusch wird Pein sein, wenn der Erschlagene in Ägypten fällt, und seine Volksmenge sie fortnehmen und seine Grundfesten umreißen werden.',
        5: 'Kusch und Put und Lud, und ganz Ereb und Chub und die Söhne des Landes des Bundes, mit ihnen fallen sie durch das Schwert.',
        6: 'So spricht Jehovah: Und es werden fallen, die für Ägypten ein Anhalt waren, und seiner Stärke Stolz wird hinabsinken. Vom Turme von Seveneh werden sie darin fallen durch das Schwert, spricht der Herr Jehovah.',
        7: 'Und sie werden verwüstet sein inmitten der verwüsteten Länder, und ihre Städte werden inmitten der verödeten Städte sein.',
        8: 'Und sie werden wissen, daß Ich Jehovah bin, wenn Feuer Ich gebe in Ägypten, und alle, die ihm beistanden, zerbrochen werden.',
        9: 'An jenem Tage werden Boten von Meinem Angesicht ausgehen auf Fahrzeugen, Kusch, das sichere, aufzuscheuchen, und Pein wird unter ihnen sein, wie an dem Tag Ägyptens, denn siehe, es kommt.',
        10: 'So spricht der Herr Jehovah: Und ein Ende mache Ich mit der Volksmenge Ägyptens durch die Hand Nebuchadrezzars, des Königs von Babel.',
        11: 'Er und sein Volk mit ihm, die Trotzigen der Völkerschaften, werden hereingebracht, das Land zu verderben, und ziehen ihre Schwerter gegen die Ägypter und füllen mit Erschlagenen das Land.',
        12: 'Und Ich lasse die Ströme vertrocknen, und das Land verkaufe Ich in die Hand der Bösen und verwüste das Land und seine Fülle durch die Hand der Fremden. Ich, Jehovah, habe geredet.',
        13: 'So spricht der Herr Jehovah: Und Ich zerstöre die Götzen und mache ein Ende mit den Abgöttern aus Noph, und ein Fürst wird nicht mehr sein vom Lande Ägypten, und Ich gebe Furcht im Lande Ägypten.',
        14: 'Und will Pathros verwüsten und Feuer in Zoan geben und über No Gerichte halten,',
        15: 'Und Meinen Grimm ausschütten über Sin, Ägyptens Stärke, und ausrotten die Volksmenge No,',
        16: 'Und Feuer gebe Ich in Ägypten, krei-ßend soll Sin kreißen, und No zum Durchbruch kommen, und Noph am Tage bedrängt werden.',
        17: 'Avens und Pibeseths Jünglinge fallen durch das Schwert, und siehe! sie gehen in Gefangenschaft.',
        18: 'Und in Techaphneches verfinstert sich der Tag, wenn Ich dort breche die Jochhölzer Ägyptens und seiner Stärke Stolz zu Ende kommt; eine Wolke bedeckt dasselbe, und seine Töchter gehen in Gefangenschaft.',
        19: 'Und Ich halte Gerichte in Ägypten, und sie werden wissen, daß Ich Jehovah bin.',
        20: 'Und es geschah im elften Jahr am siebenten des ersten Monats, daß Jehovahs Wort an mich geschah, sprechend:',
        21: 'Menschensohn, den Arm Pharaos, des Königs von Ägypten, werde Ich zerbrechen, und siehe, er wird nicht verbunden ihm Heilung zu geben, man legt keinen Verband auf, daß er verbunden werde und erstarke, um das Schwert zu erfassen.',
        22: 'Darum, so spricht der Herr Jehovah, siehe, Ich bin wider Pharao, Ägyptens König, daß Ich seine Arme zerbreche, den starken und den gebrochenen, und lasse ihm das Schwert aus seiner Hand fallen.',
        23: 'Und will die Ägypter unter die Völkerschaften zerstreuen und sie zersprengen in die Länder,',
        24: 'Und Ich will stärken die Arme des Königs von Babel und geben Mein Schwert in seine Hand, und zerbrechen die Arme Pharaos, daß er stöhne vor ihm das Stöhnen des Durchbohrten.',
        25: 'Und Ich will stärken die Arme des Königs von Babel, und die Arme Pharaos sollen sinken, daß sie wissen, daß Ich Jehovah bin, wenn Ich Mein Schwert dem König von Babel in seine Hand gebe, daß er es über Ägyptenland ausstrecke,',
        26: 'Und Ich zerstreue die Ägypter unter die Völkerschaften und zersprenge sie in die Länder, auf daß sie wissen, daß Ich Jehovah bin.',
    },
    31: {
        1: 'Und es geschah im elften Jahr am ersten des dritten Monats, daß das Wort Jehovahs an mich geschah, sprechend:',
        2: 'Menschensohn, sprich zu Pharao, dem Könige Ägyptens, und zu seiner Volksmenge: Wem gleichst du in deiner Größe?',
        3: 'Siehe, Aschur war eine Zeder auf dem Libanon, schön von Ästen und schattigem Laubwerk und hoch von Wuchs, und zwischen dichten Zweigen war sein Wipfel.',
        4: 'Wasser machten sie groß, der Abgrund ließ sie sich emporheben, daß er mit seinen Flüssen rings um ihre Pflanzung ging und ihre Kanäle zu allen Bäumen des Feldes sandte.',
        5: 'Darum ward hoch ihr Wuchs vor allen Bäumen des Feldes und ihres Gezweiges wurde viel und ihre Zweige lang von den vielen Wassern, als sie sie aussandte.',
        6: 'Auf ihrem Gezweige nistete alles Gevögel des Himmels, und unter ihren Zweigen gebar alles wilde Tier des Feldes, und unter ihrem Schatten saßen all die vielen Völkerschaften.',
        7: 'Und sie war schön in ihrer Größe, mit ihren langen Schossen; denn ihre Wurzel war an vielen Wassern.',
        8: 'Die Zedern mochten sie nicht verdecken im Garten Gottes, die Tannen waren ihr nicht zu gleichen mit ihrem Gezweige, und Platanen waren nicht wie ihre Zweige. Kein Baum im Garten Gottes war ihr an Schönheit gleich.',
        9: 'Schön hatte Ich sie gemacht in ihrer Schosse Menge, und alle Bäume Edens im Garten Gottes beneideten dieselbe.',
        10: 'Darum, so spricht der Herr Jehovah: Weil sie hoch war an Wuchs und ihr Wipfel zwischen den dichten Zweigen war, und ihr Herz ob ihrer Höhe sich emporhob,',
        11: 'So gebe Ich ihn in die Hand des Starken der Völkerschaften; er wird es an ihm tun, und ob seiner Ungerechtigkeit treibe Ich ihn fort.',
        12: 'Und Fremde rotten sie aus, die Gewaltigen der Völkerschaften, und lassen sie fahren. Auf die Berge und in alle Schluchten fallen ihre Schosse und ihre Zweige zerbrechen in allen Flußbetten des Landes; und alle Völker der Erde zogen herab aus ihrem Schatten und ließen sie fahren.',
        13: 'Auf seinem umgefallenen Stamme wohnt alles Gevögel der Himmel, und auf seinen Zweigen war alles wilde Tier des Feldes.',
        14: 'Auf daß nicht hoffärtig seien in ihrem Wuchse alle Bäume der Wasser, und ihren Wipfel nicht zwischen den dichten Gezweigen erheben, und nicht zu ihnen stehen wegen ihrer Höhe alle, die da Wasser trinken; denn sie alle werden dem Tode gegeben in die untere Erde inmitten der Menschensöhne, zu denen, die in die Grube hinabfahren.',
        15: 'So spricht der Herr Jehovah: Am Tage, da er in die Hölle hinunterfährt, lasse Ich trauern, lasse Ich sich bedecken über ihn den Abgrund, und halte ab seine Flüsse, daß den vielen Wassern gewehrt werde, und lasse sich verdunkeln über ihm den Libanon, und alle Bäume des Feldes um ihn schmachten.',
        16: 'Vor dem Getöse seines Falls lasse Ich die Völkerschaften erbeben, wenn Ich ihn in die Hölle fahren lasse mit denen, die zur Grube hinabfahren, und in der unteren Erde trösten sich alle Bäume Edens, das Auserwählte und das Beste des Libanon, alle, die Wasser trinken.',
        17: 'Auch sie fahren mit ihm hinab zur Hölle, zu den durch das Schwert Erschlagenen, die als sein Arm gesessen in seinem Schatten inmitten der Völkerschaften.',
        18: 'Wem gleichst du also an Herrlichkeit und Größe unter den Bäumen Edens, und hinabgestoßen wirst du mit den Bäumen Edens zur unteren Erde; inmitten der Unbeschnittenen liegst du mit den durch das Schwert Erschlagenen, das ist Pharao und alle seine Volksmenge, spricht der Herr Jehovah.',
    },
    32: {
        1: 'Und es geschah im zwölften Jahr, im zwölften Monat, am ersten des Monats, daß Jehovahs Wort an mich geschah. Er sprach:',
        2: 'Menschensohn, erhebe ein Klagelied über Pharao, Ägyptens König, und sprich zu ihm: Dem jungen Löwen der Völkerschaften glichest du und bist wie der Walfisch in den Meeren und brichst hervor mit deinen Flüssen und trübst mit deinen Füßen die Wasser und störst auf deine Flüsse.',
        3: 'So spricht der Herr Jehovah: Und Ich habe Mein Garn über dich ausgebreitet mit einer Versammlung vieler Völker, daß sie in Meinem Garn dich heraufziehen.',
        4: 'Ich werde dich auf das Land hinstoßen und auf die Angesichte des Feldes hinschleudern, und lasse alles Gevögel des Himmels auf dir hausen und das wilde Tier der ganzen Erde von dir sich sättigen.',
        5: 'Und will dein Fleisch geben auf die Berge, und mit deiner Höhe die Schluchten füllen.',
        6: 'Und tränken will Ich das Land mit deinem Ausfluß von deinem Blut bis an die Berge hin, und die Flußbette sollen voll von dir werden.',
        7: 'Und Ich bedecke, wenn Ich dich auslösche, die Himmel und verdunkle ihre Sterne; die Sonne bedecke Ich mit einer Wolke, und der Mond soll sein Licht nicht leuchten lassen.',
        8: 'Alle Leuchten des Lichtes am Himmel will Ich verdunkeln über dir und Finsternis bringen über dein Land, spricht der Herr Jehovah;',
        9: 'Und will reizen vieler Völker Herz, wenn Ich dein Zerbrechen hereinbringe unter die Völkerschaften, über Länder, die du nicht gekannt.',
        10: 'Und Ich mache, daß viele Völker über dir erstaunen und ihren Königen das Haar sich sträubt über dir, wenn Ich Mein Schwert vor ihrem Angesichte umherschwinge, daß jeder Mann in Augenblicken für seine Seele erzittert am Tage deines Falls.',
        11: 'Denn so spricht der Herr Jehovah: Das Schwert des Königs von Babel soll an dich kommen!',
        12: 'Mit den Schwertern der Helden bringe Ich deine Volksmenge zu Fall, die Gewaltigen der Völkerschaften allesamt, und sie sollen den Stolz Ägyptens verheeren und vernichten all seine Volksmenge.',
        13: 'Und Ich zerstöre all sein Vieh an vielen Wassern; und nicht mehr trüben soll sie eines Menschen Fuß und nicht sie trüben die Klaue des Viehs.',
        14: 'Dann lasse Ich ihre Wasser hinabsinken und ihre Flüsse dahinfließen wie Öl, spricht der Herr Jehovah:',
        15: 'Wenn Ich das Land Ägypten zur Verwüstung gemacht, und das Land von seiner Fülle verwüstet, wenn Ich geschlagen habe alle, so in ihm wohnen, und sie wissen, daß Ich Jehovah bin.',
        16: 'Ein Klagelied ist es, und ein Klagelied sollen anstimmen die Töchter der Völkerschaften, sie sollen es anstimmen; über Ägypten und über alle seine Volksmenge sollen sie solches anstimmen, spricht der Herr Jehovah.',
        17: 'Und es geschah im zwölften Jahr, am fünfzehnten Tag des Monats, daß das Wort Jehovahs an mich geschah. Er sprach:',
        18: 'Menschensohn, wehklage über die Volksmenge Ägyptens und laß sie hinabfahren, sie und die Töchter stattlicher Völkerschaften zur Erde der Unteren, mit denen, die in die Grube hinabfahren.',
        19: 'Wem gehst du vor an Lieblichkeit? Fahre hinab und lege dich zu den Unbeschnittenen.',
        20: 'Sie werden fallen mitten unter die durch das Schwert Erschlagenen. Das Schwert ist gegeben, sie ziehen sie hin mit all ihrer Volksmenge.',
        21: 'Es werden zu ihm reden die Starken der Mächtigen aus der Mitte der Hölle mit denen, die ihm beistanden. Sie sind hinabgefahren, sie liegen da, die Unbeschnittenen, die vom Schwert Erschlagenen.',
        22: 'Da ist Aschur und all seine Versammlung, rings um ihn her sind seine Gräber; sie alle sind erschlagen, die durch das Schwert Gefallenen.',
        23: 'Denn Gräber sind gegeben an den Seiten der Grube, und seine Versammlung ist rings um sein Grab, sie alle durchbohrt, gefallen durch das Schwert, die Entsetzen verbreiteten im Lande der Lebendigen.',
        24: 'Dort ist Elam und all seine Volksmenge rings um sein Grab, sie alle sind erschlagen, durch das Schwert gefallen, die unbeschnitten in das Land der unteren Orte sind hinabgefahren, sie, die Entsetzen verbreiteten im Lande der Lebendigen, und tragen ihre Schande bei denen, die in die Grube hinabgefahren.',
        25: 'Ein Lager gab man ihm mit seiner ganzen Volksmenge, inmitten der Erschlagenen; rings um ihn her sind seine Gräber. Sie alle sind unbeschnitten, erschlagen mit dem Schwert, die Entsetzen verbreiteten im Lande der Lebendigen. Und sie tragen ihre Schande bei denen, die in die Grube hinabfahren. Inmitten der Erschlagenen wurde er gelegt.',
        26: 'Da ist Meschech, Thubal und all seine Volksmenge, um ihn her sind seine Gräber. Sie alle sind Unbeschnittene, mit dem Schwert durchbohrt, weil sie ihr Entsetzen verbreiteten im Lande der Lebendigen.',
        27: 'Aber sie sollen nicht liegen mit den Mächtigen, die von den Unbeschnittenen gefallen sind, die in die Hölle hinabgefahren in ihrer Kriegsrüstung, und denen sie ihre Schwerter unter ihre Häupter gegeben; und ihre Missetaten waren auf ihren Gebeinen; denn ein Entsetzen waren die Mächtigen im Lande der Lebendigen.',
        28: 'Und du wirst inmitten der Unbeschnittenen zerbrochen werden, und liegen mit den durch das Schwert Erschlagenen.',
        29: 'Da ist Edom! Seine Könige und all seine Fürsten wurden in ihrem Heldentum zu den durch das Schwert Erschlagenen gelegt; sie sollen liegen bei den Unbeschnittenen und bei denen, die in die Grube hinabfahren.',
        30: 'Dort die Gebieter von Mitternacht allesamt und jeder Sidonier, die mit den Erschlagenen hinabgefahren sind, in ihrem Entsetzen wegen ihres Heldentums schämen sie sich; und die Unbeschnittenen liegen mit den Erschlagenen durch das Schwert, und tragen ihre Schande mit denen, die zur Grube hinabfahren.',
        31: 'Diese wird Pharao sehen und sich trösten über alle seine Volksmenge, die durch das Schwert Erschlagenen, Pharao und seine ganze Streitmacht, spricht der Herr Jehovah.',
        32: 'Denn Mein Entsetzen gebe Ich in dem Land der Lebendigen; er aber wird gelegt inmitten der Unbeschnittenen, bei den durch das Schwert Erschlagenen, Pharao und alle seine Volksmenge, spricht der Herr Jehovah.',
    },
    33: {
        1: 'Und es geschah zu mir das Wort Jehovahs, sprechend:',
        2: 'Menschensohn, rede zu den Söhnen deines Volkes und sprich zu ihnen: Wenn Ich das Schwert über ein Land bringe, und das Volk des Landes nimmt einen Mann von seinen Enden und bestellt sich ihn zum Wächter,',
        3: 'Und er sieht das Schwert kommen über das Land, und stößt in die Posaune und warnt das Volk;',
        4: 'Und so der Hörer hört den Schall der Posaune und läßt sich nicht warnen, und das Schwert kommt und nimmt ihn weg, dessen Blut sei auf seinem Haupt.',
        5: 'Er hat den Schall der Posaune gehört und sich nicht warnen lassen, sein Blut sei auf ihm. Wer sich aber warnen läßt, der rettet seine Seele.',
        6: 'Wenn aber der Wächter das Schwert sieht kommen und nicht in die Posaune stößt, und das Volk wird nicht gewarnt, und das Schwert kommt und nimmt von ihnen eine Seele weg, so wird dieser weggenommen in seiner Missetat; aber sein Blut werde Ich fordern von des Wächters Hand.',
        7: 'Und dich, Menschensohn, habe Ich zum Wächter über das Haus Israel gegeben, daß du aus Meinem Munde hörst das Wort und sie von Mir aus warnst.',
        8: 'Wenn Ich nun zu dem Ungerechten sage: Du, Ungerechter, sollst des Todes sterben -und du redest es nicht, daß du den Ungerechten warnst vor seinem Wege; so stirbt der Ungerechte in seiner Missetat, von deiner Hand aber fordere Ich sein Blut.',
        9: 'Hast du aber den Ungerechten vor seinem Wege gewarnt, daß er davon zurückkehre, und er kehrt nicht zurück von seinem Weg, so muß er sterben in seiner Missetat, du aber errettest deine Seele.',
        10: 'Und du, Menschensohn, sprich zu dem Hause Israel: Also sprechet ihr sagend: Ja, unsere Übertretungen und unsere Sünden sind auf uns, daß wir darin dahinschwinden; und wie sollen wir leben?',
        11: 'Sprich du zu ihnen: Bei Meinem Leben, spricht der Herr Jehovah: Ich habe keine Lust am Tode des Ungerechten, sondern daß der Ungerechte zurückkehre von seinem Weg und lebe. Kehrt zurück, kehrt zurück von euren bösen Wegen. Warum wollt ihr sterben, ihr Haus Israel?',
        12: 'Und du, Menschensohn, sprich zu den Söhnen deines Volkes: Des Gerechten Gerechtigkeit soll ihn nicht erretten am Tage seiner Übertretung, und die Ungerechtigkeit des Ungerechten bringt ihn nicht zum Fall am Tage, da er zurückkehrt von seiner Ungerechtigkeit. Und der Gerechte kann nicht leben dadurch am Tage, da er sündigt.',
        13: 'Wenn Ich zu dem Gerechten spreche: Er soll leben, und er vertraut auf seine Gerechtigkeit und tut Verkehrtes, so wird all seiner Gerechtigkeit nicht gedacht werden; und ob seiner Verkehrtheit, die er getan, darob stirbt er.',
        14: 'Und wenn Ich zum Ungerechten spreche: Du mußt des Todes sterben, und er kehrt zurück von seiner Sünde und tut Recht und Gerechtigkeit;',
        15: 'Wenn der Ungerechte das Pfand zurückgibt, das Entrissene erstattet, in den Satzungen des Lebens wandelt, so daß er nichts Verkehrtes tut; so soll er leben, er soll nicht sterben.',
        16: 'All seiner Sünden, die er hat gesündigt, soll ihm nicht gedacht werden, Recht und Gerechtigkeit tut er, er soll leben.',
        17: 'Und es sprechen die Söhne deines Volkes: Nicht richtig ist der Weg des Herrn; aber sie, ihr Weg ist nicht richtig.',
        18: 'Wenn der Gerechte zurückkehrt von seiner Gerechtigkeit und Verkehrtes tut, so stirbt er dadurch.',
        19: 'Und wo der Ungerechte zurückkehrt von seiner Ungerechtigkeit und Recht tut und Gerechtigkeit, so soll er deshalb leben.',
        20: 'Und ihr sprechet: der Weg des Herrn ist nicht richtig. Nach seinen Wegen richte Ich einen jeden Mann von euch, o Haus Israels.',
        21: 'Und es geschah im zwölften Jahr, am fünften des zehnten Monats unserer Wegführung, daß ein Entkommener aus Jerusalem zu mir kam und sprach: Geschlagen ist die Stadt!',
        22: 'Und die Hand Jehovahs war über mir am Abend ehe der Entkommene kam, und Er öffnete meinen Mund, bis er zu mir kam am Morgen, und mir ward geöffnet der Mund und ich war nicht mehr stumm.',
        23: 'Und es geschah an mich das Wort Jehovahs, sprechend:',
        24: 'Menschensohn, die auf jenen Öden wohnen auf Israels Boden, sie sprechen und sagen: Einer war Abraham und besaß das Land erblich. Und unser sind es viel. Uns ward das Land zum Erbbesitz gegeben.',
        25: 'Darum sprich du zu ihnen: So spricht der Herr Jehovah: Ihr habt mit dem Blut gegessen und eure Augen zu euren Götzen erhoben und Blut vergossen, und wollt das Land erblich besitzen?',
        26: 'Ihr standet auf euer Schwert, ihr tatet Greuel, und ein Mann verunreinigte seines Genossen Weib, und ihr wollt das Land erblich besitzen?',
        27: 'So sollst du zu ihnen sprechen: So spricht der Herr Jehovah: Bei Meinem Leben, die, so in den Öden sind, sollen durch das Schwert fallen. Und wer auf dem offenen Feld ist, den gebe Ich zum Fraß dem wilden Tier; und die in Festen und in Höhlen sind, sollen sterben durch die Pest.',
        28: 'Zur Verwüstung und Wüstenei mache Ich das Land und ein Ende hat seiner Stärke Stolz. Verwüstet sind die Berge Israels, daß niemand mehr darübergeht.',
        29: 'Und sie sollen erkennen, daß Ich Jehovah bin, wenn Ich das Land mache zur Verwüstung und Wüstenei ob allen ihren Greueln, die sie taten.',
        30: 'Und du, Menschensohn, die Söhne deines Volkes, die neben den Wänden und an den Eingängen der Häuser über dich reden und einer zum anderen redet, ein Mann zu seinem Bruder, und sagt: Kommt doch und hört, was für ein Wort ausgeht von Jehovah.',
        31: 'Und sie kommen zu dir, wie das Volk kommt, und setzen sich als Mein Volk vor dich und hören deine Worte und - tun sie nicht. Denn Wollüste sind in ihrem Munde, sie tun sie; ihr Herz geht ihrem Gewinn nach.',
        32: 'Und siehe, du bist ihnen, wie ein wollüstiges Lied, wie einer, der eine schöne Stimme hat und gut spielt. Und sie hören deine Worte an und tun nichts davon.',
        33: 'Und kommt es - siehe, es kommt - da sollen sie erkennen, daß ein Prophet in ihrer Mitte war.',
    },
    34: {
        1: 'Und es geschah an mich das Wort Jehovahs, sprechend:',
        2: 'Menschensohn, weissage wider die Hirten Israels, weissage und sprich zu ihnen, zu den Hirten: So spricht der Herr Jehovah: Wehe den Hirten Israels, die sich selber weiden. Sollten nicht die Hirten die Herde weiden?',
        3: 'Das Fett esset ihr, und in die Wolle kleidet ihr euch, das Gemästete schlachtet ihr, die Herde weidet ihr nicht.',
        4: 'Die Siechen stärkt ihr nicht und die Kranken heilt ihr nicht und die Gebrochenen verbindet ihr nicht, und die Verscheuchten bringt ihr nicht zurück, und die Verlorenen sucht ihr nicht, und mit Härte und mit Gewalt beherrscht ihr sie.',
        5: 'Und ohne Hirten wurden sie zerstreut und wurden zum Fraße allem wilden Tiere des Feldes und sind zerstreut.',
        6: 'Und Meine Herde, sie gehen fehl auf allen Bergen und auf allen emporragenden Hügeln; und über die ganze Erde ist Meine Herde zerstreut, und niemand ist, der nach ihr fragt, und niemand, der sie sucht.',
        7: 'Darum, ihr Hirten, hört Jehovahs Wort:',
        8: 'Bei Meinem Leben, spricht der Herr Jehovah, fürwahr, weil meine Herde zum Raube ward, und weil Meine Herde zum Fraß ward allem wilden Tiere des Feldes, weil sie keinen Hirten hat, und Meine Hirten nicht nach Meiner Herde fragen, und die Hirten sich selber weiden und Meine Herde nicht weiden;',
        9: 'Darum, ihr Hirten, hört das Wort Jehovahs:',
        10: 'So spricht der Herr Jehovah: Siehe, Ich bin wider die Hirten und fordere Meine Herde von ihrer Hand und mache ein Ende ihrem Weiden der Herde, daß die Hirten nicht mehr sich selber weiden, und Ich errette aus ihrem Munde Meine Herde, daß sie nicht mehr ihnen zur Speise sind.',
        11: 'Denn also spricht der Herr Jehovah: Siehe, Ich, Ich will nach Meiner Herde fragen, nach ihnen forschen.',
        12: 'Gleichwie der Hirte nach seinem Triebe forscht am Tage, da er inmitten seiner verstreuten Herde ist, so will Ich nach Meiner Herde forschen und sie erretten von allen Orten, dahin sie zerstreut werden am Tage der Wolke und der Düsterheit.',
        13: 'Und Ich will sie von den Völkern herausführen und sie zusammenbringen aus den Ländern, und will sie hereinbringen auf ihren Boden und sie weiden auf den Bergen Israels, in den Tälern und in allen Wohnsitzen des Landes.',
        14: 'Auf guter Weide werde Ich sie weiden, und auf den emporragenden Bergen Israels soll ihre Hürde sein, dort sollen sie sich lagern in guter Hürde, und auf fetter Weide weiden auf den Bergen Israels.',
        15: 'Ich selbst will Meine Herde weiden, und Ich will sie lagern lassen, spricht der Herr Jehovah;',
        16: 'Die Verlorenen will Ich suchen und die Verscheuchten zurückbringen und die Gebrochenen verbinden und die Kranken stärken, das Fette aber und Starke will Ich vernichten; Ich werde sie weiden nach dem Recht.',
        17: 'Und ihr, Meine Herde, so spricht der Herr Jehovah, siehe, Ich richte zwischen Schaf und Schaf, zwischen den Widdern und Böcken.',
        18: 'Ist es euch zu wenig, daß ihr die gute Weide abweidet, und daß ihr, was überbleibt von eurer Weide, zerstampft mit euren Füßen? und daß ihr das abgestandene Wasser trinkt und das übrige mit euren Füßen aufstört?',
        19: 'Und Meine Herde weidet ab, was ihr zerstampft habt mit den Füßen, und trinkt, was eure Füße aufgestört haben?',
        20: 'Darum spricht so der Herr Jehovah zu ihnen: Sehet Mich, Ich richte zwischen gemästetem Schaf und magerem Schaf.',
        21: 'Weil ihr mit Seite und Schulter hintreibt und stoßt mit euren Hörnern alle die schwachen Schafe, bis ihr sie hinauszerstreut habt.',
        22: 'Ich aber rette Meine Herde, daß sie nicht mehr zum Raube werden, und richte zwischen Schaf und Schaf.',
        23: 'Und einen Hirten lasse Ich über sie erstehen, daß Er sie weide, Meinen Knecht David. Er soll sie weiden, und Er soll ihr Hirte sein.',
        24: 'Und Ich, Jehovah, will ihnen zum Gott sein, und Mein Knecht David soll Fürst in ihrer Mitte sein. Ich, Jehovah, habe es geredet.',
        25: 'Und will mit ihnen einen Bund des Friedens schließen, und wegschaffen aus dem Lande das böse wilde Tier, daß in der Wüste sie in Sicherheit wohnen, und in den Wäldern schlafen.',
        26: 'Und will sie selbst und die Umgebungen Meines Hügels zum Segen geben, und zu seiner Zeit Platzregen herabgießen, Platzregen des Segens sollen es sein,',
        27: 'Und der Baum des Feldes wird geben seine Frucht, und die Erde geben ihr Gewächs, und sie sollen auf ihrem Boden sicher sein und wissen, daß Ich Jehovah bin, wenn Ich die Stäbe ihres Joches breche, und sie errette aus der Hand derer, die sie sich dienstbar machten.',
        28: 'Und sie sollen nicht mehr ein Raub der Heiden werden, und das wilde Tier der Erde soll sie nicht fressen, so daß sie in Sicherheit wohnen und niemand sie aufscheuche.',
        29: 'Und Ich lasse ihnen eine Pflanze erstehen zum Namen, daß sie nicht mehr vom Hunger im Lande dahingerafft werden, und nicht mehr die Schande der Völkerschaften tragen,',
        30: 'Und sie sollen wissen, daß Ich, Jehovah, ihr Gott, mit ihnen bin, und sie, das Haus Israels, Mein Volk sind, spricht der Herr Jehovah.',
        31: 'Und ihr seid Meine Herde, die Herde Meiner Weide, ein Mensch seid ihr; Ich bin euer Gott, spricht der Herr Jehovah.',
    },
    35: {
        1: 'Und das Wort Jehovahs geschah an mich, sprechend:',
        2: 'Menschensohn, richte dein Angesicht wider den Berg Seir und weissage dawider!',
        3: 'Und sprich zu ihm: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Berg Seir, und strecke Meine Hand aus wider dich und mache dich zur Verwüstung und Wüstenei.',
        4: 'Zur Öde will Ich deine Städte machen, und zur Verwüstung sollst du werden, und du sollst wissen, daß Ich Jehovah bin.',
        5: 'Darum, daß du ewige Feindschaft hast und Israels Söhne in die Hände des Schwertes hingabst zur Zeit ihrer Not, zur Zeit des Endes der Missetat.',
        6: 'Darum, bei Meinem Leben, spricht der Herr Jehovah, mache Ich dich zu Blut, und Blut soll dich verfolgen; da du Blut nicht haß-test, soll dich Blut verfolgen.',
        7: 'Darum mache Ich den Berg Seir zur Verwüstung und Wüstenei und rotte aus von ihm, der darüber hingeht und zurückkehrt.',
        8: 'Und seine Berge fülle Ich mit seinen Erschlagenen; deine Hügel und deine Schluchten und all deine Flußbette - vom Schwert Erschlagene sollen allda fallen!',
        9: 'Zur ewigen Verwüstung mache Ich dich, und deine Städte sollen nicht bewohnt werden, und ihr sollt wissen, daß Ich Jehovah bin.',
        10: 'Weil du gesprochen hast: Die zwei Völkerschaften und die zwei Länder sollen mein sein, und wir werden sie erblich besitzen; und Jehovah ist dort,',
        11: 'Darum, bei Meinem Leben, spricht der Herr Jehovah, so tue Ich nach deinem Zorn und nach deiner Eifersucht, wie du aus deinem Haß wider sie hast getan, und tue Mich kund an ihnen, wenn Ich dich richte,',
        12: 'Und du sollst wissen, daß Ich, Jehovah, hörte all deine Lästerungen, die du wider die Berge Israels gesprochen hast, sprechend: Sie sind verwüstet, sind zur Speise uns gegeben.',
        13: 'Und ihr tatet groß wider Mich mit eurem Munde, und eure Worte wider Mich habt ihr gehäuft. Ich hörte es.',
        14: 'So spricht der Herr Jehovah: Während fröhlich ist die ganze Erde, mache Ich zur Verwüstung dich.',
        15: 'Wie du fröhlich warst über das Erbe des Hauses Israel, daß es verwüstet ward, also werde Ich tun an dir. Zur Verwüstung sollst du werden, der Berg Seir und ganz Edom zumal, und sie sollen wissen, daß Ich Jehovah bin.',
    },
    36: {
        1: 'Und du, Menschensohn, weissage über die Berge Israels, und sprich: Höret, ihr Berge Israels, das Wort Jehovahs!',
        2: 'So spricht der Herr Jehovah: Darum, daß der Feind über euch sagt: Aha! und die Opferhöhen der Ewigkeit sind uns zum Erbbesitz worden!',
        3: 'Darum weissage und sprich: So spricht der Herr Jehovah: Weil und weil immer man rings umher euch verwüstet und wider euch schnaubt, daß ihr ein Erbbesitz werdet dem Überrest der Völkerschaften, und weil ihr seid aufgestiegen auf die Lippe der Zunge und zum Gerede des Volkes;',
        4: 'Darum hört, ihr Berge Israels, das Wort des Herrn Jehovah: So spricht der Herr Jehovah zu den Bergen und zu den Hügeln, zu den Flußbetten und zu den Schluchten, und zu den Öden, den verwüsteten, und zu den verlassenen Städten, die dem Überrest der Völkerschaften ringsumher zum Raub und Gelächter geworden waren;',
        5: 'Darum, so spricht der Herr Jehovah, habe Ich im Feuer Meines Eifers geredet über den Überrest der Völkerschaften und über Edom allzumal, die sich selbst Mein Land mit Fröhlichkeit des ganzen Herzens, mit dem Hohne der Seele zum Erbbesitz gegeben hatten, um seinen Ertrag zu rauben.',
        6: 'Darum weissage über den Boden Israels und sprich zu den Bergen und zu den Hügeln, zu den Flußbetten und zu den Schluchten: Also spricht der Herr Jehovah: Siehe, in Meinem Eifer und in Meinem Grimm habe Ich geredet, weil ihr die Schande der Völkerschaften getragen habt;',
        7: 'Darum spricht also der Herr Jehovah, habe Meine Hand Ich erhoben. Fürwahr, die Völkerschaften rings um euch her, sie sollen tragen ihre Schande!',
        8: 'Ihr aber, Berge Israels, sollt eure Zweige treiben und eure Frucht tragen für Mein Volk Israel; denn sie nahen sich, daß sie kommen,',
        9: 'Denn siehe, Ich bin bei euch und wende Mich zu euch, und ihr werdet bebaut und besät werden;',
        10: 'Und will auf euch den Menschen mehren, das ganze Haus Israel allzumal, und die Städte sollen bewohnt und die Öden aufgebaut werden;',
        11: 'Und Ich will auf euch den Menschen und das Vieh mehren, und sie sollen sich mehren und fruchtbar sein, und lasse euch wohnen wie in euren Vorzeiten, und tue euch mehr Gutes, denn in euren Anfängen, und ihr sollt wissen, daß Ich Jehovah bin.',
        12: 'Und Ich will den Menschen auf euch wandeln lassen, Mein Volk Israel, daß sie dich erblich besitzen und du ihr Erbe seiest, und sollst sie nicht mehr kinderlos machen.',
        13: 'So spricht der Herr Jehovah: Weil sie zu euch sprechen: Du frißt den Menschen und machst kinderlos deine Völkerschaften;',
        14: 'Darum sollst du nicht mehr den Menschen fressen und deine Völkerschaften nicht mehr kinderlos machen, spricht der Herr Jehovah.',
        15: 'Und Ich lasse nicht mehr über dich die Beschimpfung der Völkerschaften hören, und die Schmähung der Völker sollst du nicht mehr tragen, und deine Völkerschaften sollst du nicht mehr kinderlos machen, spricht der Herr Jehovah.',
        16: 'Und es geschah zu mir Jehovahs Wort, sprechend:',
        17: 'Menschensohn, das Haus Israel, sie wohnten auf ihrem Boden, und verunreinigten ihn mit ihrem Weg und ihrem Tun. Wie die Unreinheit der Befleckung war ihr Weg vor Mir.',
        18: 'Und Ich ergoß Meinen Grimm über sie des Blutes wegen, das sie vergossen in dem Land, und durch ihre Götzen hatten sie es verunreinigt.',
        19: 'Und Ich zerstreute sie unter die Völkerschaften; und in die Länder wurden sie versprengt. Nach ihrem Weg und ihrem Tun hatte Ich sie gerichtet.',
        20: 'Und sie kamen unter die Völkerschaften, dahin sie kamen, und entweihten den Namen Meiner Heiligkeit, indem man von ihnen sagte: Die sind das Volk Jehovahs, und aus Seinem Lande sind sie ausgezogen.',
        21: 'Ich aber will schonen den Namen Meiner Heiligkeit, den sie, das Haus Israel, entweihten, unter den Völkerschaften, dahin sie kamen.',
        22: 'Darum sprich zu dem Hause Israels: So spricht der Herr Jehovah: Nicht euretwegen tue Ich es, ihr vom Hause Israels, sondern für den Namen Meiner Heiligkeit, den ihr entweihtet unter den Völkerschaften, dahin ihr kamet,',
        23: 'Daß Meinen großen Namen Ich heilige, der unter den Völkerschaften ist entweiht worden, den ihr in ihrer Mitte entweiht habt, auf daß die Völkerschaften wissen, daß Ich Jehovah bin, spricht der Herr Jehovah, da Ich Mich heilige in euch vor euren Augen.',
        24: 'Und Ich werde euch von den Völkerschaften nehmen und euch zusammenbringen aus allen Ländern, und euch hereinbringen auf euern Boden,',
        25: 'Und werde sprengen reine Wasser über euch, daß ihr von allen euren Unreinheiten rein werdet, und werde euch reinigen von allen euren Götzen.',
        26: 'Und Ich gebe euch ein neues Herz, und will euch einen neuen Geist in euer Inneres geben; und will das Herz von Stein wegtun aus eurem Fleische und euch ein Herz von Fleisch geben,',
        27: 'Und Meinen Geist will Ich in euer Inneres geben und machen, daß ihr in Meinen Satzungen wandelt und Meine Rechte haltet und sie tut.',
        28: 'Und ihr sollt wohnen in dem Land, das euren Vätern Ich gegeben habe, und sollt Mein Volk sein, und Ich will Gott euch sein.',
        29: 'Und Ich will euch von allen euren Unreinheiten retten, und will rufen dem Korn und es mehren, und gebe keine Hungersnot auf euch.',
        30: 'Und Ich will die Frucht des Baumes und den Ertrag des Feldes mehren, daß ihr nicht mehr unter den Völkerschaften die Schmach der Hungersnot auf euch nehmt.',
        31: 'Und ihr werdet eurer bösen Wege gedenken, und eures Tuns, das nicht gut war, und euch wird vor euch selber verdrießen ob eurer Missetaten und ob eurer Greuel.',
        32: 'Nicht euretwegen tue Ich es, spricht der Herr Jehovah; das sei euch zu wissen getan. Schämt euch und werdet zuschanden über euren Wegen, o Haus Israel.',
        33: 'So spricht der Herr Jehovah: Am Tage, da Ich euch reinige von all euren Missetaten, da lasse Ich die Städte wieder bewohnen und die Öden werden aufgebaut.',
        34: 'Und das verwüstete Land soll bebaut werden, statt daß es eine Verwüstung war vor den Augen eines jeden, der vorüber- ging.',
        35: 'Und sagen sollen sie: Dies Land, das verwüstet war, ist wie der Garten Edens, und die Städte, die verödet und verwüstet und eingerissen waren, sind befestigt, sie sind bewohnt.',
        36: 'Und die Völkerschaften, die verblieben um euch her, sollen wissen, daß Ich, Jehovah, das Eingerissene gebaut, bepflanzt das Verwüstete. Ich, Jehovah, habe es geredet und getan.',
        37: 'So spricht der Herr Jehovah: Noch darin lasse Ich Mich erbitten vom Hause Israels, daß Ich es ihnen tue. Ich will sie mehren, wie eine Herde von Menschen.',
        38: 'Wie die Herde der Heiligtümer, wie die Herde Jerusalems an seinen Festzeiten, so sollen die verödeten Städte voll sein von einer Herde von Menschen, und sie sollen wissen, daß Ich Jehovah bin.',
    },
    37: {
        1: 'Und es war auf mir Jehovahs Hand, und Er brachte mich heraus im Geist Jehovahs, und ließ mich nieder inmitten einer Talebene, und sie war voll von Gebeinen.',
        2: 'Und Er ließ mich darüber hinziehen ringsum und ringsum, und siehe, ihrer waren sehr viel auf der Fläche der Talebene; und siehe, sie waren gar sehr verdorrt.',
        3: 'Und er sprach zu mir: Menschensohn, werden diese Gebeine leben? Und ich sprach: Herr Jehovah, Du weißt es.',
        4: 'Und Er sprach zu mir: Weissage über diese Gebeine und sprich zu ihnen: Ihr verdorrte Gebeine, hört das Wort Jehovahs.',
        5: 'So spricht der Herr Jehovah zu diesen Gebeinen: Siehe, Ich bringe Geist in euch, auf daß ihr lebet;',
        6: 'Und Ich gebe Sehnen auf euch, und lasse Fleisch auf euch heraufkommen und überdecke euch mit Haut, und gebe Geist in euch, auf daß ihr lebet, und ihr sollt wissen, daß Ich Jehovah bin.',
        7: 'Und ich weissagte, wie mir geboten war, und es ward eine Stimme, als ich weissagte, und siehe, ein Beben und die Gebeine nahten sich, Gebein zu seinem Gebein.',
        8: 'Und ich sah und siehe, über sie kamen herauf Sehnen und Fleisch, und es überdeckte sie Haut von oben; und es war kein Geist in ihnen.',
        9: 'Und Er sprach zu mir: Weissage über den Geist! Weissage, Menschensohn, und sprich zum Geist: So spricht der Herr Jehovah: Von den vier Winden komme Geist, und hauche diese Erwürgten an, auf daß sie leben.',
        10: 'Und ich weissagte, wie Er mir gebot; und der Geist kam in sie, und sie lebten, und sie standen auf ihren Füßen, eine sehr, sehr große Streitmacht.',
        11: 'Und Er sprach zu mir: Menschensohn, diese Gebeine, sie sind das ganze Haus Israel. Siehe, sie sprechen: Verdorrt sind unsere Gebeine, und verloren unsere Hoffnung, wir sind abgeschnitten!',
        12: 'Darum weissage und sprich zu ihnen: Also spricht der Herr Jehovah: Siehe, Ich öffne eure Gräber und bringe euch herauf aus euren Gräbern, Mein Volk, und bringe euch hinein auf den Boden Israels.',
        13: 'Und ihr sollt wissen, daß Ich Jehovah bin, wenn eure Gräber Ich geöffnet und euch, Mein Volk, aus euren Gräbern habe lassen aufsteigen;',
        14: 'Und gebe Meinen Geist in euch, auf daß ihr lebet, und lasse euch auf euren Boden nieder, auf daß ihr wisset, daß Ich, Jehovah, es habe geredet und getan, spricht Jehovah.',
        15: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        16: 'Und du, Menschensohn, nimm ein Holz dir und schreibe darauf: Dem Jehudah und den Söhnen Israels, seinen Gefährten; und nimm ein Holz und schreibe darauf: Dem Joseph, das Holz Ephraims und des ganzen Hauses Israels, seiner Gefährten!',
        17: 'Und bringe sie für dich nahe, eins zum anderen, zu einem Holz, daß sie eins seien in deiner Hand.',
        18: 'Und wie die Söhne deines Volkes zu dir sprechen und sagen: Willst du uns nicht ansagen, was dir das sein soll?',
        19: 'Rede du zu ihnen: So spricht der Herr Jehovah: Siehe, Ich nehme Josephs Holz, das in der Hand Ephraims und der Stämme Israels, seiner Gefährten, ist, und Ich gebe sie, die darauf sind, zum Holze Jehudahs und mache sie zu einem Holz, auf daß sie eins seien in Meiner Hand.',
        20: 'Und sie sollen die Hölzer, auf die du geschrieben hast, in deiner Hand vor ihren Augen sein.',
        21: 'Und rede du zu ihnen: Also spricht der Herr Jehovah: Siehe, Ich nehme die Völker Israels heraus von den Völkerschaften, dahin sie gegangen waren, und bringe sie zusammen von ringsumher und bringe sie herein auf ihren Boden;',
        22: 'Und Ich mache sie zu einer Völkerschaft im Lande auf Israels Bergen, und ein König soll für sie alle König sein, daß nicht mehr zwei Völkerschaften seien und sie nicht noch in zwei Reiche mehr sich teilen.',
        23: 'Und nicht werden sie sich mehr mit ihren Götzen und ihren Scheusalen und auf all ihren Übertretungen verunreinigen. Und Ich rette sie aus allen ihren Wohnsitzen, worin sie sündigten, und reinige sie, daß sie Mein Volk werden, und Ich ihnen Gott sei.',
        24: 'Und Mein Knecht David wird König sein über sie und wird ein Hirte sein für sie alle, und in Meinen Rechten werden sie wandeln, und halten Meine Satzungen und sie tun.',
        25: 'Und werden in dem Lande wohnen, das Ich Meinem Knechte, dem Jakob, gegeben habe, in dem wohnten eure Väter, und in ihm werden wohnen sie und ihre Söhne und ihrer Söhne Söhne in Ewigkeit, und Mein Knecht David soll ihr Fürst sein ewiglich.',
        26: 'Und Ich will einen Bund des Friedens mit ihnen schließen, ein Bund der Ewigkeit soll es für sie sein. Und Ich gebe sie und mehre sie und gebe Mein Heiligtum in ihre Mitte ewiglich.',
        27: 'Und Meine Wohnung soll sein bei ihnen, und Ich will ihr Gott sein und sie sollen Mein Volk sein.',
        28: 'Und die Völkerschaften sollen wissen, daß Ich, Jehovah, Israel heilige, wenn Mein Heiligtum ewiglich in ihrer Mitte ist.',
    },
    38: {
        1: 'Und es geschah Jehovahs Wort zu mir, sprechend:',
        2: 'Menschensohn, richte dein Angesicht gegen Gog, das Land Magog, den Fürsten, das Haupt von Meschech und Thubal, und weissage wider ihn,',
        3: 'Und sprich: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Gog, du Fürst, Haupt von Meschech und Thubal,',
        4: 'Und Ich wende dich zurück und tue Haken in deine Kinnbacken und bringe heraus dich und all deine Streitmacht, Rosse und Reiter, alle vollkommen gekleidet, eine große Versammlung mit Schild und Tartsche, allesamt fassend die Schwerter.',
        5: 'Perser, Kusch und Pud mit ihnen, sie alle mit Tartsche und Helm.',
        6: 'Gomer und alle seine Scharen, Beth Thogarmah, an den Seiten der Mitternacht, und alle seine Scharen, viele Völker mit dir.',
        7: 'Sei bereit und bereite dich, du und alle deine Versammlung, die sich um dich angesammelt, und sei ihnen zur Hut.',
        8: 'Nach vielen Tagen wirst du heimgesucht werden, in der Zukunft Jahren wirst du kommen in ein Land, das vom Schwert zurückgebracht aus vielen Völkern zusammengebracht worden, auf die Berge Israels, die beständig eine Öde gewesen, das aus den Völkern herausgebracht worden ist, und wohnen allesamt sicher.',
        9: 'Und wie ein Unwetter ziehst du herauf, du kommst, wie eine Wolke, das Land zu bedecken wirst du sein, du und all deine Scharen, und viele Völker mit dir.',
        10: 'So spricht der Herr Jehovah: Und geschehen wird an jenem Tag, daß Dinge in dein Herz aufsteigen und du böse Gedanken denkst,',
        11: 'Und sprichst: Ich will hinaufziehen in ein offenliegendes Land, will kommen zu denen, die rasten, die wohnen in Sicherheit. Sie alle wohnen ohne Mauer und Riegel, und Torflügel haben sie keine.',
        12: 'Um Beute zu erbeuten und Raub zu rauben, und deine Hand zurückzukehren wider die Öden, die bewohnt sind, und wider ein Volk, das aus den Völkerschaften ist gesammelt worden, und Viehherden und Habe sich schafft und wohnt im Nabel der Erde.',
        13: 'Scheba und Dedan und die Händler von Tharschisch und alle seine jungen Löwen werden zu dir sagen: Bist du gekommen Beute zu erbeuten, um Raub zu rauben, hast deine Versammlung du angesammelt, auf daß du Silber und Gold wegtragest, Viehherde und Habe wegnehmest, um große Beute zu erbeuten?',
        14: 'Darum weissage, Menschensohn, und sprich zu Gog: So spricht der Herr Jehovah: Wirst du nicht an jenem Tag es wissen, daß Mein Volk Israel wohnt in Sicherheit?',
        15: 'Und du kommst von deinem Ort, von den Seiten der Mitternacht, du und viele Völker mit dir, sie alle auf Rossen reitend, eine große Versammlung und viele Streitmacht.',
        16: 'Und ziehst herauf wider Mein Volk Israel, wie eine Wolke das Land zu bedecken. In der Zukunft der Tage wird es geschehen, daß Ich dich in Mein Land hereinbringe, auf daß die Völkerschaften Mich erkennen, wie Ich Mich durch dich, o Gog, vor ihren Augen heilige.',
        17: 'So spricht der Herr Jehovah: Bist du es, von dem Ich in den Tagen der Vorzeit durch die Hand Meiner Knechte, der Propheten Israels, geredet habe, die in jenen Tagen jahrelang weissagten, daß Ich dich wider sie hereinbringen würde?',
        18: 'Und wird geschehen an selbigem Tage, am Tage, da Gog auf den Boden Israels kommt, sagt der Herr Jehovah, daß Mein Grimm aufsteigt in Meinem Zorn.',
        19: 'Und in Meinem Eifer, im Feuer Meines Wütens, rede Ich: Fürwahr, an jenem Tage wird ein großes Erdbeben sein auf dem Boden Israels,',
        20: 'Daß vor Meinem Angesicht beben die Fische des Meeres und der Himmel Gevögel und das wilde Tier des Feldes und all das Kriechtier, das auf dem Boden kriecht, und jeder Mensch auf den Angesichten des Bodens; und Berge werden umgerissen und Felsenwände fallen und zur Erde fällt jede Mauer.',
        21: 'Und Ich rufe wider ihn auf allen Meinen Bergen das Schwert, spricht der Herr Jehovah, das Schwert des Mannes soll wider seinen Bruder sein.',
        22: 'Und Ich will mit ihm rechten mit Pest und mit Blut, und mit überflutendem Platzregen; und Steine des Hagels, Feuer und Schwefel, lasse Ich regnen über ihn und über seine Scharen, und über die vielen Völker, die mit ihm sind.',
        23: 'Und Ich erweise Mich groß und heilige Mich, und tue Mich kund vor den Augen vieler Völkerschaften, auf daß sie wissen, daß Ich Jehovah bin.',
    },
    39: {
        1: 'Und du, Menschensohn, weissage wider Gog und sprich: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Gog, Fürst, Haupt über Meschech und Thubal.',
        2: 'Und Ich wende dich zurück und sechsteile dich und lasse dich von den Seiten der Mitternacht heraufsteigen und bringe dich herein auf die Berge Israels.',
        3: 'Und schlage dir deinen Bogen aus deiner linken Hand und lasse dir deine Pfeile aus der rechten Hand fallen.',
        4: 'Auf den Bergen Israels sollst du fallen, du und alle deine Scharen, und die Völker, die mit dir sind; und den Raubvögeln, den Vögeln jeglichen Flügels und dem wilden Tier des Feldes gebe Ich dich zur Speise.',
        5: 'Auf dem Angesichte des Feldes sollst du fallen, denn Ich habe geredet, spricht der Herr Jehovah.',
        6: 'Und Feuer sende Ich gegen Magog und die, so sicher auf den Inseln wohnen, auf daß sie erkennen, daß Ich Jehovah bin.',
        7: 'Und den Namen Meiner Heiligkeit tue Ich kund inmitten Meines Volkes Israel, und lasse nicht mehr entweihen den Namen Meiner Heiligkeit, und erkennen sollen die Völkerschaften, daß Ich Jehovah bin, der Heilige in Israel.',
        8: 'Siehe, es kommt und es geschieht, spricht der Herr Jehovah, dies ist der Tag, von dem Ich geredet habe.',
        9: 'Und die, so in den Städten Israels wohnen, gehen hinaus und brennen, und feuern mit Waffen, und mit Tartsche und Schild, mit dem Bogen und Pfeilen und dem Stecken der Hand, und mit dem Speere; und Feuer davon brennen sie sieben Jahre.',
        10: 'Und sie werden kein Holz vom Feld tragen, noch es hauen aus den Wäldern; denn mit den Waffen lassen sie brennen das Feuer. Und sie machen Beute von denen, welchen sie zur Beute waren, und rauben von ihren Räubern, spricht der Herr Jehovah.',
        11: 'Und am selbigen Tage wird geschehen, daß Ich dem Gog dort Platz für ein Grab in Israel gebe, die Schlucht der Vorübergehenden, ostwärts vom Meere, und es ist eine Sperre für die Vorübergehenden; und dort werden sie den Gog und all seine Volksmenge begraben und es nennen die Schlucht der Volksmenge Gogs.',
        12: 'Und das Haus Israel wird sie begraben, um das Land zu reinigen, sieben Monate.',
        13: 'Und alles Volk des Landes wird begraben, und es wird ihnen zum Namen sein an dem Tag, da Ich Mich verherrliche, spricht der Herr Jehovah.',
        14: 'Und beständige Männer werden sie ausscheiden, die das Land durchziehen und mit den Durchziehenden begraben sie die, so auf den Angesichten des Landes übriggeblieben sind, es zu reinigen. Nach dem Ende von sieben Monaten werden sie forschen.',
        15: 'Und die Durchziehenden werden das Land durchziehen, und sieht einer das Gebein eines Menschen, so baut er ein Mahlzeichen daneben auf, bis die Begrabenden es in Ge-Hamon-Gog begraben.',
        16: 'Und auch der Name der Stadt ist Hamonah, und sie reinigen das Land.',
        17: 'Und du, Menschensohn, so spricht der Herr Jehovah: Sprich zu den Vögeln jeglichen Flügels und zu allem wilden Tiere des Feldes: Tut euch zusammen und kommet, versammelt euch ringsumher zu Meinem Opfer, das Ich für euch opfere, ein großes Opfer auf den Bergen Israels, und esset Fleisch und trinket Blut.',
        18: 'Das Fleisch der Helden sollt ihr essen, und das Blut der Fürsten der Erde trinken, Widder, Lämmer und Böcke, Farren, die gemästeten Baschans allzumal.',
        19: 'Und ihr sollt Fett essen bis zur Sättigung, und Blut trinken bis zur Trunkenheit von Meinem Opfer, das Ich für euch opfere.',
        20: 'Und sättigt euch an Meinem Tisch von Roß und Streitwagen, vom Helden und jeglichem Manne des Streites, spricht der Herr Jehovah.',
        21: 'Und Ich werde Meine Herrlichkeit unter die Völkerschaften geben, daß alle Völkerschaften sehen Mein Gericht, das Ich habe geübt, und Meine Hand, die Ich an sie gelegt.',
        22: 'Und daß sie, das Haus Israel, wissen, daß Ich, Jehovah, ihr Gott bin von diesem Tage an und hinfort.',
        23: 'Und daß wissen die Völkerschaften, daß die vom Hause Israel ob ihrer Missetat fortgeführt wurden, weil sie Mir untreu wurden; darum Ich Mein Angesicht verbarg vor ihnen und sie in die Hände ihrer Dränger gab, so daß sie allesamt durch das Schwert fielen.',
        24: 'Ob ihrer Unreinheiten und ihrer Übertretungen habe Ich so getan an ihnen und Mein Angesicht verborgen vor denselben.',
        25: 'Darum spricht so der Herr Jehovah: Nun bringe Ich die Gefangenschaft Jakobs zurück und erbarme Mich des ganzen Hauses Israel und eifere für den Namen Meiner Heiligkeit.',
        26: 'Und sie sollen tragen ihre Schande und alle ihre Untreue, die sie begingen gegen Mich, wenn sie in Sicherheit auf ihrem Boden wohnen und niemand sie aufscheucht.',
        27: 'Wenn Ich sie aus den Völkern zurückbringe und sie zusammenbringe aus den Ländern ihrer Feinde, und Mich heilige an ihnen vor den Augen vieler Völkerschaften;',
        28: 'Und sie sollen wissen, daß Ich Jehovah bin, ihr Gott, Der sie wegführte unter die Völkerschaften, und sie wieder zusammenfaßte auf ihren Boden und keinen mehr von ihnen übrig ließ;',
        29: 'Und will Mein Angesicht nicht mehr verbergen vor ihnen, weil Meinen Geist Ich über das Haus Israel ausgießen werde, spricht der Herr Jehovah.',
    },
    40: {
        1: 'Im fünfundzwanzigsten Jahr unserer Wegführung, im Anfang des Jahres, am zehnten Tag des Monats, im vierzehnten Jahr, nachdem die Stadt geschlagen war, an ebendemselben Tag, war über mir die Hand Jehovahs und brachte mich dahin.',
        2: 'In Gesichten Gottes brachte Er mich hinein zum Land Israels und ließ mich nieder auf einen sehr hohen Berg, und auf ihm war wie das Gebäu einer Stadt vom Mittag her.',
        3: 'Und Er brachte mich dahin, und siehe, da war ein Mann, sein Ansehen wie das Ansehen von Erz, und eine leinene Schnur war in seiner Hand und ein Rohr zum Messen; und er stand in dem Tor.',
        4: 'Und der Mann redete zu mir: Menschensohn, siehe mit deinen Augen und mit deinen Ohren höre, und richte dein Herz auf alles, was ich dich sehen lasse; denn damit ich dir es zeige, bist du hierher gebracht. Alles, was du siehst, sage an dem Hause Israel.',
        5: 'Und siehe, eine Mauer war von außen am Hause, ringsum, ringsum. Und der Mann hatte in der Hand ein Rohr zum Messen von sechs Ellen, nach der Elle und eine Handbreite; und er maß die Breite des Gebäus eine Rute und die Höhe eine Rute.',
        6: 'Und er ging hinein zum Tor, das am Wege gegen Osten war, und stieg dessen Stufen hinauf und maß die Schwelle des Tores zu einer Rute in die Breite und die andere Schwelle eine Rute breit.',
        7: 'Und die Wachtzelle eine Rute nach der Länge, eine Rute in der Breite. Und zwischen den Wachtzellen waren es fünf Ellen, und die Schwelle des Tores neben der Vorhalle des Tores von innen her eine Rute.',
        8: 'Und er maß die Vorhalle des Tores von innen zu einer Rute.',
        9: 'Und er maß die Vorhalle des Tores acht Ellen, und die Vorsprünge davon zwei Ellen; und die Vorhalle des Tores innerhalb.',
        10: 'Und der Wachtzellen des Tores am Wege gegen Osten waren drei hüben und drei drüben, ein Maß für deren drei, und ein Maß für die Vorsprünge hüben und drüben.',
        11: 'Und er maß die Breite des Eingangs des Tores zehn Ellen, die Länge des Tores dreizehn Ellen.',
        12: 'Und die Grenzwehr vor den Wachtzellen war eine Elle, und eine Elle Grenzwehr dort. Aber die Wachtzellen waren von sechs Ellen hier und von sechs Ellen dort.',
        13: 'Und er maß das Tor vom Dach der Wachtzelle bis zu seinem Dach, fünfundzwanzig Ellen in die Breite, Eingang gegen Eingang.',
        14: 'Und er machte die Erker sechzig Ellen, und vor dem Erker war der Vorhof am Tore ringsum und ringsum.',
        15: 'Und vor dem Tore des Eintritts bis vor die Vorhalle am inneren Tor waren es fünfzig Ellen.',
        16: 'Und geschlitzte Fenster waren an den Wachtzellen, und an ihren Vorsprüngen einwärts dem Tore zu, ringsum und ringsum, und so an den Vorhallen, und Fenster waren ringsum und ringsum einwärts. Und an den Vorsprüngen waren Palmen.',
        17: 'Und er brachte mich zu dem äußeren Vorhof, und siehe, da waren Zellen und ein Pflaster gemacht am Vorhof ringsum, ringsum, dreißig Zellen waren auf dem Pflaster.',
        18: 'Und das Pflaster war zur Seite der Tore, der Länge der Tore entlang, - das niedere Pflaster.',
        19: 'Und er maß die Breite vor dem unteren Tor, vor dem inneren Vorhof, außerhalb, hundert Ellen, gegen Osten und gegen Mitternacht;',
        20: 'Und das Tor, dessen Vorderseite am Wege nach Mitternacht des äußeren Vorhofs ist, maß er nach seiner Länge und nach seiner Breite.',
        21: 'Und seiner Wachtzellen waren drei hier und drei dort, und seine Vorsprünge und seine Vorhallen waren nach dem Maß des ersten Tores fünfzig Ellen in die Länge und fünfundzwanzig Ellen in die Breite.',
        22: 'Und seine Fenster und seine Vorhallen und seine Palmen waren nach dem Maß des Tores, dessen Angesicht auf dem Wege nach Morgen ist, und auf sieben Stufen stieg man dazu hinauf, und seine Vorhalle war vor denselben.',
        23: 'Und das Tor zum inneren Vorhof war gegenüber dem Tore nach Mitternacht und nach Osten, und er maß hundert Ellen von Tor zu Tor.',
        24: 'Und er ließ mich den Weg gen Mittag gehen, und siehe, ein Tor am Weg nach Mittag, und er maß seine Pfeiler und seine Vorhallen nach denselben Maßen.',
        25: 'Und Fenster hatte es, und seine Vorhallen ringsum und ringsum, wie die selbigen Fenster fünfzig Ellen die Länge und die Breite fünfundzwanzig Ellen.',
        26: 'Und sieben Stufen hatten seine Treppen und seine Vorhalle davor, und hatte Palmen, eine hüben und eine drüben an seinen Pfeilern.',
        27: 'Und ein Tor zum inneren Vorhof war am Wege nach Mittag, und er maß von Tor zu Tor am Wege nach Mittag hundert Ellen.',
        28: 'Und er brachte mich hinein in den inneren Vorhof durch das Tor nach Mittag, und maß das Tor nach Mittag, nach denselben Maßen.',
        29: 'Und seine Wachtzellen und seine Pfeiler und seine Vorhallen waren nach diesen Maßen, und waren Fenster daran und an seinen Vorhallen ringsum und ringsum: fünfzig Ellen in die Länge und fünfundzwanzig in die Breite.',
        30: 'Und ringsum und ringsum waren Vorhallen, fünfundzwanzig Ellen in der Länge und fünf Ellen in der Breite.',
        31: 'Und seine Vorhallen waren dem äußeren Vorhof zu, und Palmen waren an seinen Pfeilern, und acht Stufen stieg man zu ihm hinauf.',
        32: 'Und er brachte mich hinein nach dem inneren Vorhof am Wege nach Osten, und maß das Tor nach denselben Maßen.',
        33: 'Und seine Wachtzellen und seine Pfeiler und seine Vorhallen waren nach denselben Maßen, und Fenster hatte es und seine Vorhallen ringsum, ringsum, in die Länge fünfzig Ellen, fünfundzwanzig Ellen in die Breite.',
        34: 'Und seine Vorhalle war nach dem äußeren Vorhof, und Palmen waren an seinen Pfeilern hüben und drüben, und acht Stufen stieg man zu ihm hinauf.',
        35: 'Und er brachte mich hinein zum Tor nach Mitternacht, und maß nach denselben Maßen,',
        36: 'Seine Wachtzellen, seine Pfeiler und seine Vorhallen, und seine Fenster waren ringsum, ringsum, fünfzig Ellen in die Länge und fünfundzwanzig Ellen in die Breite.',
        37: 'Und seine Pfeiler waren dem äußeren Vorhof zu, und Palmen waren an seinen Pfeilern hier und dort, und acht Stufen stieg man zu ihm hinauf.',
        38: 'Und da war eine Zelle, und ihr Eingang war an den Pfeilern der Tore. Da wuschen sie das Brandopfer ab.',
        39: 'Und in der Vorhalle des Tores waren zwei Tische hüben und zwei Tische drüben, das Brandopfer und das Sündopfer und das Schuldopfer darauf zu schlachten.',
        40: 'Und auf der Seite nach außen, da man zum Eingang des Tores nach Mitternacht aufsteigt, waren zwei Tische, und auf der anderen Seite der Vorhalle des Tores waren zwei Tische.',
        41: 'Vier Tische hüben und vier Tische drüben zur Seite des Tores: acht Tische, auf denen sie schlachteten.',
        42: 'Und die vier Tische für das Brandopfer waren von behauenen Steinen, anderthalb Ellen die Länge und anderthalb Ellen die Breite, und eine Elle die Höhe, auf dieselben legten sie die Geräte nieder, mit denen sie das Brandopfer und das Schlachtopfer schlachteten.',
        43: 'Und Herdsteine von einer Handbreite waren einwärts zugerichtet ringsum, ringsum, und auf den Tischen das Fleisch der Opfergabe.',
        44: 'Und außerhalb des inneren Tores waren Zellen der Sänger in dem inneren Hofe zur Seite des Tores gen Mitternacht, und ihre Vorderseiten waren des Weges gen Mittag; eine war an der Seite des Tores gen Osten, mit der Vorderseite des Weges gen Mitternacht.',
        45: 'Und er redete zu mir: Diese Zelle, deren Vorderseite des Weges gen Mittag ist, ist für die Priester, die der Hut des Hauses hüten.',
        46: 'Die Zelle aber, deren Vorderseite des Weges gen Mitternacht ist, ist für die Priester, welche die Hut des Altares hüten. Dies sind die Söhne Zadoks, die von den Söhnen Levis dem Jehovah nahen, Ihm Dienst zu tun.',
        47: 'Und er maß den Hof, zu einer Länge von hundert Ellen, und hundert Ellen Breite in das Gevierte. Und der Altar war vor dem Haus.',
        48: 'Und er brachte mich hinein zur Vorhalle des Hauses, und maß den Pfeiler der Vorhalle zu fünf Ellen hüben und fünf Ellen drüben, und die Breite des Tores war drei Ellen hüben und drei Ellen drüben.',
        49: 'Die Länge der Halle zwanzig Ellen, und die Breite elf Ellen, und samt den Stufen, auf denen sie hinangingen zu derselben, und Säulen waren bei den Pfeilern, eine hüben und eine drüben.',
    },
    41: {
        1: 'Und er ließ mich in den Tempel eingehen, und er maß die Pfeiler, sechs Ellen Breite hier und sechs Ellen Breite dort, nach der Breite des Zeltes.',
        2: 'Und die Breite des Eingangs war zehn Ellen, und die Seiten des Eingangs fünf Ellen hier und fünf Ellen dort, und er maß seine Länge, vierzig Ellen und die Breite zwanzig Ellen.',
        3: 'Und er ging in das Innere und maß den Pfeiler des Eingangs, zwei Ellen, und den Eingang, sechs Ellen, und die Breite des Eingangs sieben Ellen.',
        4: 'Und er maß seine Länge, zwanzig Ellen, und die Breite, zwanzig Ellen vor dem Tempel; und er sprach zu mir: Dies ist das Heilige der Heiligen.',
        5: 'Und er maß die Wand des Hauses, sechs Ellen, und die Breite des Seitengemachs vier Ellen, ringsum und rings um das Haus herum.',
        6: 'Und die Seitengemächer, Seitengemach an Seitengemach waren es dreiunddreißig, zweimal, und sie gingen herein in die Wand am Hause, die für die Seitengemächer ringsum, ringsum war zum Ergreifen, aber in die Wand des Hauses selbst griffen sie nicht ein.',
        7: 'Und es ward breiter aufwärts und aufwärts, wie es umherlief; denn die Umgänge am Hause waren übereinander, ringsum, rings um das Haus. Darum nahm die Breite am Hause aufwärts zu, wie man von unteren durch das mittlere nach dem oberen aufstieg.',
        8: 'Und ich sah am Hause die Höhe ringsum, ringsum von den Grundlagen der Seitengemächer, eine volle Rute, sechs Ellen bis an das Gelenk.',
        9: 'Die Breite der Mauer zum Seitengemach nach außen war fünf Ellen, und was gelassen wurde, war das Inwendige der Seitengemächer des Hauses.',
        10: 'Und zwischen den Zellen war eine Breite von zwanzig Ellen, rings um das Haus, ringsum und ringsum.',
        11: 'Und der Eingang zum Seitengemach war nach dem Freigelassenen, ein Eingang des Weges gen Mitternacht, und ein Eingang gen Mittag, und die Breite des freigelassenen Raumes war fünf Ellen ringsum und um.',
        12: 'Und der Bau auf der Fläche des Hofraumes an der Ecke des Weges nach dem Meere war siebzig Ellen die Breite, und die Wand des Baues hatte eine Breite von fünf Ellen ringsum und ringsum, und seine Länge neunzig Ellen.',
        13: 'Und er maß das Haus, eine Länge von hundert Ellen, und den Hofraum, und den Bau und seine Wände, eine Länge von hundert Ellen;',
        14: 'Und die Breite der Vorderseite des Hauses und den Hofraum gegen Osten hundert Ellen.',
        15: 'Und er maß die Länge des Baues vor dem Hofraum dahinter, und seine Galerien hier und dort hundert Ellen, und den inneren Tempel und des Vorhofs Hallen;',
        16: 'Die Schwellen und die verengten Fenster und die Galerien ringsum an den drei Seiten, gegenüber der Schwelle, war hölzernes Getäfel ringsum, ringsum, und von der Erde bis zu den Fenstern, und die Fenster waren bedeckt;',
        17: 'Über dem Eingang oben und bis in das innere Haus und außen und an der ganzen Wand ringsum, ringsum, im Inwendigen und im Auswendigen war es nach den Maßen.',
        18: 'Und waren gemacht Cherube und Palmen, und eine Palme zwischen Cherub und Cherub, und der Cherub hatte zwei Gesichter.',
        19: 'Und eines Menschen Angesicht der Palme zu hüben, und eines jungen Löwen Angesicht der Palme zu drüben. Das ward getan dem ganzen Haus ringsum, ringsum.',
        20: 'Von der Erde bis oberhalb des Eingangs waren die Cherube und die Palmen gemacht, und an der Wand des Tempels.',
        21: 'Die Türpfosten des Tempels waren viereckig und am Vorderteil des Heiligtums war Ansehen wie Ansehen.',
        22: 'Der Altar von Holz war drei Ellen an Höhe und seine Länge zwei Ellen. Und die Ecken an ihm und seine Länge und seine Wände waren von Holz. Und er redete zu mir: Dies ist der Tisch, der vor Jehovah ist.',
        23: 'Und zwei Türflügel hatte der Tempel und das Heiligtum.',
        24: 'Und zwei Türflügel hatten die Türen, zwei sich umwendende Türflügel; zwei für die eine Tür und zwei Türflügel für die andere.',
        25: 'Und an ihnen, an den Türflügeln des Tempels, waren Cherube und Palmen gemacht, so wie sie an den Wänden gemacht waren. Auch waren dicke Balken vorne außen an der Vorhalle.',
        26: 'Und die Fenster waren geschlitzt, und Palmen hüben und drüben an den Seiten der Vorhalle und an den Seitengemächern des Hauses und an den Balken.',
    },
    42: {
        1: 'Und er brachte mich hinaus, in den äußeren Vorhof, den Weg gen Mitternacht zu, und brachte mich hinein nach der Zelle, gegenüber dem Hofraum und gegenüber dem Gebäu nach Mitternacht hin;',
        2: 'Zu der Vorderseite, in einer Länge von hundert Ellen nach dem Eingang gen Mitternacht, und die Breite war fünfzig Ellen;',
        3: 'Gegenüber den zwanzigen im inneren Vorhof und gegenüber dem Pflaster im äußeren Vorhof war eine Galerie vor der anderen Galerie dreifach.',
        4: 'Und vor den Zellen war ein Gang von zehn Ellen Breite nach dem Inneren, ein Weg von einer Elle, und ihre Eingänge waren gen Mitternacht zu.',
        5: 'Und die oberen Zellen waren kürzer; denn die Galerien nahmen von ihnen, von den unteren und von den mittleren, weg am Gebäu.',
        6: 'Denn dreistöckig waren sie, und hatten keine Säulen wie die Säulen der Vorhöfe; darum zog man zurück von den untersten und von den mittleren von der Erde.',
        7: 'Und die Hofmauer, die außerhalb den Zellen entlang lief, des Weges dem äußeren Vorhof zu vor den Zellen, deren Länge war fünfzig Ellen.',
        8: 'Denn die Länge der Zellen dem äußeren Vorhof zu war fünfzig Ellen; aber siehe, vor dem Tempel hin war sie hundert Ellen.',
        9: 'Und unterhalb dieser Zellen war der Zugang vom Osten her, da man in sie hineinging vom äußeren Vorhof aus.',
        10: 'In der Breite der Hofmauer des Vorhofes, des Weges nach Osten hin, an der Vorderseite des Hofraumes und vor dem Gebäu, waren Zellen.',
        11: 'Und der Weg vor denselben hin war anzusehen wie der vor den Zellen am Weg gegen Mitternacht, nach ihrer Länge so war ihre Breite, und nach all ihren Ausgängen und nach ihren Einrichtungen und ihren Eingängen.',
        12: 'Und wie die Eingänge der Zellen des Weges gen Mittag war ein Eingang am Anfang des Weges, des Weges vor der geraden Hofmauer, des Weges gen Morgen, wo man durch sie eingeht.',
        13: 'Und er sprach zu mir: Die Zellen gen Mitternacht, die Zellen gen Mittag, die vor dem Hofraum sind, sie sind Zellen der Heiligkeit, wo die Priester essen, die Jehovah darbringen das Heilige des Heiligen. Dort legen sie nieder das Heilige des Heiligen, und das Speiseopfer und das Sündopfer und das Schuldopfer; denn der Ort ist heilig.',
        14: 'Wenn die Priester hineingehen, so sollen sie nicht aus dem Heiligtum hinausgehen in den äußeren Vorhof, sondern allda ihre Kleider, in denen sie Dienst getan, niederlegen, denn Heiligkeit sind sie; und andere Kleider anziehen, und dem nahen, was des Volkes ist.',
        15: 'Und er vollendete die Messungen des inneren Hauses und brachte mich hinaus, des Weges des Tores, dessen Vorderseite des Weges gen Osten ist, und maß es ringsum, ringsum.',
        16: 'Er maß gegen den Ostwind mit dem Meßrohr fünfhundert Ruten, mit dem Meßrohr ringsum.',
        17: 'Er maß gegen den Wind der Mitternacht, fünfhundert Ruten mit dem Meßrohr ringsum.',
        18: 'Gegen den Wind des Mittags maß er fünfhundert Ruten mit dem Meßrohr.',
        19: 'Er wandte sich um zum Wind der Meeresseite; er maß fünfhundert Ruten mit dem Meßrohr.',
        20: 'Nach den vier Winden maß er es. Es hatte eine Mauer ringsum, ringsum, in der Länge fünfhundert und in der Breite fünfhundert, um zu scheiden zwischen dem Heiligen und dem Gemeinen.',
    },
    43: {
        1: 'Und er ließ mich gehen zum Tor, dem Tor, das des Weges gen Osten gewendet ist.',
        2: 'Und siehe, die Herrlichkeit des Gottes Israels kam des Weges von Osten her, und Seine Stimme war wie die Stimme vieler Wasser, und die Erde leuchtete von Seiner Herrlichkeit.',
        3: 'Und das Ansehen der Erscheinung, die ich sah, war wie die Erscheinung, die ich sah, als ich kam die Stadt zu verderben, und die Erscheinung war wie die Erscheinung, die ich sah am Fluß Chebar, und ich fiel auf mein Angesicht.',
        4: 'Und die Herrlichkeit Jehovahs kam herein zu dem Haus, auf dem Wege des Tores, dessen Vorderseite auf dem Wege nach dem Osten ist.',
        5: 'Und der Geist hob mich auf und brachte mich hinein nach dem inneren Vorhof, und siehe, das Haus war voll der Herrlichkeit Jehovahs.',
        6: 'Und ich hörte, wie Einer aus dem Hause zu mir sprach; und ein Mann stand neben mir.',
        7: 'Und Er sprach zu mir: Menschensohn, dies ist der Ort Meines Thrones und der Ort der Sohlen Meiner Füße, wo Ich wohnen werde inmitten der Söhne Israels in Ewigkeit; und nicht sollen mehr verunreinigen die vom Hause Israels den Namen Meiner Heiligkeit, sie und ihre Könige, durch ihre Buhlerei und durch die Leichen ihrer Könige, wenn sie gestorben sind;',
        8: 'Weil sie ihre Schwelle neben Meine Schwelle und ihre Türpfosten neben Meine Türpfosten setzten, und die Wand war zwischen Mir und ihnen, und sie den Namen Meiner Heiligkeit verunreinigten durch ihre Greuel, die sie taten, da verzehrte Ich sie in Meinem Zorn.',
        9: 'Nun sollen sie fernhalten von Mir ihre Buhlerei und die Leichen ihrer Könige, und Ich will ewiglich in ihrer Mitte wohnen.',
        10: 'Du, Menschensohn, sage dem Hause Israels das Haus an, daß sie zuschanden werden ob ihrer Missetaten und dessen Ebenmaß messen.',
        11: 'Und werden sie zuschanden ob allem, was sie getan, so lasse sie erkennen die Gestaltung und das Ebenmaß des Hauses, und seine Ausgänge und seine Eingänge, und alle seine Gestaltungen, und alle seine Satzungen und all seine Gestaltungen, und all seine Gesetze, und schreibe sie vor ihren Augen nieder, daß sie alle seine Gestaltung und alle seine Satzungen halten und sie tun.',
        12: 'Dies ist das Gesetz des Hauses, das auf dem Gipfel des Berges ist: All seine Grenze ringsum, ringsum ist das Heilige des Heiligen. Siehe, dies ist das Gesetz des Hauses.',
        13: 'Und dies sind die Maße des Altars nach Ellen. Die Elle ist eine Elle und eine Handbreite. Und der Untersatz ist eine Elle und eine Elle die Breite, und sein Rand an seiner Einfassung ist ringsumher eine Spanne, und das ist der Rücken des Altars.',
        14: 'Und von dem Untersatz von Erde bis an die untere Einfassung sind es zwei Ellen, und die Breite eine Elle, und von der kleineren Einfassung bis zu der großen Einfassung sind es vier Ellen, und die Breite eine Elle.',
        15: 'Und der Herd vier Ellen, und von dem Herd und oberhalb sind vier Hörner.',
        16: 'Und der Herd war zwölf in der Länge bei zwölf in die Breite, viereckig nach seinen vier Seiten hin.',
        17: 'Und die Einfassung war vierzehn in die Länge bei vierzehn in die Breite an seinen vier Seiten, und sein Rand rings um denselben eine halbe Elle, und sein Untersatz eine Elle rings herum, und seine Stufen sind gegen Osten gewendet.',
        18: 'Und Er sprach zu mir: Menschensohn, so spricht der Herr Jehovah: Dies sind die Satzungen für den Altar am Tage, da man ihn macht, um Brandopfer darauf aufzuopfern und Blut darauf zu sprengen.',
        19: 'Und den Priestern, den Leviten, die aus dem Samen Zadoks sind, die Mir nahen, um Mir Dienst zu tun, spricht der Herr Jehovah, sollst du einen Farren, ein junges Rind als Sündopfer geben.',
        20: 'Und sollst von desselben Blut nehmen und auf seine vier Hörner sprengen, und an die vier Ecken der Einfassung, und an den Rand rings herum, und ihn entsündigen und sühnen;',
        21: 'Und sollst den Farren des Sündopfers nehmen und ihn verbrennen an einem verordneten Platz des Hauses, außerhalb des Heiligtums.',
        22: 'Und am zweiten Tage sollst du darbringen einen Bock der Ziegen ohne Fehl zum Sündopfer, und den Altar damit entsündigen, wie man ihn mit dem Farren entsündigte.',
        23: 'Und wenn du das Entsündigen vollendet hast, sollst du darbringen einen Farren, ein junges Rind ohne Fehl, und einen Widder von der Herde ohne Fehl,',
        24: 'Und sollst sie vor Jehovah darbringen, und sollen die Priester Salz über sie werfen, und sie als Brandopfer dem Jehovah aufopfern.',
        25: 'Sieben Tage sollst du des Tages zurichten einen Bock als Sündopfer. Und einen Farren, ein junges Rind und einen Widder von der Herde ohne Fehl sollen sie zurichten.',
        26: 'Sieben Tage sollen sie den Altar sühnen und ihn reinigen und seine Hände füllen.',
        27: 'Und haben sie die Tage vollendet, so soll geschehen am achten Tage und fernerhin, daß die Priester auf dem Altare zurichten eure Brandopfer und eure Dankopfer, und Ich werde Wohlgefallen an euch haben, spricht der Herr Jehovah.',
    },
    44: {
        1: 'Und er brachte mich zurück des Weges zum äußeren Tor des Heiligtums, das nach Osten gewendet ist, und es war verschlossen.',
        2: 'Und Jehovah sprach zu mir: Dies Tor soll verschlossen sein, es werde nicht geöffnet, und kein Mann gehe durch dasselbe ein; sondern Jehovah, der Gott Israels, geht durch dasselbe ein, und es sei verschlossen.',
        3: 'Doch der Fürst, da er Fürst ist, soll darin sitzen, um Brot zu essen vor Jehovah. Des Weges der Halle des Tores soll er eingehen und auf seinem Wege ausgehen.',
        4: 'Und Er brachte mich herein des Weges des Tores gen Mitternacht auf die Vorderseite des Hauses, und ich sah und siehe, es erfüllte die Herrlichkeit Jehovahs das Haus Jehovahs, und ich fiel auf mein Angesicht.',
        5: 'Und Jehovah sprach zu mir: Menschensohn, nimm es dir zu Herzen, und siehe mit deinen Augen und höre mit deinen Ohren alles, was Ich mit dir rede von allen Satzungen des Hauses Jehovahs und allen seinen Gesetzen, und nimm dir zu Herzen das Eingehen in das Haus mit all dem Ausgehen aus dem Heiligtum.',
        6: 'Und sprich zu den Widerspenstigen, zum Hause Israels: So spricht der Herr Jehovah: Zuviel für euch sind all eure Greuel, Haus Israels,',
        7: 'Darum, daß ihr Söhne des Auslandes, unbeschnittenen Herzens und unbeschnittenen Fleisches, hereinbrachtet, daß sie in Meinem Heiligtum sein sollten, Mein Haus zu entweihen, indem ihr Mein Brot, das Fett und das Blut darbrachtet, und Meinen Bund mit allen euren Greueln zunichte machtet.',
        8: 'Und nicht selbst die Hut Meiner Heiligtümer hütet, und sie euch zu Hütern der Hut Meines Heiligtums setztet.',
        9: 'So spricht der Herr Jehovah: Kein Sohn des Auslandes, unbeschnittenen Herzens und unbeschnittenen Fleisches, soll kommen in Mein Heiligtum, von allen Söhnen des Auslandes, die inmitten der Söhne Israels sind.',
        10: 'Noch die Leviten, die sich von Mir entfernten bei der Abirrung Israels, das von Mir abirrte ihren Götzen nach; und sie sollen tragen ihre Missetat.',
        11: 'Und sie sollen in Meinem Heiligtum Dienste tun, bestellt über die Tore des Hauses, und im Hause Dienste tun, sie sollen das Brandopfer und das Schlachtopfer schlachten für das Volk und vor ihnen stehen, um ihnen Dienst zu tun.',
        12: 'Weil sie ihnen Dienst taten vor ihren Götzen, und dem Hause Israels ein Anstoß zur Missetat wurden, darum habe Ich Meine Hand aufgehoben über sie, spricht der Herr Jehovah, daß sie ihre Missetat tragen sollen,',
        13: 'Und sie dürfen nicht zu Mir hinzutreten, um Mir Priesterdienst zu tun, noch herzutreten zu irgendeinem Meiner Heiligtümer, zu dem Heiligen des Heiligen, daß ihre Schande sie tragen und ihre Greuel, die sie taten.',
        14: 'Und Ich gebe sie, die Hut des Hauses zu hüten für allen Dienst desselben, und was darinnen ist zu tun.',
        15: 'Und die Priester, die Leviten, Zadoks Söhne, welche die Hut Meines Heiligtums hüteten, indes die Söhne Israels von Mir abirrten, sie sollen Mir nahen, Mir Dienst zu tun, und sollen vor Mir stehen, Mir Fett und Blut darzubringen, spricht der Herr Jehovah.',
        16: 'Sie sollen in Mein Heiligtum eingehen, und sie nahen Meinem Tisch, um Mir Dienst zu tun, und hüten Meine Hut.',
        17: 'Und soll geschehen, wenn sie zu den Toren des inneren Vorhofes eingehen, sollen sie leinene Kleider anziehen, und keine Wolle soll auf sie kommen, wenn sie in den Toren des inneren Vorhofs und im Hause Dienst tun.',
        18: 'Leinene Kopfbünde sollen auf ihrem Haupte sein, und leinene Beinkleider sollen an ihren Lenden sein, sie sollen sich nicht im Schweiße gürten.',
        19: 'Und wenn sie in den äußeren Hof hinausgehen, in den äußeren Vorhof zum Volk, sollen sie ausziehen ihre Kleider, in denen sie Dienst getan, und sie in den Zellen der Heiligkeit niederlegen und andere Kleider anziehen, auf daß sie nicht das Volk durch ihre Kleider heiligen.',
        20: 'Und sie sollen ihr Haupt nicht bescheren, aber das Haar auch nicht frei wachsen lassen, verschneiden sollen sie ihre Häupter.',
        21: 'Und Wein soll kein Priester trinken, wenn in den inneren Vorhof sie eingehen.',
        22: 'Und eine Witwe und eine Verstoßene sollen sie sich nicht zu Weibern nehmen, sondern Jungfrauen aus dem Samen des Hauses Israel; aber eine Witwe, die eines Priesters Witwe ist, mögen sie nehmen.',
        23: 'Und sollen unterweisen Mein Volk in dem Unterschied zwischen dem Heiligen und dem Gemeinen, und den zwischen Unreinem und Reinem ihnen zu wissen tun.',
        24: 'Und im Rechtsstreite sollen sie stehen, zu richten nach Meinen Rechten; sie sollen ihn richten. Und Meine Gesetze und Meine Satzungen sollen sie halten bei allen Meinen Festzeiten, und heiligen Meine Sabbathe.',
        25: 'Und zu einem toten Menschen sollen sie nicht hineinkommen und sich verunreinigen; nur bei Vater und bei Mutter und bei Sohn und bei Tochter, bei Bruder und bei Schwestern, die keinen Mann gehabt haben, mögen sie sich verunreinigen.',
        26: 'Und nach seiner Reinigung sollen sie ihm sieben Tage zählen.',
        27: 'Und an dem Tage, da er zum Heiligtum, zum inneren Vorhof hereinkommt, um Dienst zu tun im Heiligtum, soll er sein Sündopfer darbringen, spricht der Herr Jehovah.',
        28: 'Und ihr Erbe, das sie haben sollen: Ich bin ihr Erbe. Und ihr sollt ihnen kein Eigentum geben in Israel: Ich bin ihr Eigentum.',
        29: 'Das Speiseopfer und das Sündopfer und das Schuldopfer, die sollen sie essen, und alles Verbannte in Israel soll ihnen sein.',
        30: 'Und die Erstlinge von allen Erstgeburten, von allem, und alles Hebeopfer von allem, von euren Hebeopfern sollen die Priester haben, und die Erstlinge eures Teiges gebt dem Priester, auf daß Segen ruhe auf deinem Haus.',
        31: 'Alles Gefallene und Zerfleischte vom Gevögel und vom Vieh sollen die Priester nicht essen.',
    },
    45: {
        1: 'Und wenn ihr das Land durch das Los verteilt zum Erbe, sollt ihr für Jehovah eine Hebe heben als Heiliges vom Land, die Länge sei fünfundzwanzigtausend in die Länge, und die Länge zehntausend. Heilig sei es in all seiner Grenze ringsum.',
        2: 'Von diesem sei für das Heiligtum fünfhundert bei fünfhundert ins Gevierte ringsum und fünfzig Ellen sei sein Weichbild ringsum.',
        3: 'Und sollst von diesem Maß messen in die Länge fünfundzwanzigtausend und in die Breite zehntausend, und darauf soll das Heiligtum, das Heilige des Heiligen sein.',
        4: 'Das Heiligtum vom Lande ist für die Priester, die Diener des Heiligtums; die zum Dienst tun Jehovah nahen, und ihnen sei es zum Orte für Häuser und das Geheiligte als Heiligtum.',
        5: 'Und fünfundzwanzigtausend in die Länge und zehntausend in die Breite soll für die Leviten sein, die Diener des Hauses, ihnen zum Eigentum für zwanzig Zellen.',
        6: 'Und als Eigentum der Stadt sollt ihr geben fünftausend in die Breite und in die Länge fünfundzwanzigtausend entlang der Hebe für das Heiligtum. Es sei für das ganze Haus Israel;',
        7: 'Und für den Fürsten sei hüben und drüben von der Hebe des Heiligtums und dem Eigentum der Stadt, vor der Hebe des Heiligtums und vor dem Eigentum der Stadt, von der Meeresseite dem Meere zu, und von der Ostseite dem Osten zu; und die Länge sei entlang einem der Teile von der Grenze meerwärts bis zur Grenze ostwärts.',
        8: 'Es sei ihm zum Lande, zum Eigentum in Israel; und nicht mehr sollen Meine Fürsten Mein Volk bedrücken und sollen das Land dem Hause Israels geben für seine Stämme.',
        9: 'So spricht der Herr Jehovah: Es ist genug für euch, ihr Fürsten Israels. Tut weg Gewalttat und Verheerung, und tut Recht und Gerechtigkeit, und hebt auf eure Austreibungen von Meinem Volk, spricht der Herr Jehovah.',
        10: 'Eine Waage der Gerechtigkeit und ein Ephah der Gerechtigkeit und ein Bath der Gerechtigkeit seien bei euch.',
        11: 'Ephah und Bath sollen ein Maß sein, so daß man das Bath als ein Zehntel vom Chomer halte und das Ephah den Zehntel des Chomers. Nach dem Chomer soll sein ihr Maß.',
        12: 'Und ein Schekel sei zwanzig Gerah, und zwanzig Schekel, fünfundzwanzig Schekel, fünfzehn Schekel sei bei euch die Mine.',
        13: 'Das soll die Hebe sein, die ihr hebet: Ein Sechstel Ephah von dem Chomer Weizen, und ein Sechstel Ephah von dem Chomer Gerste.',
        14: 'Und die Satzung vom Öl, das Bath Öl, der zehnte Teil des Baths vom Cor. Zehn Bath sind ein Chomer; denn zehn Bath machen ein Chomer;',
        15: 'Und ein Schaf von der Herde von zweihundert von den bewässerten Wiesen Israels zum Speiseopfer und zum Brandopfer und zu Dankopfern, um für sie zu sühnen, spricht der Herr Jehovah.',
        16: 'Alles Volk im Lande sei für diese Hebe an den Fürsten in Israel.',
        17: 'Und auf dem Fürsten seien die Brandopfer und das Speiseopfer und das Trankopfer an den Festen und an den Neumonden und an den Sabbathen bei allen Festversammlungen des Hauses Israel. Er soll das Sündopfer und das Speiseopfer und das Brandopfer und die Dankopfer bringen, zu sühnen für das Haus Israel.',
        18: 'So spricht der Herr Jehovah: Im ersten am ersten des Monats sollst du einen Farren nehmen, ein junges Rind, ohne Fehl, und das Heiligtum entsündigen.',
        19: 'Und der Priester soll von dem Blut des Sündopfers nehmen und an die Türpfosten des Hauses und an die vier Ecken der Einfassung des Altars und an die Türpfosten am Tor des inneren Vorhofs sprengen.',
        20: 'Und du sollst also tun am siebenten des Monats wegen des Mannes, der sich versehen, und wegen des Einfältigen, auf daß ihr sühnt für das Haus.',
        21: 'Im ersten, am vierzehnten Tag des Monats soll bei euch das Paschah sein, das Fest der sieben Tage; Ungesäuertes sollt ihr essen.',
        22: 'Und am selben Tage soll der Fürst für sich und für das ganze Volk des Landes einen Farren als Sündopfer bringen.',
        23: 'Und die sieben Tage des Festes soll er als Brandopfer Jehovah sieben Farren opfern und sieben Widder ohne Fehl die sieben Tage täglich, und als Sündopfer einen Bock der Ziegen täglich.',
        24: 'Und als Speiseopfer soll er ein Ephah für den Farren und ein Ephah für den Widder und für das Ephah ein Hin Öl nehmen.',
        25: 'Im siebenten, am fünfzehnten Tag des Monats soll er am Feste dasselbe tun, sieben Tage, nach dem Sündopfer, nach dem Brandopfer und nach dem Speiseopfer und nach dem Öl..',
    },
    46: {
        1: 'So spricht der Herr Jehovah: Das Tor des inneren Vorhofs, das gegen Osten ist gewendet, soll die sechs Werktage geschlossen sein, aber am Sabbathtage soll es geöffnet werden; auch am Tag des Neumonds soll es geöffnet werden.',
        2: 'Und der Fürst soll eingehen des Weges durch die Halle des äußeren Tores, und stehen an dem Türpfosten des Tores, und die Priester sollen zurichten sein Brandopfer und seine Dankopfer, und er soll an der Schwelle des Tores anbeten und hinausgehen, und das Tor soll bis zum Abend nicht geschlossen werden.',
        3: 'Und das Volk des Landes soll am Eingang desselben Tores anbeten vor Jehovah an den Sabbathen und an den Neumonden.',
        4: 'Und das Brandopfer, das der Fürst Jehovah darbringen soll am Tag des Sabbaths, sind sechs Lämmer ohne Fehl und ein Widder ohne Fehl.',
        5: 'Und das Speiseopfer: ein Ephah auf den Widder, und zu den Lämmern ein Speiseopfer, eine Gabe seiner Hand und ein Hin Öl auf das Ephah;',
        6: 'Und am Tag des Neumonds seien es ein Farren, ein junges Rind ohne Fehl und sechs Lämmer und ein Widder ohne Fehl.',
        7: 'Und ein Ephah auf den Farren und ein Ephah auf den Widder soll er als Speiseopfer bringen, und für die Lämmer, wie seine Hand reichen mag, und ein Hin Öl auf das Ephah.',
        8: 'Und wenn der Fürst eingeht, soll er des Weges der Vorhalle des Tores eingehen und herausgehen seines Weges.',
        9: 'Und wenn das Volk des Landes hineingeht vor Jehovah an den Feiertagen, soll, wer des Weges durch das Tor der Mitternacht eingeht, um anzubeten, herausgehen auf dem Weg des Tores nach Mittag, und wer auf dem Weg des Tores nach Mittag ist eingegangen, gehe hinaus auf dem Weg des Tores nach Mitternacht. Er kehre nicht zurück auf dem Weg des Tores, auf dem er eingegangen ist, sondern gehe stracks vor sich hinaus.',
        10: 'Der Fürst aber soll in der Mitte der Einziehenden einziehen, und wenn sie ausziehen, sollen sie ausziehen.',
        11: 'Und an den Festen und an den Feiertagen sei das Speiseopfer ein Ephah für den Farren und ein Ephah für den Widder, und für die Lämmer eine Gabe seiner Hand, und Öls ein Hin für das Ephah.',
        12: 'Und wenn der Fürst als Freiwillgabe ein Brandopfer oder Dankopfer Jehovah freiwillig machen will, so öffne man ihm das Tor, das nach Osten gewendet ist, und er mache sein Brandopfer und seine Dankopfer, wie er am Sabbathtage tut, und er gehe hinaus und man schließe das Tor, nachdem er hinausgegangen ist.',
        13: 'Und ein einjährig Lamm ohne Fehl sollst du täglich dem Jehovah als Brandopfer machen; Morgen für Morgen sollst du es machen.',
        14: 'Und als Speiseopfer sollst du darauf Morgen für Morgen das Sechstel eines Ephah tun, und Öl ein Drittel Hin, das Semmelmehl damit zu beträufeln, dem Jehovah als Speiseopfer, ewige Satzungen beständiglich.',
        15: 'Und sie sollen das Lamm und das Speiseopfer und das Öl Morgen für Morgen als ein beständig Brandopfer bringen.',
        16: 'So spricht der Herr Jehovah: Wenn der Fürst einem Manne von seinen Söhnen eine Gabe gibt, so ist sie sein Erbe, es ist für seine Söhne. Ihr Eigentum ist es als Erbe.',
        17: 'Wenn er aber an einen von seinen Knechten eine Gabe von seinem Erbe gibt, so soll es ihm sein bis zum Jahr der Freilassung, und es kommt zurück an den Fürsten. Allein sein Erbe soll für seine Söhne sein.',
        18: 'Und der Fürst soll nichts nehmen von dem Erbe des Volkes, sie zu verdrängen aus ihrem Eigentum. Aus seinem Eigentum soll er seinen Söhnen Erbe geben, auf daß Mein Volk nicht zerstreut werde, der Mann aus seinem Eigentum.',
        19: 'Und der Engel brachte mich in den Eingang zur Seite des Tores zu den Zellen des Heiligtums, zu denen der Priester, die der Mitternacht sind zugewendet; und siehe, da war ein Ort an ihren Seiten gegen das Meer.',
        20: 'Und er sprach zu mir: Dies ist der Ort, allwo die Priester das Schuldopfer und das Sündopfer kochen, wo sie das Speiseopfer backen, auf daß sie es nicht in den äußeren Hof hinausbringen, um das Volk zu heiligen.',
        21: 'Und er brachte mich hinaus in den äußeren Vorhof und ließ mich herumgehen nach den vier Winkeln des Vorhofs, und siehe, ein Vorhof war in dem Winkel des Vorhofs, ein Vorhof in dem Winkel des Vorhofs;',
        22: 'In den vier Winkeln des Vorhofs Vorhöfe mit Rauchfängen, vierzig in der Länge und dreißig in der Breite. Ein Maß war für die viere in den Winkeln.',
        23: 'Und eine Einfriedung war ringsum an ihnen, rings um die viere; und Kochherde gemacht unter den Einfriedungen ringsum.',
        24: 'Und er sprach zu mir: Dies ist das Haus der Küchen, darin des Hauses Diener kochen das Schlachtopfer des Volkes.',
    },
    47: {
        1: 'Und er brachte mich zurück an den Eingang des Hauses. Und siehe, Wasser kamen heraus unter der Schwelle des Hauses gegen Osten; denn des Hauses Vorderseite ist gegen Osten, und die Wasser kamen herab unter der rechten Seite des Hauses, zu Mittag vom Altar.',
        2: 'Und er brachte mich heraus des Weges durch das Tor gegen Mitternacht, und er ließ mich den äußeren Weg herumgehen zum äußeren Tor, auf dem Weg gegen Osten gewendet, und siehe, die Wasser quollen von der rechten Seite hervor.',
        3: 'Als der Mann hinausging gegen Osten, da war eine Meßschnur in seiner Hand, und er maß tausend mit der Elle, und führte mich durch die Wasser: Wasser der Knöchel.',
        4: 'Und er maß tausend und führte mich durch die Wasser hindurch: Wasser der Knie; und er maß tausend, und führte mich hindurch: Wasser der Lenden.',
        5: 'Und er maß tausend; ein Bach, durch den ich nicht hindurchgehen konnte; denn die Wasser waren hoch, Wasser zum Schwimmen, ein Bach, da man nicht hindurchgehen konnte.',
        6: 'Und er sprach zu mir: Siehst du, Menschensohn? Und er führte mich und brachte mich zurück an das Ufer des Baches.',
        7: 'Als ich zurückkam, da siehe, es waren am Ufer des Baches sehr viele Bäume hüben und drüben.',
        8: 'Und er sprach zu mir: Diese Wasser fließen hinaus zum östlichen Umkreis, und kommen hinab auf das Blachfeld, und kommen zum Meere; und werden sie in das Meer hinausgeführt, so werden die Wasser geheilt.',
        9: 'Und geschehen wird, daß jegliche lebendige Seele, die da kreucht, wohin die Bäche kommen, lebt, und der Fische sehr viel sein wird; weil diese Wasser dahin kommen, so werden sie geheilt, und alles lebt, wohin der Bach wird kommen.',
        10: 'Und es wird geschehen, daß Fischer werden daran stehen; von Engedi bis Enegla- jim werden sie Garne ausbreiten; und nach seiner Art wird ihr Fisch sein, wie der Fisch des großen Meeres, sehr viel.',
        11: 'Seine Lachen und seine Pfützen werden nicht geheilt, sie sind dem Salze übergeben.',
        12: 'Und an dem Bache steigen auf hüben und drüben an seinem Ufer jeglicher Baum zur Speise. Nicht welkt sein Blatt, und seine Frucht geht nicht zu Ende; gemäß seinen Monaten treibt er Erstlinge; denn seine Wasser gehen aus vom Heiligtum. Und seine Frucht ist zum Essen und sein Blatt zur Arznei.',
        13: 'So spricht der Herr Jehovah: Dies ist die Grenze, zu der ihr das Land zum Erbe verteilen sollt an die zwölf Stämme Israels: Für Joseph Schnüre.',
        14: 'Und ihr sollt es erben, der eine Mann, wie sein Bruder, weil Ich Meine Hand aufhob, es euren Vätern zu geben, darum dies Land euch zum Erbe fallen soll.',
        15: 'Und dies ist des Landes Grenze: Auf der Seite nach Mitternacht, vom großen Meer an, des Weges nach Chethlon, wo man nach Zedad kommt;',
        16: 'Chamath, Berothah, Sibraim, das zwischen der Grenze von Damask und zwischen der Grenze von Chamath ist, das mittlere Chazer an der Grenze Chaurans.',
        17: 'Und die Grenze sei vom Meere aus nach Chazar, Enon, die Grenze von Damask, und die von Mitternacht, gen Mitternacht, und die Grenze Chamaths: und das ist die Seite gen Mitternacht.',
        18: 'Und die Seite gegen Osten ist zwischen Chauran und zwischen Damask und zwischen Gilead, und zwischen dem Lande Israels der Jordan. Von der Grenze gegen das östliche Meer sollt ihr messen. Und das ist die Seite nach Osten.',
        19: 'Und die Seite gen Mittag sei südwärts, von Thamar bis zum Haderwasser Kadesch, nach dem Bache, dem großen Meere zu, und dies sei die Südseite mittagwärts.',
        20: 'Und die Seite des Meeres ist das große Meer von der Grenze bis gegenüber von da, wo man nach Chamath kommt; das ist die Seite nach dem Meere.',
        21: 'Und ihr sollt dieses Land unter euch, die Stämme Israels, verteilen.',
        22: 'Und es soll geschehen, daß ihr es als Erbe zufallen lasset euch und den Fremdlingen, die in eurer Mitte weilen und Söhne gezeugt haben in eurer Mitte; und sie sollen euch wie Eingeborene sein unter den Söhnen Israels, mit euch soll ihnen das Erbe fallen inmitten der Stämme Israels.',
        23: 'Und es soll geschehen, daß in dem Stamme, da der Fremdling verweilt, ihr ihm dort sein Erbe gebet, spricht der Herr Jehovah.',
    },
    48: {
        1: 'Und das sind die Namen der Stämme: Vom Ende gen Mitternacht, zur Seite des Weges nach Chethlon, wo man kommt gen Chamath, Chazar Enan an der Grenze von Damask, mitternachtwärts, zur Seite Chamaths von der Ostecke zum Meere ist eins für Dan.',
        2: 'Und an der Grenze Dans von der Ostecke bis zur Ecke meerwärts, hat Ascher eines.',
        3: 'Und an der Grenze Aschers von der Ostecke bis zur Ecke meerwärts hat Naphthali eines.',
        4: 'Und an der Grenze Naphthalis von der Ostecke bis zur Ecke meerwärts hat Menascheh eines.',
        5: 'Und an der Grenze Menaschehs von der Ecke ostwärts bis zur Ecke meerwärts hat Ephraim eines.',
        6: 'Und an der Grenze Ephraims von der Ecke ostwärts und bis zur Ecke meerwärts hat Ruben eines.',
        7: 'Und an der Grenze Rubens von der Ostecke bis zur Ecke meerwärts hat Jehudah eines.',
        8: 'Und an der Grenze Jehudahs von der Ostecke bis zur Ecke meerwärts soll die Hebe sein, die ihr heben sollt, fünfundzwanzigtausend in die Breite, und in die Länge wie einer der Teile von der Ecke ostwärts bis zur Ecke meerwärts, und in seiner Mitte sei das Heiligtum.',
        9: 'Die Hebe, die ihr Jehovah hebet, soll in die Länge fünfundzwanzigtausend und in die Breite zehntausend sein.',
        10: 'Und für diese soll die Hebe der Heiligkeit sein den Priestern, gegen Mitternacht fünfundzwanzigtausend und gegen das Meer zehntausend in die Breite, und gegen Osten zehntausend in die Breite, und gegen Mittag in die Länge fünfundzwanzigtausend, und in ihrer Mitte sei Jehovahs Heiligtum.',
        11: 'Es soll sein für die Priester, die geheiligt sind von den Söhnen Zadoks, welche die Hut gehütet, die nicht abgeirrt, als die Söhne Israels abirrten, wie die Leviten abgeirrt.',
        12: 'Und eine Hebe von der Hebe des Landes soll ihnen sein, das Heilige des Heiligen bei der Grenze der Leviten.',
        13: 'Und die Leviten sollen haben der Grenze der Priester entlang fünfundzwanzigtausend in die Länge, und in die Breite zehntausend. Die ganze Länge soll sein fünfundzwanzigtausend und die Breite zehntausend;',
        14: 'Und sollen nichts davon verkaufen noch vertauschen, noch veräußern das Erstling des Landes, denn Heiligkeit ist es dem Jehovah.',
        15: 'Und die fünftausend, die übrig sind in der Breite vorn an den fünfundzwanzigtausend, sollen gemeines Land sein, für die Stadt zum Wohnen und zum Weichbilde, und die Stadt sei in der Mitte.',
        16: 'Und das sind ihre Maße: Die Mitternachtseite viertausendfünfhundert, und die Mittagseite viertausendfünfhundert, und die Ostseite viertausendfünfhundert, und die Meerseite viertausendfünfhundert.',
        17: 'Und das Weichbild der Stadt soll sein gen Mitternacht zweihundertfünfzig, und gen Mittag zweihundertfünfzig, und gen Osten zweihundertfünfzig, und gegen das Meer zweihundertfünfzig.',
        18: 'Und was neben der Hebe des Heiligtums noch übrigbleibt in der Länge entlang der Hebe der Heiligkeit, zehntausend gegen Osten und zehntausend dem Meere zu, und ist entlang der Hebe des Heiligtums, dessen Ertrag sei zum Brot für die, welche der Stadt dienen.',
        19: 'Und die, so in der Stadt dienen, sollen aus allen Stämmen Israels ihr dienen.',
        20: 'Die ganze Hebe sei fünfundzwanzigtausend bei fünfundzwanzigtausend; als Geviertes sollt ihr die Hebe des Heiligtums heben zum Eigentum der Stadt.',
        21: 'Und das übrige sei für den Fürsten hüben und drüben an der Hebe der Heiligkeit und am Eigentum der Stadt vorn an den fünfundzwanzigtausend der Hebe bis zur Grenze gen Osten und meerwärts, vor den fünfundzwanzigtausend bei der Grenze meerwärts, den Teilen entlang sei für den Fürsten; und die Hebe der Heiligkeit und das Heiligtum des Hauses seien in dessen Mitte.',
        22: 'Und von dem Eigentum der Leviten, vom Eigentum der Stadt, die inmitten dessen sind, das des Fürsten ist, zwischen der Grenze Jehudahs und der Grenze Benjamins, das sei des Fürsten.',
        23: 'Und von den übrigen Stämmen von der Ecke ostwärts bis zur Ecke meerwärts hat Benjamin einen;',
        24: 'Und an der Grenze Benjamins von der Ecke ostwärts bis zur Ecke meerwärts hat Simeon einen;',
        25: 'Und an der Grenze Simeons von der Ecke ostwärts bis zur Ecke meerwärts hat Jissaschar einen;',
        26: 'Und an der Grenze Jissaschars von der Ecke ostwärts bis zur Ecke meerwärts hat Sebulon einen;',
        27: 'Und an der Grenze Sebuluns von der Ecke ostwärts bis zur Ecke meerwärts hat Gad einen.',
        28: 'Und an der Grenze Gads auf der Seite gen Mittag südlich sei die Grenze von Thamar bis zum Haderwasser, von Kadesch bis gegen den Bach hin zum großen Meer.',
        29: 'Dies ist das Land, das ihr als Erbe den Stämmen Israels zufallen lassen sollt, und dies sind ihre Teile, spricht der Herr Jehovah.',
        30: 'Und dies sind die Ausgänge der Stadt: von der Ecke der Mitternacht viertausendfünfhundert sei ihr Maß.',
        31: 'Und die Tore der Stadt seien nach dem Namen der Stämme Israels: drei Tore gen Mitternacht, ein Tor Ruben, ein Tor Jehudah, ein Tor Levi.',
        32: 'Und auf der Ecke gen Osten viertausendfünfhundert; und drei Tore, und zwar: Tor Joseph eines, Tor Benjamin eines und Tor Dan eines.',
        33: 'Und auf der Mittagseite viertausendfünfhundert das Maß, und drei Tore: Tor Schimeon eines, Tor Jissaschar eines, Tor Sebulun eines.',
        34: 'Die Seite nach dem Meer viertausendfünfhundert. Ihrer Tore sind drei: ein Tor Gad, ein Tor Ascher, Naphthali ein Tor.',
        35: 'Ringsum achtzehntausend, und der Name der Stadt sei von dem Tage an Jehovah allda!.',
    },
}
